window.QUESTIONS = [{"id": 1,"q": "Szyb kablowy jest to, zgodnie z treścią definicji zawartej w zaktualizowanej w 2014 r. Normie Stowarzyszenia Elektryków Polskich N SEP-E 004 pt. „Elektroenergetyczne i sygnalizacyjne linie kablowe. Projektowanie i budowa”, obudowane przejście przeznaczone do ułożenia w nim kabli, łączące więcej niż:","options": {"a": "dwie kondygnacje budynku,","b": "trzy kondygnacje budynku,","c": "pięć kondygnacji budynku."},"category": "Ewakuacja"},{"id": 2,"q": "Przepisy przeciwpożarowe wymagają, aby stałe samoczynne urządzenia gaśnicze wodne było stosowane w:","options": {"a": "budynkach służących celom gastronomicznym o liczbie miejsc powyżej 600,","b": "budynkach, w których występuje strefa pożarowa służąca celom gastronomicznym o liczbie miejsc powyższej 600,","c": "budynkach służących celom gastronomicznym o liczbie miejsc powyżej 300."},"category": "Strefy pożarowe i oddzielenia"},{"id": 3,"q": "Zgodnie z Polską Normą PN-EN 12845 „Stałe urządzenia gaśnicze. Urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja”, oddzielenie między przestrzenią chronioną urządzeniem tryskaczowym i przestrzenią niechronioną powinno mieć odporność ogniową wymaganą dla ścian i stropów oddzieleń przeciwpożarowych, przy czym nie mniejszą niż:","options": {"a": "30 min,","b": "60 min,","c": "120 min."},"category": "Odporność ogniowa i klasy budynków"},{"id": 4,"q": "Podłogi podniesione o więcej niż 0,2 m ponad poziom stropu, znajdujące się w strefie pożarowej ZL II w budynku niskim użyteczności publicznej, powinny mieć klasę odporności ogniowej nie mniejszą niż:","options": {"a": "EI 60,","b": "EI 30,","c": "nie wymagają klasy odporności ogniowej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 5,"q": "Wymagania stawiane obiektom widowiskowym (PN-EN 13200-1:2013 Obiekty widowiskowe. Część 1: Ogólna charakterystyka widowni) w zakresie ewakuacji, w przypadku obszarów na wolnym powietrzu, zalecają, aby widzowie byli w stanie osiągnąć miejsce bezpieczne, w ciągu:","options": {"a": "2 minut,","b": "8 minut,","c": "12 minut."},"category": "Ewakuacja"},{"id": 6,"q": "W budynku z przekryciem dachu wykonanym z materiałów niepalnych ściany oddzielenia przeciwpożarowego:","options": {"a": "należy wyprowadzić ponad pokrycie dachu na wysokość co najmniej 0,3 m lub zastosować wzdłuż ściany pas z materiału niepalnego o szerokości co najmniej 1 m i klasie odporności ogniowej EI 60, bezpośrednio pod pokryciem,","b": "należy wyprowadzić ponad pokrycie dachu na wysokość co najmniej 0,3 m lub zastosować wzdłuż ściany pas z materiału niepalnego o szerokości co najmniej 2 m i klasie odporności ogniowej EI 60, bezpośrednio pod pokryciem,","c": "można wznieść do poziomu pokrycia bez konieczności zastosowania dodatkowych zabezpieczeń."},"category": "Odporność ogniowa i klasy budynków"},{"id": 7,"q": "Zgodnie z wymaganiami rozporządzenia Ministra Infrastruktury w sprawie przepisów techniczno – budowlanych dotyczących autostrad płatnych, przejazdy awaryjne przez pas dzielący jezdnie autostrady, co do zasady, powinny być wykonane w odstępach nie większych niż:","options": {"a": "3 km,","b": "4 km,","c": "5 km."},"category": "Drogi pożarowe i dojazd"},{"id": 8,"q": "Zastosowanie stałego samoczynnego urządzenia gaśniczego mgłowego w budynku jednokondygnacyjnym zakwalifikowanym do kategorii zagrożenia ludzi ZL I nie upoważnia do:","options": {"a": "powiększenia powierzchni strefy pożarowej o 100%","b": "obniżenia klasy odporności pożarowej budynku,","c": "wydłużenia o 50% dopuszczalnej długości przejścia ewakuacyjnego."},"category": "Ewakuacja"},{"id": 9,"q": "Celem stosowania instalacji tryskaczowych ESFR jest:","options": {"a": "kontrola pożaru,","b": "ugaszenie pożaru,","c": "wobec nieokreślenia wymagań prawnych w przedmiotowym zakresie, wspomnianego celu nie określa się."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 10,"q": "Skuteczność gaszenia gazem gaśniczym wymaga nie tylko uzyskania odpowiedniego stężenia gazu w chronionym pomieszczeniu, ale również utrzymania tego stężenia przez określony czas. Jest to czas retencji, który zgodnie z PN-EN 15004 powinien wynosić:","options": {"a": "nie mniej niż 10 minut,","b": "co najmniej 5 minut lub do przyjmowanego momentu podjęcia działań ratowniczych przez przeszkolony personel, w zależności od tego, który jest krótszy,","c": "obliczany jest indywidualnie w każdym projekcie w funkcji szczelności pomieszczenia oraz różnicy gęstości między mieszaniną gaz gaśniczy – powietrze wewnątrz pomieszczenia a gęstością powietrza na zewnątrz chronionego pomieszczenia."},"category": "Pozostałe / ogólne"},{"id": 11,"q": "Klasyfikacja w zakresie reakcji na ogień B2ca,s1,d0, a1 dotyczy następujących wyrobów budowlanych :","options": {"a": "kabli elektroenergetycznych zasilających,","b": "konstrukcji kanałów kablowych,","c": "systemu kominowego wg PN EN 1443:2005 w zakresie odporności na pożar sadzy."},"category": "Reakcja na ogień i materiały"},{"id": 12,"q": "Parametrem warunkującym usytuowanie ze względu na bezpieczeństwo pożarowe garażu zamkniętego i otwartego jest:","options": {"a": "gęstość obciążenia ogniowego do 1000 MJ/m2,","b": "gęstość obciążenia ogniowego do 500 MJ/m2,","c": "powierzchnia strefy pożarowej."},"category": "Strefy pożarowe i oddzielenia"},{"id": 13,"q": "W budynku hali magazynowej o wysokości 12,70 m można zastosować ogrzewanie za pomocą promienników zasilanych gazem propan-butan:","options": {"a": "tak, pod warunkiem obniżenia wysokości zamocowania promienników na wysokości poniżej 12 m,","b": "nie, ponieważ dopuszcza się tego rodzaju ogrzewanie tylko w budynkach niskich,","c": "tak, pod warunkiem uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej."},"category": "Pozostałe / ogólne"},{"id": 14,"q": "Minimalna odległość miedzy instalowanymi tryskaczami powinna wynosić:","options": {"a": "3 m,","b": "2 m z dopuszczalnymi wyjątkami,","c": "zawsze 50 % maksymalnej odległości między tryskaczami."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 15,"q": "Jednym z elementów oceny zagrożenia wybuchem w świetle wymagań przepisów przeciwpożarowych jest:","options": {"a": "określenie zasięgów fali nadciśnienia powstałego w trakcie wybuchu,","b": "opracowanie klasyfikacyjnej dokumentacji graficznej,","c": "obliczenie wielkości ryzyka dla pracowników zatrudnionych na stanowiskach, na których występuje zagrożenie wybuchem."},"category": "Zagrożenie wybuchem"},{"id": 16,"q": "Wewnętrzną instalację wodociągową przeciwpożarową (hydranty wewnętrzne) można podłączyć do instalacji urządzenia tryskaczowego wodnego:","options": {"a": "tak, pod warunkiem, że pobór wody dla instalacji hydrantów następował będzie przed zaworami kontrolno-alarmowymi poprzez armaturę odcinającą możliwie najbliżej punktu podłączenia instalacji tryskaczowej do zasilania wodnego.","b": "nie można, gdyż polskie przepisy przeciwpożarowe nie dopuszczają takiego rozwiązania","c": "tak – pod warunkiem, że łączny pobór wody przez hydranty wewnętrzne nie przekracza 300 dm3/min."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 17,"q": "W świetle Normy N SEP-E-005, ręczny przycisk uruchamiający przeciwpożarowy wyłącznik prądu (PWP) powinien być:","options": {"a": "koloru żółtego,","b": "koloru czerwonego,","c": "koloru niebieskiego."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 18,"q": "Prowadzenie przedszkola wielooddziałowego, powstałego w wyniku przekształcenia dotychczasowego oddziału przedszkolnego, jest dopuszczalne w lokalu znajdującym się w użytkowanym budynku szkoły lub jego części niespełniających wymagań określonych w przepisach techniczno-budowlanych oraz przepisów o ochronie przeciwpożarowej dla kategorii ZL II lub wymagań uzgodnionych z właściwym miejscowo komendantem wojewódzkim Państwowej Straży Pożarnej w trybie określonym w tych przepisach, m.in. pod warunkiem jego oddzielenia od pozostałej części budynku:","options": {"a": "ścianami wewnętrznymi o klasie odporności ogniowej co najmniej EI 30, w których otwory mają zamknięcia o klasie odporności ogniowej co najmniej EI 30 i są wyposażone w urządzenia zapewniające samoczynne zamykanie otworu w czasie pożaru,","b": "ścianami wewnętrznymi o klasie odporności ogniowej co najmniej EI 60, w których otwory mają zamknięcia o klasie odporności ogniowej co najmniej EI 60 i są wyposażone w urządzenia zapewniające samoczynne zamykanie otworu w czasie pożaru,","c": "ścianami wewnętrznymi o klasie odporności ogniowej co najmniej EI 60, w których otwory mają zamknięcia o klasie odporności ogniowej co najmniej EI 30 i są wyposażone w urządzenia zapewniające samoczynne zamykanie otworu w czasie pożaru."},"category": "Odporność ogniowa i klasy budynków"},{"id": 19,"q": "Przeciwpożarowy wyłącznik prądu odcinający dopływ energii elektrycznej do wszystkich odbiorników na stacji metra, z wyjątkiem obwodów zasilających instalacje i urządzenia, których funkcjonowanie jest niezbędne w czasie pożaru i prowadzenia akcji ratowniczo- gaśniczej instalowany jest:","options": {"a": "w dyspozytorni stacji,","b": "przy wyjściu z peronu pasażerskiego,","c": "przy ostatnim wyjściu ze stacji metra."},"category": "Ewakuacja"},{"id": 20,"q": "Agregat prądotwórczy stanowiący awaryjne źródło energii elektrycznej dla zasilania instalacji bezpieczeństwa metra, które powinny działać w czasie pożaru, powinien zapewniać dostarczenie energii przez czas nie mniejszy niż:","options": {"a": "60 min.,","b": "120 min.,","c": "180 min."},"category": "Pozostałe / ogólne"},{"id": 21,"q": "Zastosowanie stałego samoczynnego urządzenia gaśniczego wodnego w budynku o wysokości 30 m, zaliczonym do kategorii zagrożenia ludzi ZL III i zaprojektowanym wstępnie w klasie odporności pożarowej B:","options": {"a": "umożliwia obniżenie klasy odporności pożarowej do klasy C,","b": "umożliwia obniżenie klasy odporności pożarowej do klasy D,","c": "nie stanowi przesłanki umożliwiającej obniżenie klasy odporności pożarowej budynku."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 22,"q": "W budynku zakwalifikowanym do kategorii ZL V zagrożenia ludzi, długość poziomej drogi ewakuacyjnej od wyjścia z obudowanej klatki schodowej, zamykanej drzwiami o klasie odporności ogniowej co najmniej EI 30 i wyposażonej w urządzenia służące do usuwania dymu, do wyjścia na zewnątrz nie może przekroczyć przy jednym dojściu:","options": {"a": "40 m,","b": "20 m,","c": "10 m."},"category": "Ewakuacja"},{"id": 23,"q": "Polska Norma PN-EN ISO 7010:2012 Symbole graficzne – Barwy bezpieczeństwa i znaki bezpieczeństwa – Zarejestrowane znaki bezpieczeństwa, zastąpiła Polską Normę:","options": {"a": "PN-N-01256-4:1997 Znaki bezpieczeństwa - Techniczne środki przeciwpożarowe,","b": "PN-N-01256-5:1998 Znaki bezpieczeństwa – Zasady umieszczania znaków bezpieczeństwa na drogach ewakuacyjnych i drogach pożarowych,","c": "PN-N-01256-1:1992 Znaki bezpieczeństwa – Ochrona przeciwpożarowa."},"category": "Ewakuacja"},{"id": 24,"q": "Forma i zakres danych zawartych w projekcie budowlanym, przedkładanym do uzgodnienia pod względem ochrony przeciwpożarowej, powinny odpowiadać wymaganiom:","options": {"a": "rozporządzenia Ministra Transportu, Budownictwa i Gospodarki Morskiej z dnia 25.04.2012 r. w sprawie szczegółowego zakresu i formy projektu budowlanego (Dz.U. z 2012 r., poz. 462),","b": "rozporządzenia Ministra Spraw Wewnętrznych i Administracji z dnia 16.06.2003 r. w sprawie uzgadniania projektu budowlanego pod względem ochrony przeciwpożarowej (Dz.U. Nr 121, poz. 1137 i z 2009 r. Nr 119, poz. 998).","c": "obu wyżej wymienionych aktów prawnych."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 25,"q": "Projektowane przeszklenia w części ściany zewnętrznej klatki schodowej obudowanej, zamykanej drzwiami przeciwpożarowymi klasy odporności ogniowej EI 30, zabezpieczonej przed zadymieniem, zlokalizowanej w miejscu połączenia pod kątem prostym dwóch skrzydeł budynku mieszkalnego o wysokości 9 kondygnacji w kształcie litery „L”, powinny mieć klasę odporności ogniowej co najmniej:","options": {"a": "EI 120,","b": "EI 60,","c": "EI 30."},"category": "Ewakuacja"},{"id": 26,"q": "W przypadku zastosowania ochrony pionowych dróg ewakuacji w budynku wielokondygnacyjnym za pomocą instalacji oddymiającej, należy uwzględnić czynnik związany z okresową utratą możliwości ewakuacji osób znajdujących się na:","options": {"a": "kondygnacji objętej pożarem,","b": "kondygnacjach powyżej kondygnacji objętej pożarem,","c": "kondygnacjach poniżej kondygnacji objętej pożarem."},"category": "Ewakuacja"},{"id": 27,"q": "W budynku o wysokości 11 kondygnacji, posadowionym na trzykondygnacyjnym garażu podziemnym, w którym na pierwszej kondygnacji nadziemnej zlokalizowano sklepy a powyżej na każdej kondygnacji, stanowiącej odrębną strefę pożarową o powierzchni 1800 m2, znajdują się mieszkania, maksymalne dopuszczalne zmniejszenie pojemności zbiornika do zasilania w wodę instalacji wodociągowej przeciwpożarowej wynosi:","options": {"a": "50 m3,","b": "6 m3,","c": "dopuszcza się brak zbiornika, przy zapewnieniu zasilania z zewnętrznej sieci wodociągowej o wydajności nie mniejszej niż 10 dm3/s."},"category": "Odporność ogniowa i klasy budynków"},{"id": 28,"q": "Pojemność zbiornika magazynowego stacji paliw płynnych dla produktów naftowych nie powinna przekraczać:","options": {"a": "50 m3,","b": "100 m3,","c": "200 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 29,"q": "Promień łuku drogi pożarowej mierzy się do:","options": {"a": "wewnętrznej krawędzi drogi,","b": "osi drogi,","c": "zewnętrznej krawędzi drogi."},"category": "Drogi pożarowe i dojazd"},{"id": 30,"q": "Zgodnie z PN-EN 1838:2013-11 Zastosowanie oświetlenia. Oświetlenie awaryjne, obowiązek wyposażenia w oprawy oświetlenia awaryjnego dotyczy:","options": {"a": "toalet przystosowanych do obsługi osób niepełnosprawnych,","b": "wszystkich toalet,","c": "wszystkich dróg ewakuacyjnych, w tym również oświetlonych światłem dziennym."},"category": "Ewakuacja"},{"id": 31,"q": "Pomieszczenie magazynowe przeznaczone do składowania gazów palnych lub karbidu, uznaje się za zagrożone wybuchem, przewidując przy tym określone dla tych pomieszczeń wymagania, na podstawie:","options": {"a": "dokonanej oceny zagrożenia wybuchem,","b": "postanowień wynikających wprost z przepisów przeciwpożarowych,","c": "dokonanej analizy zagrożenia wybuchem."},"category": "Zagrożenie wybuchem"},{"id": 32,"q": "Minimalna szerokość w świetle drzwi prowadzących bezpośrednio na zewnątrz z klatki schodowej przeznaczonej do ewakuacji ludzi z wielokondygnacyjnego garażu podziemnego wynosi:","options": {"a": "0,8 m,","b": "0,9 m,","c": "1,2 m."},"category": "Ewakuacja"},{"id": 33,"q": "W jednokondygnacyjnym budynku magazynowym o wysokości 6 m, stanowiącym odrębną strefę pożarową zakwalifikowaną do kategorii PM o gęstości obciążenia ogniowego 1000 MJ/m2, wyposażonym w stałe samoczynne urządzenie gaśnicze tryskaczowe oraz grawitacyjną instalację oddymiającą uruchamiającą się automatycznie po przekroczenia temperatury znamionowej zadziałania wyzwalaczy termicznych klap dymowych, maksymalna długość przejścia ewakuacyjnego wynosi:","options": {"a": "225 m,","b": "150 m,","c": "175 m."},"category": "Ewakuacja"},{"id": 34,"q": "W budynku biurowym o wysokości 165 m, do zabezpieczenia przed zadymieniem dwóch klatek schodowych zastosowano system różnicowania ciśnień wg PN-EN-12101-6 Wymagania techniczne dotyczące systemów różnicowania ciśnień. Zestawy urządzeń. Jeżeli z każdego miejsca na poszczególnych kondygnacjach jest zapewniona możliwość ewakuacji ludzi do obu klatek schodowych (dwa kierunki ewakuacji), to zgodnie wyżej wymienioną normą rezerwowe wentylatory oraz mechanizmy napędowe wykorzystywane w tym systemie:","options": {"a": "powinny być zastosowane, w co najmniej jednej klatce schodowej,","b": "nie muszą być stosowane,","c": "powinny być zastosowane w obu klatkach schodowych."},"category": "Ewakuacja"},{"id": 35,"q": "Budynek niski o trzech kondygnacjach nadziemnych, niepodpiwniczony, w którym dwie pierwsze kondygnacje stanowią strefę pożarową ZL II, ze stropem nad pierwszą kondygnacją nadziemną na wysokości nie większej niż 9 m nad poziom terenu, a kondygnacja trzecia nadziemną stanowi strefę pożarową ZL III, powinien spełnić wymagania klasy odporności pożarowej:","options": {"a": "co najmniej C dla całego budynku,","b": "co najmniej B w części ZL II i C w części ZL III,","c": "co najmniej B dla całego budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 36,"q": "Droga pożarowa prowadzona na terenie zakładu produkcyjnego pod estakadą z instalacjami technicznymi, powinna mieć zapewniony prześwit:","options": {"a": "o szerokości 3,6 metra i wysokości 4,5 metra,","b": "o szerokości 4 metrów i wysokości 4,5 metra,","c": "o szerokości i wysokości 4,5 metra."},"category": "Drogi pożarowe i dojazd"},{"id": 37,"q": "Na działce zlokalizowanej poza granicą jednostki osadniczej usytuowane są dwa obiekty, stanowiące jedną strefę pożarową: jednokondygnacyjny użyteczności publicznej o powierzchni 145 m2 i kubaturze brutto 400 m3 oraz dwukondygnacyjny zamieszkania zbiorowego o powierzchni 350 m2 i kubaturze brutto 2050 m3. Wymagane przeciwpożarowe zaopatrzenie w wodę do zewnętrznego gaszenia pożaru dla tych obiektów wynosi:","options": {"a": "10 dm3/s,","b": "20 dm3/s,","c": "nie jest wymagane."},"category": "Odporność ogniowa i klasy budynków"},{"id": 38,"q": "Wymagana ilość wody do celów przeciwpożarowych dla budynku mieszkalnego zaliczonego w całości do kategorii zagrożenia ludzi ZL IV z garażem podziemnym o powierzchni 4500 m2, powinna wynosić:","options": {"a": "10 dm3/s,","b": "20 dm3/s,","c": "30 dm3/s."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 39,"q": "Przedszkole w projektowanym budynku szkoły podstawowej należy tworzyć zgodnie z:","options": {"a": "ogólnymi wymaganiami przepisów techniczno-budowlanych,","b": "rozporządzeniem MEN z dnia 31.12.2014 r. w sprawie wymagań ochrony przeciwpożarowej, jakie musi spełniać lokal, w którym jest prowadzone przedszkole utworzone w wyniku przekształcenia oddziału przedszkolnego lub oddziałów przedszkolnych w szkole podstawowej (Dz.U. z 2015 r., poz. 20),","c": "rozporządzeniem MEN z dnia 31.08.2010 r. w sprawie rodzajów innych form wychowania przedszkolnego, warunków tworzenia i organizowania tych form oraz sposobu ich działania (Dz.U. Nr 161, poz. 1080 i z 2011 r. Nr 143, poz. 839)."},"category": "Pozostałe / ogólne"},{"id": 40,"q": "Według PKN-CEN/TS 54-14.2006 Systemy sygnalizacji pożarowej. Część 14. Wytyczne planowania projektowania, instalowania, odbioru, eksploatacji i konserwacji wymagany poziom natężenia dźwięku sygnalizacji akustycznej w pokojach hotelowych powinien być zapewniony:","options": {"a": "w miejscu zainstalowania sygnalizatora akustycznego,","b": "na wysokości łóżka,","c": "na poziomie podłogi."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 41,"q": "Czy inwestor jest zobowiązany do zawiadomienia organów Państwowej Straży Pożarnej o zakończeniu budowy obiektu budowlanego i zamiarze przystąpienia do użytkowania, w przypadku, gdy obiekt nie jest objęty obowiązkiem uzyskania pozwolenia na użytkowanie?","options": {"a": "nie,","b": "tak, jeśli warunek przedłożenia stanowiska organu PSP określił właściwy organ nadzoru budowlanego,","c": "tak, jeśli projekt budowlany obiektu budowlanego wymagał uzgodnienia pod względem ochrony przeciwpożarowej."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 42,"q": "Odległość pomiędzy hydrantami zewnętrznymi usytuowanymi poza obszarami miejskimi, powinna wynosić:","options": {"a": "nie mniej niż 150 metrów,","b": "nie mniej niż 300 metrów,","c": "powinna być dostosowana do gęstości istniejącej i planowanej zabudowy."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 43,"q": "Obowiązek utrzymania, przez właścicieli lub zarządców terenów, dróg pożarowych w stanie umożliwiającym korzystanie z tych dróg przez pojazdy jednostek ochrony przeciwpożarowej określa:","options": {"a": "rozporządzenie Ministra Spraw Wewnętrznych i Administracji w sprawie przeciwpożarowego zaopatrzenia w wodę oraz dróg pożarowych,","b": "rozporządzenie Ministra Spraw Wewnętrznych i Administracji w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów,","c": "rozporządzenie Ministra Środowiska w sprawie szczegółowych zasad zabezpieczenia przeciwpożarowego lasów."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 44,"q": "Klapy dymowe w grawitacyjnej wentylacji oddymiającej otwierane wyłącznie w sposób ręczny powinny mieć klasę:","options": {"a": "B30030,","b": "В30060,","c": "В60030."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 45,"q": "Klasyfikacja materiału lub wyrobu budowlanego w zakresie reakcji na ogień opisana jako A2-s3,d0 wskazuje, że jest on:","options": {"a": "niepalny, niekapiący i intensywnie dymiący,","b": "niepalny, kapiący i niedymiący,","c": "trudno zapalny, niekapiący i intensywnie dymiący."},"category": "Reakcja na ogień i materiały"},{"id": 46,"q": "Czy zgodnie z rozporządzeniem Ministra Edukacji Narodowej w sprawie wymagań ochrony przeciwpożarowej, jakie musi spełniać lokal, w którym jest prowadzone przedszkole utworzone w wyniku przekształcenia oddziału przedszkolnego lub oddziałów przedszkolnych zorganizowanych w szkole podstawowej, lokal przedszkola powstały w wyniku przekształcenia istniejącego oddziału przedszkolnego w szkole podstawowej może być zlokalizowany na drugiej kondygnacji nadziemnej:","options": {"a": "nie, ponieważ wyżej wymienione rozporządzenie nie dopuszcza takiej możliwości,","b": "tak, np. jeśli będą spełnione wymagania uzgodnione z właściwym miejscowo komendantem wojewódzkim Państwowej Straży Pożarnej,","c": "tak, jeśli lokal będzie spełniał warunki szczególne określone w wyżej wymienionym rozporządzeniu, m.in. będzie użytkowany przez nie więcej niż 25 dzieci oraz będzie posiadał co najmniej dwa wyjścia na zewnątrz, na drogi ewakuacyjne spełniające wymagania dla kategorii zagrożenia ludzi ZL II."},"category": "Ewakuacja"},{"id": 47,"q": "Zapas środka pianotwórczego do stałego urządzenia gaśniczego pianowego do ochrony zbiornika z paliwem na terenie bazy paliw płynnych powinien wystarczyć na okres:","options": {"a": "trzydziestominutowego jego zużycia,","b": "zużycia wymaganego zapasu wody,","c": "dwugodzinnego zużycia zapasu wody do gaszenia pożaru największego zbiornika i jego obwałowania."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 48,"q": "Pojemność zbiornika magazynowego stacji paliw płynnych dla produktów naftowych nie powinna przekraczać:","options": {"a": "50 m3,","b": "100 m3,","c": "200 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 49,"q": "Zgodnie ze specyfikacją techniczną PKN-CEN/TS 54-14:2006 Systemy sygnalizacji pożarowej. Część 14: Wytyczne planowania projektowania, instalowania, odbioru, eksploatacji i konserwacji pod optyczną czujką dymu należy zachować wolną przestrzeń:","options": {"a": "w odległości co najmniej 0,3 m od czujki we wszystkich kierunkach,","b": "w odległości co najmniej 0,5 m od czujki we wszystkich kierunkach,","c": "w odległości co najmniej 0,5 m od czujki w poziomie i 0,3 m w pionie."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 50,"q": "W średniowysokim budynku zakwalifikowanym do kategorii zagrożenia ludzi ZL III długość poziomej drogi ewakuacyjnej od wyjścia z obudowanej klatki schodowej, zamykanej drzwiami о klasie odporności ogniowej co najmniej EI 30 i wyposażonej w urządzenia służące do usuwania dymu, do wyjścia na zewnątrz nie może przekraczać przy jednym dojściu:","options": {"a": "40 m,","b": "20 m,","c": "10 m."},"category": "Ewakuacja"},{"id": 51,"q": "Minimalna szerokość w świetle drzwi prowadzących bezpośrednio na zewnątrz z klatki schodowej przeznaczonej do ewakuacji ludzi z wielokondygnacyjnego budynku mieszkalnego powinna wynosić co najmniej:","options": {"a": "0,8 m,","b": "0,9 m,","c": "1,2 m."},"category": "Ewakuacja"},{"id": 52,"q": "Dopuszcza się powiększenie o 100 % powierzchni stref pożarowych budynków zaliczonych do ZL, pod warunkiem zastosowania:","options": {"a": "stałych urządzeń gaśniczych tryskaczowych,","b": "stałych samoczynnych urządzeń gaśniczych wodnych,","c": "stałych urządzeń gaśniczych (dowolnego rodzaju)."},"category": "Strefy pożarowe i oddzielenia"},{"id": 53,"q": "Ściana zewnętrzna budynku, do którego droga pożarowa przybliżona jest na odległość mniejszą niż 5 m, powinna na tym odcinku oraz w odległości do 5 m od niego:","options": {"a": "posiadać klasę odporności ogniowej wymaganą dla ściany oddzielenia przeciwpożarowego,","b": "spełniać wymagania dla ściany oddzielenia przeciwpożarowego,","c": "na całej powierzchni posiadać klasę odporności ogniowej wymaganą dla ścian zewnętrznych tego budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 54,"q": "Pomieszczenia magazynowe przeznaczone do składowania karbidu:","options": {"a": "muszą spełniać wymagania określone dla pomieszczeń zagrożonych wybuchem,","b": "muszą spełniać wymagania określone dla pomieszczeń zagrożonych wybuchem, jeśli ocena zagrożenia wybuchem wykaże, iż w pomieszczeniu możliwy jest przyrost ciśnienia przekraczający 5 kPa,","c": "muszą spełniać wymagania określone dla pomieszczeń zagrożonych wybuchem, jeśli ocena zagrożenia wybuchem wykaże, iż w pomieszczeniu możliwe jest powstanie strefy zagrożenia wybuchem."},"category": "Zagrożenie wybuchem"},{"id": 55,"q": "Urządzeniem przeciwpożarowym w rozumieniu przepisów przeciwpożarowych jest:","options": {"a": "gaśnica,","b": "półstałe urządzenia gaśnicze,","c": "główny wyłącznik prądu, odcinający dopływ prądu do wszystkich obwodów w budynku w przypadku pożaru."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 56,"q": "Wymiary stref zagrożenia wybuchem dla cysterny kolejowej w czasie spustu produktu w bazie paliw, wyznacza się na podstawie:","options": {"a": "PN-EN 60079-10-1.2009 Atmosfery i wybuchowe. Część 10-1: Klasyfikacja przestrzeni. Gazowe atmosfery wybuchowe,","b": "załącznika do rozporządzenia Ministra Gospodarki w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie,","c": "przepisów umowy ADR."},"category": "Zagrożenie wybuchem"},{"id": 57,"q": "Przy projektowaniu infrastruktury do magazynowania i tankowania pojazdów paliwami płynnymi na użytek własny przedsiębiorstwa transportowego przepisy rozporządzenia Ministra Gospodarki w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie:","options": {"a": "stosuje się jako obligatoryjne,","b": "mogą być stosowane na zasadach wiedzy technicznej,","c": "nie mogą być stosowane ponieważ przepisy nie przewidują projektowania takich obiektów."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 58,"q": "W odniesieniu do ogółu budynków użyteczności publicznej, kryterium w kontekście obowiązku ich wyposażenia w system sygnalizacji pożarowej jest :","options": {"a": "liczba przebywających w nich osób,","b": "powierzchnia strefy pożarowej,","c": "wysokość budynku."},"category": "Strefy pożarowe i oddzielenia"},{"id": 59,"q": "W przypadku usytuowania w obrębie miejsca obsługi podróżnych (MOP), na drodze klasy S, parkingu przeznaczonego dla pojazdów przewożących materiały niebezpieczne, należy zapewnić jego odległość od budynków przeznaczonych na pobyt ludzi wynoszącą nie mniej niż:","options": {"a": "20 m,","b": "30 m,","c": "300 m."},"category": "Garaże i parkingi"},{"id": 60,"q": "Zaliczenie kondygnacji podziemnej budynku biurowego do kategorii zagrożenia ludzi (ZL):","options": {"a": "powoduje konieczność uwzględnienia wysokości wspomnianej kondygnacji w kontekście określania wymaganej klasy odporności pożarowej tego budynku,","b": "powoduje konieczność uwzględnienia wysokości wspomnianej kondygnacji w kontekście określania dopuszczalnej powierzchni strefy pożarowej tego budynku,","c": "może powodować konieczność uwzględnienia wysokości rozpatrywanej kondygnacji w kontekście określania wymaganej klasy odporności pożarowej tego budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 61,"q": "Przepust instalacyjny o średnicy 0,04 m w stropie oddzielającym garaż podziemny od części mieszkalnej niskiego budynku ZL IV:","options": {"a": "powinien mieć klasę odporności ogniowej EI 60,","b": "powinien mieć klasę odporności ogniowej EI 120,","c": "powinien mieć klasę odporności ogniowej EIS 120."},"category": "Odporność ogniowa i klasy budynków"},{"id": 62,"q": "Obowiązek wyposażenia w system sygnalizacji pożarowej dotyczy tunelu drogowego o długości większej niż:","options": {"a": "500 m,","b": "1000 m,","c": "akty prawne nie określają takiego obowiązku."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 63,"q": "Wskazany w załączniku nr 1 do rozporządzenia Ministra Infrastruktury w sprawie warunków technicznych, jakim powinny odpowiadać obiekty budowlane metra i ich usytuowanie współczynnik bezpieczeństwa, ustalany każdorazowo indywidualnie, lecz wynoszący nie mniej niż 1,3, uwzględnia się przy określaniu:","options": {"a": "krytycznego stanu środowiska,","b": "przewidywanego czasu ewakuacji,","c": "krytycznego czasu ewakuacji."},"category": "Ewakuacja"},{"id": 64,"q": "Klasa odporności ogniowej wypełnienia otworu wykonanego z materiału przepuszczającego światło, znajdującego się w ścianie oddzielenia przeciwpożarowego, oddzielającej od siebie dwa pomieszczenia użytkowe w niskim, 3 kondygnacyjnym budynku szpitala powinna wynosić:","options": {"a": "EI 30,","b": "EI 60,","c": "E 60."},"category": "Odporność ogniowa i klasy budynków"},{"id": 65,"q": "Masę dachu w pomieszczeniu zagrożonym wybuchem, określaną w celu ustalenia spełniania przez ten dach parametru dla dachu lekkiego, tj. nieprzekroczenia masy 75 kg/m2, należy ustalać:","options": {"a": "bez uwzględnienia elementów konstrukcji nośnej dachu,","b": "z uwzględnieniem elementów konstrukcji nośnej dachu,","c": "wymagania przepisów ochrony przeciwpożarowej nie rozstrzygają powyższej kwestii i w tym zakresie należy dokonać oceny inżynierskiej."},"category": "Zagrożenie wybuchem"},{"id": 66,"q": "Jezdnia asfaltowa o szerokości 15 m, przebiegająca w odległości 2 m od ściany zewnętrznej z oknami budynku wysokiego biurowego (wzdłuż jego dłuższego boku o szerokości 45 m), spełniająca pozostałe wymagania odnoszące się do dróg pożarowych:","options": {"a": "może być rozpatrywana jako droga pożarowa dla tego budynku pomimo, że jej bliższa krawędź znajduje się w odległości mniejszej 5 m od ściany zewnętrznej budynku,","b": "nie może być rozpatrywana jako droga pożarowa dla tego budynku ponieważ bliższa krawędź drogi pożarowej musi być oddalona od jego ściany zewnętrznej o 5-15 m,","c": "może być rozpatrywana jako droga pożarowa pomimo, że jej bliższa krawędź znajduje się w odległości mniejszej 5 m od ściany zewnętrznej budynku, pod warunkiem zastosowania rozwiązań zamiennych zapewniających niepogorszenie warunków ochrony przeciwpożarowej obiektu, uzgodnionych z właściwym miejscowo komendantem wojewódzkim Państwowej Straży Pożarnej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 67,"q": "Budynek o wysokości 9 kondygnacji nadziemnych (24 m), w którym pierwszą kondygnację nadziemną zajmują sklepy, na kondygnacjach od 2 do 8 nadziemnej przewidziano mieszkania, a na ostatniej taras widokowy z pomieszczeniem, w którym świadczone są usługi gastronomiczne i sprzedaż pamiątek, powinien być zaprojektowany w klasie odporności pożarowej:","options": {"a": "C,","b": "B,","c": "pierwsza kondygnacja nadziemna w klasie B, a kondygnacje od 2 do 9 w klasie C."},"category": "Ewakuacja"},{"id": 68,"q": "Kwalifikacji zamierzonego odstąpienia od zatwierdzonego projektu budowlanego, które dotyczy rozwiązań z zakresu ochrony przeciwpożarowej, dokonuje:","options": {"a": "rzeczoznawca do spraw zabezpieczeń przeciwpożarowych,","b": "projektant,","c": "organ administracji architektoniczno-budowlanej."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 69,"q": "W pomieszczeniu magazynowym, w strefie zagrożenia wybuchem sklasyfikowanej jako strefa 2 mogą być stosowane urządzenia elektryczne:","options": {"a": "wyłącznie kategorii 1,","b": "wyłącznie kategorii 2,","c": "kategorii 1, 2 lub 3."},"category": "Zagrożenie wybuchem"},{"id": 70,"q": "W miejscu przejścia przewodu wentylacyjnego przez ścianę wewnętrzną o klasie odporności ogniowej REI 60, stanowiącą obudowę ewakuacyjnej klatki schodowej, który w warunkach bytowych nawiewa powietrze tylko do klatki schodowej, można zastosować przeciwpożarową klapę odcinającą z klasyfikacją ogniową:","options": {"a": "EI 60,","b": "EI 60 (ve i<->o) S,","c": "EI 60 (ho k->o) S."},"category": "Ewakuacja"},{"id": 71,"q": "Celem stosowania instalacji tryskaczowych ESFR jest:","options": {"a": "kontrola pożaru,","b": "ugaszenie pożaru,","c": "wobec nie określenia wymagań w przedmiotowym zakresie w normach i innych standardach technicznych wspomnianego celu nie określa się."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 72,"q": "W lokalu restauracji, który znajduje się na parterze w budynku hotelu o wysokości 26 m, stosowanie instalacji gazowych z kuchenkami, zasilanych z indywidualnych butli z gazem płynnym o nominalnej zawartości gazu do 11 kg, jest:","options": {"a": "zabronione;","b": "dozwolone, przy czym w lokalu nie należy instalować więcej niż dwóch butli;","c": "dozwolone, przy czym wymaga uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 73,"q": "Dopuszcza się umieszczenie w jednym budynku części mieszkalnej i gospodarczej (IN) m.in. pod warunkiem zapewnienia między częścią mieszkalną a gospodarczą:","options": {"a": "ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 120,","b": "ściany o klasie odporności ogniowej co najmniej REI 60,","c": "ściany z materiału niepalnego bez otworów drzwiowych lub okiennych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 74,"q": "Ustalając klasę odporności pożarowej budynku produkcyjno-magazynowego jego ściany wewnętrzne wykonane z materiałów palnych:","options": {"a": "uwzględniania się w obliczeniach gęstości obciążenia ogniowego,","b": "nie uwzględniania się w obliczeniach gęstości obciążenia ogniowego,","c": "nie uwzględniania się w obliczeniach gęstości obciążenia ogniowego jeżeli są nierozprzestrzeniające ognia (NRO)."},"category": "Odporność ogniowa i klasy budynków"},{"id": 75,"q": "Projektując system kontroli rozprzestrzeniania dymu i ciepła klasy B zgodnie z PN-EN 12101-6:2007 Systemy kontroli rozprzestrzeniania dymu i ciepła Część 6: Wymagania techniczne dotyczące systemów różnicowania ciśnień. Zestawy urządzeń w drzwiach pomiędzy przedsionkiem przeciwpożarowym klatki schodowej zabezpieczonej tym systemem, a pomieszczeniem użytkowym należy zapewnić prędkość przepływu powietrza co najmniej:","options": {"a": "0,5 m/s,","b": "1 m/s,","c": "2 m/s"},"category": "Odporność ogniowa i klasy budynków"},{"id": 76,"q": "Zgodnie z PN-EN 60849:2001 Dźwiękowe systemy ostrzegawcze rezerwowe źródło zasilania powinno umożliwić działanie systemu w trybie zagrożenia, w czasie:","options": {"a": "dłuższym niż czas ewakuacji ustalony przez władającego budynkiem, jednak nie krótszym niż 30 min,","b": "dwa razy dłuższym niż czas ewakuacji ustalony przez władającego budynkiem, jednak nie krótszym niż 30 min,","c": "nie krótszym niż 60 min."},"category": "Ewakuacja"},{"id": 77,"q": "Zgodnie z PN-B-02877-4:2001 Ochrona przeciwpożarowa budynków Instalacje grawitacyjne do odprowadzania dymu i ciepła. Zasady projektowania w dachu płaskim o kącie nachylenia 2° co najmniej jedna klapa dymowa powinna przypadać:","options": {"a": "na każde 100 m2,","b": "na każde 200 m2,","c": "na każde 400 m2."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 78,"q": "Przy projektowaniu budynku galerii handlowej o wysokości 20 m, w której część handlowo-usługowa stanowić będzie jedną strefę pożarową o powierzchni 30 000 m z hipermarketem spożywczym na kondygnacji podziemnej, wyposażoną stałe urządzenia gaśnicze tryskaczowe oraz w samoczynne urządzenia oddymiające uruchamiane za pomocą systemu wykrywania dymu, konieczne jest uzyskanie odstępstwa od dopuszczalnej przepisami techniczno-budowlanymi wielkości strefy pożarowej, wynoszącej w rozpatrywanym przypadku:","options": {"a": "2 500 m2,","b": "5 000 m2,","c": "7500 m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 79,"q": "Do budynku mieszkalnego z wbudowanym garażem podziemnym zamkniętym wymagane jest zapewnienie wody do zewnętrznego gaszenia pożaru w ilości 20 dm3/s w przypadku, gdy powierzchnia strefy pożarowej garażu przekracza:","options": {"a": "1500 m2,","b": "2000 m2,","c": "3000 m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 80,"q": "Wymiana odmierzacza paliw płynnych na stacji paliw płynnych zbudowanej w 1993 roku, niespełniającej wymagań rozporządzenia Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie (Dz. U. z 2014 r. poz. 1853), jest możliwa:","options": {"a": "po uzyskaniu odstępstwa od wymagań ww. rozporządzenia,","b": "po uzgodnieniu z właściwym komendantem wojewódzkim Państwowej Straży Pożarnej możliwości spełnienia wymagań ww. rozporządzenia w sposób inny niż wynika to wprost z jego przepisów,","c": "bez stosowania procedur, o których mowa w odpowiedziach a) i b)."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 81,"q": "Droga pożarowa prowadzona na terenie zakładu produkcyjnego pod estakadą z instalacjami technicznymi, powinna mieć zapewniony prześwit:","options": {"a": "o szerokości 3,6 m i wysokości 4,5 m,","b": "o szerokości 4 m i wysokości 4,5 m,","c": "o szerokości 4,5 m i wysokości 4,5 m."},"category": "Drogi pożarowe i dojazd"},{"id": 82,"q": "Zawór odcinający dopływ gazu do budynku, będący elementem składowym urządzenia sygnalizacyjno-odcinającego, w budynku mieszkalnym wielorodzinnym z instalacją gazową (lub instalacjami gazowymi) na paliwo gazowe (z sieci) zasilającą (lub zasilającymi) urządzenia w lokalach mieszkalnych oraz kotłownię z kotłami na paliwo gazowe, o łącznej mocy cieplnej 350 kW (2 kotły o mocy 150 kW i jeden o mocy 50 kW) powinien zapewniać odcięcie dopływu gazu do:","options": {"a": "całego budynku,","b": "kotłowni,","c": "tych kotłów w kotłowni, które mają moc cielną powyżej 60 kW."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 83,"q": "Przewody i kable elektryczne oraz inne instalacje wykonane z materiałów palnych, prowadzone w przestrzeni podpodłogowej podłogi podniesionej powinny mieć osłonę lub obudowę o określonej klasie odporności ogniowej (co najmniej EI 30 bądź EI 60):","options": {"a": "wyłącznie w przypadku, gdy przestrzeń ta jest wykorzystywana do wentylacji lub ogrzewania pomieszczenia i jednocześnie podłogi te podniesione są o więcej niż 0,2 m ponad poziom stropu lub innego podłoża,","b": "zawsze w budynku wysokościowym (WW) lub w budynkach ze strefą pożarową o gęstości obciążenia ogniowego ponad 4.000 MJ/m2,","c": "zawsze w przypadku, gdy przestrzeń ta jest wykorzystywana do wentylacji lub ogrzewania pomieszczenia niezależnie od wysokości, na jaką podłogi są podniesione."},"category": "Odporność ogniowa i klasy budynków"},{"id": 84,"q": "Klasa reakcji na ogień oznaczona literami Cfl-s2 dotyczy wyrobu budowlanego, jakim jest:","options": {"a": "posadzka,","b": "wykładzina podłogowa,","c": "obydwa wymienione powyżej wyroby."},"category": "Reakcja na ogień i materiały"},{"id": 85,"q": "Przechowywanie cieczy o temperaturze zapłonu poniżej 373,15 K (100 °C) w garażach o powierzchni powyżej 100 m2:","options": {"a": "jest niedopuszczalne,","b": "dopuszczalne jest tylko wtedy, gdy są niezbędne przy eksploatacji pojazdu i są przechowywane w jednostkowych opakowaniach stosowanych w handlu detalicznym,","c": "jest dopuszczalne w łącznej ilości do 200 dm3 przy założeniu nieprzelewania paliwa oraz nienapełniania nim zbiorników paliwa w pojazdach."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 86,"q": "Parametrem granicznym, którego przekroczenie wskazuje na wystąpienie w obiekcie budowlanym metra, krytycznego dla życia i zdrowia ludzi warunku środowiskowego, jest:","options": {"a": "temperatura powietrza powyżej 60°C na wysokości mniejszej lub równej 1,5 m od poziomu drogi ewakuacyjnej,","b": "temperatura powietrza powyżej 200°C na wysokości mniejszej lub równej 1,8 m od poziomu drogi ewakuacyjnej,","c": "temperatura powietrza powyżej 60°C na wysokości mniejszej lub równej 1,8 m od poziomu drogi ewakuacyjnej."},"category": "Ewakuacja"},{"id": 87,"q": "W dwukondygnacyjnym budynku magazynowym o wysokości 8 m i o gęstości obciążenia ogniowego 800 MJ/m2 jako przekrycie dachu należy zastosować:","options": {"a": "przekrycie klasy co najmniej BROOF(t1),","b": "przekrycie spełniające co najmniej warunki i kryteria określone dla grupy kryteriów b „penetracja ognia do wewnątrz budynku\" właściwej dla przekryć klasy BROOF(t1),","c": "przekrycie klasy co najmniej CROOF(t1)."},"category": "Odporność ogniowa i klasy budynków"},{"id": 88,"q": "Wymagana ilość wody do celów przeciwpożarowych dla zlokalizowanych poza budynkami urządzeń technologicznych z cieczami o temperaturze zapłonu do 373,15 K (100 °C), służąca do zewnętrznego gaszenia pożaru zależy od:","options": {"a": "powierzchni zajmowanej przez te urządzenia [m2],","b": "ilości cieczy w tych urządzeniach [m3],","c": "gęstości obciążenia ogniowego na terenie zajmowanym przez te urządzenia [MJ/m2]."},"category": "Pozostałe / ogólne"},{"id": 89,"q": "Projektowanie galerii handlowej jako budynku niskiego dwukondygnacyjnego o powierzchni strefy pożarowej do 5000 m2, z kinem składającym się z czterech sal, każdej o liczbie 200 miejsc, wymaga zastosowania:","options": {"a": "stałych samoczynnych urządzeń gaśniczych wodnych, systemu sygnalizacji pożarowej i dźwiękowego systemu ostrzegawczego,","b": "systemu sygnalizacji pożarowej i dźwiękowego systemu ostrzegawczego,","c": "tylko systemu sygnalizacji pożarowej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 90,"q": "W pomieszczeniu o wysokości 5,8 m stanowiącym odrębną strefę pożarową zakwalifikowaną do kategorii ZL III i chronionym stałym samoczynnym urządzeniem gaśniczym gazowym, maksymalna długość przejścia ewakuacyjnego wynosi:","options": {"a": "40 m,","b": "50 m,","c": "60 m."},"category": "Ewakuacja"},{"id": 91,"q": "Dla budynku mieszkalno-usługowego o wysokości 13,5 m i czterech kondygnacjach nadziemnych, w którym pierwszą kondygnację nadziemną, stanowi odrębna strefa pożarowa zaliczona do kategorii zagrożenia ludzi ZL II, natomiast pozostałe kondygnacje zaliczone zostały do kategorii zagrożenia ludzi ZL IV, dopuszcza się przyjęcie najniższej klasy odporności pożarowej:","options": {"a": "„D”,","b": "„C”,","c": "„B”."},"category": "Odporność ogniowa i klasy budynków"},{"id": 92,"q": "W przypadku budynku hotelowego o wysokości 13,45 m, jego główna konstrukcja nośna oraz konstrukcja jego dachu powinny spełniać odpowiednio wymagania klasy odporności ogniowej co najmniej:","options": {"a": "R 60 i R 15,","b": "R 60 i R 30,","c": "R 120 i R30."},"category": "Odporność ogniowa i klasy budynków"},{"id": 93,"q": "Budynek biurowy średniowysoki o powierzchni zabudowy nie większej niż 1200 m2, którego ściany zewnętrzne mają stopień przeszklenia szkłem „zwykłym\" na poziomie 30%, projektuje się od granicy sąsiedniej niezabudowanej działki o przeznaczeniu określonym w miejscowym planie zagospodarowania przestrzennego pod budynki PM, w odległości nie mniejszej niż:","options": {"a": "6 m,","b": "7,5 m,","c": "15 m."},"category": "Pozostałe / ogólne"},{"id": 94,"q": "W pomieszczeniu przeznaczonym do jednoczesnego przebywania 150 dzieci, w którym miejsca do siedzenia są ustawione w rzędach przyściennych o liczbie 18 siedzeń w rzędzie, szerokość przejść między rzędami siedzeń nie może być mniejsza niż:","options": {"a": "0,47 m,","b": "0,55 m,","c": "0,60 m."},"category": "Ewakuacja"},{"id": 95,"q": "W budynku ZL II dwukondygnacyjnym o wysokości 9 m zastosowanie w ścianach zewnętrznych izolacji cieplnej palnej:","options": {"a": "jest możliwe jeżeli osłaniająca ją od wewnątrz okładzina jest niepalna i ma klasę odporności ogniowej co najmniej El 30,","b": "jest możliwe jeżeli osłaniająca ją od wewnątrz okładzina jest nierozprzestrzeniająca ognia i ma klasę odporności ogniowej co najmniej El 60,","c": "jest możliwe jeżeli osłaniająca ją od wewnątrz okładzina jest niepalna i ma klasę odporności ogniowej co najmniej El 60."},"category": "Odporność ogniowa i klasy budynków"},{"id": 96,"q": "W pomieszczeniach zagrożonych wybuchem należy stosować instalację wyciągową:","options": {"a": "oddzielną dla każdego pomieszczenia,","b": "wyposażoną w urządzenia zapobiegające przeniesieniu się ognia,","c": "wyposażoną w klapy lub przepony przeciwwybuchowe."},"category": "Zagrożenie wybuchem"},{"id": 97,"q": "Podziemny zbiornik z gazem propan-butan o pojemności 50 m3, zasilający instalację gazową w budynku produkcyjnym o gęstości obciążenia ogniowego do 2000 MJ/m2, powinien być usytuowany od tego budynku w odległości co najmniej:","options": {"a": "7,5 m,","b": "15 m,","c": "30 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 98,"q": "Na drogach ewakuacyjnych z lokalu dyskoteki przeznaczonej dla 200 osób, usytuowanego na kondygnacji podziemnej należy zastosować:","options": {"a": "rozwiązania techniczno-budowlane służące do usuwania dymu,","b": "rozwiązania techniczno-budowlane zabezpieczające przed zadymieniem dróg ewakuacyjnych,","c": "urządzenia zapobiegające zadymieniu lub służące do usuwania dymu."},"category": "Ewakuacja"},{"id": 99,"q": "Instalacja wodociągowa przeciwpożarowa budynku w biurowym o wysokości 55 m, zawierającym strefę pożarową o powierzchni 2500 m2, wyposażona w nasady umożliwiające jej zasilanie z samochodów gaśniczych, może być zasilana:","options": {"a": "ze zbiornika przeciwpożarowego o pojemności 25 m3 w przypadku zapewnienia zasilania tego zbiornika w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s,","b": "ze zbiornika przeciwpożarowego o pojemności 6 m3 w przypadku zapewnienia zasilania tego zbiornika w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 15 dm3/s,","c": "z grupy zbiorników przeciwpożarowych o łącznej pojemności nie mniejszej niż 50 m3, w przypadku zapewnienia zasilania tych zbiorników w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 100,"q": "Wymagania stawiane obiektom widowiskowych (PN-EN 13200-1:2013 Obiekty widowiskowe. Część 1: Ogólna charakterystyka widowni) w zakresie ewakuacji zalecają, aby widzowie byli w stanie osiągnąć miejsce bezpieczne w przypadku obszarów pod przykryciem, wciągu:","options": {"a": "2 minut,","b": "8 minut,","c": "12 minut."},"category": "Ewakuacja"},{"id": 101,"q": "Zgodnie z rozporządzeniem Ministra Transportu, Budownictwa i Gospodarki Morskiej z dnia 25 kwietnia 2012 r. w sprawie szczegółowego zakresu i formy projektu budowlanego (Dz.U, z 27 kwietnia 2012 r., poz. 462, ze zm.), projekt zagospodarowania terenu powinien zawierać m.in. część opisową, która z kolei powinna określać zagospodarowanie działki, uwzględniające parametry techniczne m.in:","options": {"a": "sieci i urządzeń uzbrojenia terenu zapewniających przeciwpożarowe zaopatrzenie w wodę,","b": "występujących elementów oddzieleń przeciwpożarowych,","c": "obudowę dróg ewakuacyjnych i oddzielenia przeciwpożarowe."},"category": "Ewakuacja"},{"id": 102,"q": "Zastosowanie stałego samoczynnego urządzenia gaśniczego mgłowego w budynku jednokondygnacyjnym zakwalifikowanym do kategorii zagrożenia ludzi ZL I nie upoważnia do:","options": {"a": "powiększenia powierzchni strefy pożarowej o 100%","b": "obniżenia klasy odporności pożarowej budynku,","c": "wydłużenia o 50% dopuszczalnej długości przejścia ewakuacyjnego."},"category": "Ewakuacja"},{"id": 103,"q": "W świetle aktualnych regulacji przepisów ustawy o ochronie przeciwpożarowej rzeczoznawca do spraw zabezpieczeń przeciwpożarowych może:","options": {"a": "być autorem instrukcji bezpieczeństwa pożarowego,","b": "uzgodnić projekt urządzenia przeciwpożarowego, którego jest autorem,","c": "uzgodnić warunkowo projekt budowlany zawierający rozwiązania inne niż wynikające z przepisów przeciwpożarowych bez dołączenia do niego zgody na zastosowanie rozwiązań zamiennych."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 104,"q": "Czy garaż przeznaczony dla samochodów osobowych, w którym strefa pożarowa nie przekracza 1500 m2 i obejmuje jednocześnie kondygnację na poziomie „0\" i „-1\", powinien być wyposażony, zgodnie z przepisami przeciwpożarowymi, w system sygnalizacji pożarowej:","options": {"a": "tak,","b": "nie,","c": "nie, pod warunkiem zastosowania rozwiązań zamiennych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 105,"q": "Przynajmniej jeden dźwig w każdej strefie pożarowej powinien być przystosowany do potrzeb ekip ratowniczych w budynku ZL IV, zakwalifikowanym do:","options": {"a": "budynków wysokich (W),","b": "budynków wysokościowych (WW),","c": "w budynku mającym kondygnację z posadzką na wysokości powyżej 25 m ponad poziomem terenu przy najniżej położonym wejściu do budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 106,"q": "Minimalny poziom słyszalności komunikatu alarmowego w pokoju hotelowym, zgodnie z PN-EN 60849 Dźwiękowe systemy ostrzegawcze, powinien wynosić:","options": {"a": "75 dBA,","b": "65 dBA,","c": "10 dBA powyżej poziomu szumu tła."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 107,"q": "Pojemność zbiornika pośredniego uzupełnianego z sieci wodociągowej z natężeniem przepływu 10 1/s, stanowiącego wraz z pompą źródło wody dla instalacji tryskaczowej, której czas działania jest równy 60 min, przy wymaganym natężeniu przepływu wynikającym z obliczeń hydraulicznych wynoszącym 1800 dm3/min powinna być nie mniejsza niż:","options": {"a": "36 m3,","b": "72 m3,","c": "108m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 108,"q": "Maksymalna powierzchnia strefy dozorowej w budynku chronionym systemem sygnalizacji pożarowej z indywidualną adresacją czujek pożarowych w liniach dozorowych otwartych klasy „B\", zgodnie PKN-CEN TS 54-14: 2006, nie powinna przekraczać:","options": {"a": "400 m2,","b": "1000 m2,","c": "1600 m2."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 109,"q": "W korytarzu stanowiącym drogę ewakuacyjną o szerokości 2 m, zgodnie z wymaganiami PN-EN-1838 Zastosowania oświetlenia. Oświetlenie awaryjne, średnie natężenie awaryjnego oświetlenia ewakuacyjnego w centralnym pasie podłogi o szerokości 1 m powinno wynosi minimum:","options": {"a": "0,5 lx,","b": "0,75 lx,","c": "1 lx."},"category": "Ewakuacja"},{"id": 110,"q": "Powierzchnia strefy pożarowej PM o gęstości obciążenia ogniowego 1000 МJ/m2, bez pomieszczeń zagrożonych wybuchem, w wielokondygnacyjnym budynku wysokim chronionym całkowicie samoczynnym urządzeniem wodnym tryskaczowym, oraz samoczynnymi urządzeniami oddymiającymi powinna być:","options": {"a": "nie większa niż 2500 m2,","b": "nie większa niż 6250 m2,","c": "nie większa niż 7500 m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 111,"q": "W strefie pożarowej budynku produkcyjnego o wysokości 12 m podzielonego na dwie kondygnacje o równej wysokości i gęstości obciążenia ogniowego 500 МJ/m2, wyposażonej w stałe samoczynne urządzenie gaśnicze tryskaczowe, maksymalna długość przejścia ewakuacyjnego wynosi:","options": {"a": "131,25 m,","b": "150 m,","c": "175 m."},"category": "Ewakuacja"},{"id": 112,"q": "Dla budynku produkcyjnego, dla którego: zapotrzebowanie na wodę do zewnętrznego gaszenia pożaru wynosi 30 dm3/s, względny czas trwania pożaru wynosi 6 godzin a wydajność wodociągu wynosi 10 dm3/s, należy zapewnić uzupełniający zapas wody w zbiorniku przeciwpożarowym o pojemności co najmniej:","options": {"a": "200 m3,","b": "288 m3,","c": "432 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 113,"q": "Na terenie bazy paliw płynnych stanowiska służące do przeładunku produktów naftowych I i II klasy powinny być oddalone od ogrodzenia baz paliw co najmniej:","options": {"a": "5 m,","b": "10 m,","c": "15 m."},"category": "Pozostałe / ogólne"},{"id": 114,"q": "Jednym z warunków, jakie muszą spełniać proponowane rozwiązania zamienne jest:","options": {"a": "ograniczenie możliwości powstania pożaru,","b": "uwzględnienie możliwości ewakuacji ludzi lub ich uratowania w inny sposób,","c": "zapewnienie bezpieczeństwa ekip ratowniczych."},"category": "Ewakuacja"},{"id": 115,"q": "Obiektem budowlanym, którego projekt budowlany podlega obowiązkowi uzgodnienia pod względem ochrony przeciwpożarowej jest:","options": {"a": "tuneli długości 100 m,","b": "budynek niski zakwalifikowany do kategorii zagrożenia ludzi ZL III o powierzchni wewnętrznej 1000 m2,","c": "obiekt budowlany PM o powierzchni wewnętrznej 2500 m2 i projektowanej gęstości obciążenia ogniowego do 1000 МJ/m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 116,"q": "Obowiązek uzgodnienia pod względem zgodności z wymaganiami ochrony przeciwpożarowej projektu urządzenia przeciwpożarowego określa:","options": {"a": "ustawa o ochronie przeciwpożarowej,","b": "rozporządzenie Ministra Spraw Wewnętrznych i Administracji w sprawie uzgadniania projektu budowlanego pod względem ochrony przeciwpożarowej,","c": "obydwa wymienione powyżej akty prawne."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 117,"q": "W ramach opracowania scenariusza pożarowego uwzględnia się:","options": {"a": "przede wszystkim sposób funkcjonowania urządzeń przeciwpożarowych, innych technicznych środków zabezpieczenia przeciwpożarowego, urządzeń użytkowych lub technologicznych, oraz ich współdziałanie i oddziaływanie na siebie,","b": "przede wszystkim rozwiązania organizacyjne niezbędne do właściwego funkcjonowania projektowanych zabezpieczeń,","c": "zarówno kwestie wymienione pod literą a, jak i literą b."},"category": "Pozostałe / ogólne"},{"id": 118,"q": "Zawarta w projekcie budowlanym obiektu budowlanego informacja dotycząca doboru w nim urządzeń przeciwpożarowych i innych urządzeń służących bezpieczeństwu pożarowemu:","options": {"a": "powinna zawierać szczegółową charakterystykę tych urządzeń,","b": "powinna zawierać podstawową charakterystykę tych urządzeń,","c": "nie musi zawierać charakterystyki tych urządzeń."},"category": "Pozostałe / ogólne"},{"id": 119,"q": "Celem stosowania instalacji tryskaczowych ESFR jest:","options": {"a": "kontrola pożaru,","b": "ugaszenie pożaru,","c": "wobec nie określenia wymagań prawnych w przedmiotowym zakresie, wspomnianego celu nie określa się."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 120,"q": "Hydranty 33 powinny być stosowane w garażu wielokondygnacyjnym:","options": {"a": "w każdym przypadku,","b": "jedynie wtedy, gdy jest to garaż zamknięty,","c": "którego powierzchnia strefy pożarowej przekracza 1000 m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 121,"q": "Zgodnie z Polską Normą PN-B-02857:2017-04 „Ochrona przeciwpożarowa budynków. Przeciwpożarowe zbiorniki wodne. Wymagania ogólne.” stanowisko czerpania wody zbiornika zlokalizowanego w mieście i służącego do zabezpieczenia wysokiego budynku użyteczności publicznej powinno:","options": {"a": "mieć wymiary co najmniej 20 x 20 m,","b": "mieć wymiary co najmniej 15 x 5 m,","c": "zapewniać stanowisko postojowe dla samochodu pożarniczego o szerokości co najmniej 4 m i długości co najmniej 12 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 122,"q": "Przewód gazowy doprowadzony do pomieszczenia technicznego z zainstalowanymi kotłami o łącznej mocy cieplnej powyżej 60 kW do 2000 kW, zlokalizowanego w budynku o innym przeznaczeniu niż kotłownia, może służyć:","options": {"a": "zarówno do zasilania tych kotłów, jak i innych urządzeń gazowych w tym budynku,","b": "do zasilania tych kotłów, przy czym dopuszcza się zasilanie z niego pozostałych urządzeń gazowych, w tym budynku po zastosowaniu urządzenia sygnalizacyjno- odcinającego dopływ gazu do tego pomieszczenia,","c": "wyłącznie do zasilania tych kotłów."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 123,"q": "Zgodnie z przepisami określającymi wymagania dla urządzeń i systemów ochronnych przeznaczonych do użytku w atmosferze potencjalnie wybuchowej urządzenia grupy II kategorii 2 przeznaczone są do użytku w:","options": {"a": "miejscach, w których atmosfera wybuchowa spowodowana przez mieszaniny powietrza z gazami, parami, mgłami lub mieszaniny pyłowo-powietrzne występuje stale, często lub przez długi czas,","b": "przestrzeniach, w których zachodzi prawdopodobieństwo sporadycznego wystąpienia atmosfery wybuchowej spowodowanej przez gazy, pary, mgły lub mieszaniny pyłowo-powietrzne,","c": "przestrzeniach, w których występowanie atmosfery wybuchowej spowodowanej przez gazy, pary, mgły lub mieszaniny pyłowo-powietrzne jest mało prawdopodobne lub jeżeli ona rzeczywiście występuje, to ma to miejsce niezbyt często i jedynie przez krótki okres."},"category": "Zagrożenie wybuchem"},{"id": 124,"q": "Zgodnie ze specyfikacją techniczną PKN-CEN/TS 54-14:2006 „Systemy sygnalizacji pożarowej. Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji” czujki nie powinny być umieszczane bezpośrednio na wlocie świeżego powietrza z instalacji klimatyzacyjnej, przy czym gdy dopływ powietrza następuje przez sufit perforowany, to perforacja powinna być zaślepiona wokół każdej czujki w promieniu co najmniej:","options": {"a": "0,6 m,","b": "1,0 m,","c": "1,2 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 125,"q": "Średnica nominalna w milimetrach przewodów zasilających, na których instaluje się hydranty wewnętrzne z wężem półsztywnym o nominalnej średnicy węża 33 mm, powinna wynosić co najmniej:","options": {"a": "DN 32,","b": "DN 40,","c": "DN 50."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 126,"q": "Zgodnie z rozporządzeniem Ministra Infrastruktury w sprawie warunków technicznych, jakim powinny odpowiadać drogowe obiekty inżynierskie i ich usytuowanie, obowiązek posiadania przez tunel drogowy, m.in. punktów alarmowych oraz wyjść awaryjnych, dotyczy tunelu o długości większej niż:","options": {"a": "150 m,","b": "500 m,","c": "1000m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 127,"q": "Zgodnie z Polską Normą PN-EN 12845:2015-10 „Stałe urządzenia gaśnicze. Automatyczne urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja” pomieszczenie urządzeń pompowych znajdujące się w budynku chronionym urządzeniem tryskaczowym:","options": {"a": "jest wyłączone z ochrony tym urządzeniem,","b": "jest wyłączone z ochrony tym urządzeniem, jeżeli budynek wyposażony jest w system sygnalizacji pożarowej, a pomieszczenie stanowi odrębną strefę pożarową oddzieloną elementami o klasie odporności ogniowej co najmniej REI 120,","c": "powinno być chronione tym urządzeniem."},"category": "Odporność ogniowa i klasy budynków"},{"id": 128,"q": "Obowiązkowe ubezpieczenie odpowiedzialności cywilnej, któremu podlega rzeczoznawca do spraw zabezpieczeń przeciwpożarowych, obejmuje szkody wyrządzone w związku z uzgadnianiem:","options": {"a": "projektów budowlanych oraz projektów urządzeń przeciwpożarowych,","b": "projektów budowlanych, projektów urządzeń przeciwpożarowych oraz innej dokumentacji projektowej,","c": "wyłącznie projektów budowlanych."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 129,"q": "Zgodnie ze specyfikacją techniczną PKN-CEN/TS 54-14:2006 „Systemy sygnalizacji pożarowej. Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji” w przypadku stropów płaskich czujki należy sytuować w następujący sposób:","options": {"a": "bezpośrednio na stropie,","b": "tak, aby ich elementy detekcyjne znajdowały się w granicach górnych 5 % wysokości pomieszczenia,","c": "w odległości nie większej niż 0,5 m od powierzchni stropu."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 130,"q": "W przypadku ognioodpornej klapy odcinającej do przewodów wentylacji oddymiającej oznaczonej jako EI 120 (vedw i↔o) S1000C300AAmulti, oznaczenie „multi” wskazuje, że klapa:","options": {"a": "ma konstrukcję umożliwiającą jej montaż zarówno w położeniu poziomym, jak i pionowym,","b": "jest klapą wielostrefową,","c": "ma konstrukcję umożliwiającą jej montaż w zespole (baterii) wielu klap przylegających do siebie."},"category": "Odporność ogniowa i klasy budynków"},{"id": 131,"q": "Odległość projektowanego zbiornika gazu płynnego na samodzielnej stacji gazu płynnego od budynku użyteczności publicznej powinna wynosić co najmniej:","options": {"a": "30 m,","b": "60 m,","c": "30 m w przypadku zastosowania ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 120, zasłaniającej zbiornik od strony tego budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 132,"q": "Jednym z parametrów, którego przekroczenie uznaje się za wystąpienie w obiekcie budowlanym metra, krytycznego dla życia i zdrowia ludzi warunku środowiskowego, jest:","options": {"a": "zasięg widzialności mniejszy niż 5 m na wysokości mniejszej lub równej 1,8 m od poziomu drogi ewakuacyjnej,","b": "zasięg widzialności mniejszy niż 10 m na wysokości mniejszej lub równej 1,8 m od poziomu drogi ewakuacyjnej,","c": "zasięg widzialności mniejszy niż 10 m na wysokości mniejszej lub równej 2 m od poziomu drogi ewakuacyjnej."},"category": "Ewakuacja"},{"id": 133,"q": "Średnice nominalne w milimetrach (DN) przewodów wodociągowych wykonanych z rur stalowych w odgałęzieniach sieci obwodowej, na których przewiduje się instalowanie hydrantów zewnętrznych przeciwpożarowych, powinny:","options": {"a": "wynosić co najmniej DN 100,","b": "wynosić co najmniej DN 80,","c": "być określane na podstawie obliczeń hydraulicznych."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 134,"q": "Zgodnie z rozporządzeniem Ministra Edukacji Narodowej z dnia 31 grudnia 2014 r. w sprawie wymagań ochrony przeciwpożarowej, jakie musi spełniać lokal, w którym jest prowadzone przedszkole utworzone w wyniku przekształcenia oddziału przedszkolnego lub oddziałów przedszkolnych zorganizowanych w szkole podstawowej (Dz. U. z 2015 r. poz. 20), dzieci przebywające w lokalu przedszkola mogą, po spełnieniu określonych warunków, korzystać ze znajdujących się poza tym lokalem:","options": {"a": "szkolnej stołówki, szatni oraz sali gimnastycznej,","b": "szkolnej stołówki i szatni, a korzystanie z sali gimnastycznej jest niedopuszczalne,","c": "szkolnej szatni, a korzystanie ze stołówki i sali gimnastycznej jest niedopuszczalne."},"category": "Pozostałe / ogólne"},{"id": 135,"q": "Zgodnie z rozporządzeniem Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2015 r. poz. 1422), za niepalny nie można uznać wyrobu budowlanego o klasie reakcji na ogień:","options": {"a": "A2-s1, d1,","b": "A2-s3, d0,","c": "A1."},"category": "Reakcja na ogień i materiały"},{"id": 136,"q": "W jednokondygnacyjnym budynku produkcyjno-magazynowym w klasie odporności pożarowej „E”, niewyposażonym w stałe samoczynne urządzenia gaśnicze wodne, konstrukcja nośna antresoli przeznaczonej do użytku przez 15 osób powinna mieć klasę odporności ogniowej co najmniej:","options": {"a": "R 60,","b": "R 30,","c": "„-” (nie stawia się wymagań dla konstrukcji nośnej antresoli)."},"category": "Odporność ogniowa i klasy budynków"},{"id": 137,"q": "Zgodnie z art. 10 ust. 1 ustawy z dnia 16 kwietnia 2004 r. o wyrobach budowlanych (Dz. U. z 2016 r. poz. 1570), dopuszczone do jednostkowego zastosowania w obiekcie budowlanym są wyroby budowlane, wykonane według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla których producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami, z wyłączeniem wyrobów budowlanych:","options": {"a": "objętych normą zharmonizowaną lub zgodnych z wydaną dla niego europejską oceną techniczną,","b": "objętych krajową ocena techniczną,","c": "wymienionych zarówno w lit. A i lit. B."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 138,"q": "Kurtyny dymowe, które muszą ze względu na wymagania ochrony przeciwpożarowej funkcjonować w przypadku pożaru w warunkach wyższych temperatur powinny być sklasyfikowane jako:","options": {"a": "D XX, gdzie XX oznacza czas w minutach, np. D 30, D 60, D 120,","b": "D600 XX, gdzie XX oznacza czas w minutach, np. D600 30, D600 60, D600 120,","c": "DH XX, gdzie XX oznacza czas w minutach, np. DH 30, DH 60, DH 120."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 139,"q": "Przy zapotrzebowaniu na wodę do celów przeciwpożarowych przekraczającym 20 dm3/s dopuszcza się, jako rezerwowe źródło energii dla pomp w pompowniach przeciwpożarowych, zastosowanie agregatu prądotwórczego napędzanego silnikiem spalinowym z zapasem paliwa wystarczającym na czas pracy przy pełnym obciążeniu, co najmniej:","options": {"a": "60 minut,","b": "120 minut,","c": "240 minut."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 140,"q": "Zespoły kablowe stosowane w systemach zasilania i sterowania urządzeniami służącymi ochronie przeciwpożarowej zlokalizowane w pomieszczeniach chronionych stałym urządzeniem gaśniczym tryskaczowym mogą być uznane za odporne na działanie wody, jeżeli będą:","options": {"a": "umieszczone powyżej sekcji tryskaczowych,","b": "umieszczone w przestrzeni pomiędzy stropem a sufitem podwieszonym,","c": "ułożone w ognioochronnych kanałach kablowych."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 141,"q": "Magazyny karbidu powinny spełniać wymagania dotyczące pomieszczeń:","options": {"a": "zagrożonych wybuchem,","b": "zagrożonych wybuchem, jeżeli przewidywany przyrost ciśnienia w pomieszczeniu, jaki mógłby zostać spowodowany przez wybuch, jest większy od 2 kPa,","c": "zagrożonych wybuchem, jeżeli przewidywany przyrost ciśnienia w pomieszczeniu, jaki mógłby zostać spowodowany przez wybuch, jest większy od 5 kPa."},"category": "Zagrożenie wybuchem"},{"id": 142,"q": "Kabel oznaczony symbolami YnTKSYekw może być zastosowany do wykonania obwodów:","options": {"a": "linii dozorowych czujek pożarowych,","b": "linii sterowniczych od central oddymiania do siłowników klap dymowych i okien napowietrzających w klatkach schodowych,","c": "zasilania wentylatorów oddymiających wentylacji pożarowej."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 143,"q": "Przyspieszacz w powietrznej sekcji tryskaczowej służy:","options": {"a": "skróceniu czasu do otwarcia tryskaczy oraz skróceniu czasu do otwarcia zaworu kontrolno-alarmowego,","b": "skróceniu czasu do otwarcia zaworu kontrolno-alarmowego,","c": "skróceniu czasu do przesłania sygnału alarmowego oraz skróceniu czasu do otwarcia tryskaczy."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 144,"q": "Zgodnie z Polską Normą PN-B-02857:2017-04 „Ochrona przeciwpożarowa budynków. Przeciwpożarowe zbiorniki wodne. Wymagania ogólne.” elementy oddzielenia przeciwpożarowego wydzielające pomieszczenie w budynku, w którym zlokalizowano przeciwpożarowy zbiornik wodny, powinny mieć klasę odporności ogniowej zapewniającą możliwość poboru wody przez czas nie mniejszy niż:","options": {"a": "obliczeniowy czas trwania pożaru,","b": "obliczeniowy czas trwania pożaru, jednak nie krótszy niż 2 godziny,","c": "obliczeniowy czas trwania pożaru, jednak nie krótszy niż 4 godziny."},"category": "Odporność ogniowa i klasy budynków"},{"id": 145,"q": "Zgodnie z przepisami przeciwpożarowymi, doprowadzenie drogi pożarowej jest wymagane, do budynku zawierającego strefę pożarową zakwalifikowaną do kategorii zagrożenia ludzi ZL V:","options": {"a": "niskiego, mającego 50 miejsc noclegowych,","b": "średniowysokiego,","c": "w obu powyższych przypadkach."},"category": "Drogi pożarowe i dojazd"},{"id": 146,"q": "Do wykrywania pożaru w sali konferencyjnej o wysokości 4,5 m, długości 24 m i szerokości 6 m, w której na suficie występują 2 belki konstrukcyjne o wysokości 0,2 m, dzielące sufit na 3 równe pola w poprzek jego długości, jest wymagane zastosowanie, co najmniej:","options": {"a": "1 punktowej czujki dymu,","b": "2 punktowych czujek dymu,","c": "3 punktowych czujek dymu."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 147,"q": "Zastosowanie samoczynnego urządzenia oddymiającego uruchamianego za pomocą systemu wykrywania dymu w budynku jednokondygnacyjnym zakwalifikowanym do kategorii zagrożenia ludzi ZL I umożliwia:","options": {"a": "obniżenie klasy odporności pożarowej budynku o jedną oraz wydłużenie dopuszczalnej długości przejścia ewakuacyjnego o 50%,","b": "powiększenie powierzchni strefy pożarowej maksymalnie o 50% i wydłużenie dopuszczalnej długości przejścia ewakuacyjnego o 50%,","c": "powiększenie powierzchni strefy pożarowej maksymalnie o 100% i wydłużenie dopuszczalnej długości przejścia ewakuacyjnego o 50%."},"category": "Ewakuacja"},{"id": 148,"q": "Awaryjne oświetlenie ewakuacyjne w jednokondygnacyjnym budynku muzeum powinno być zastosowane:","options": {"a": "tylko w salach wystawowych o powierzchni ponad 100 m2 przeznaczonych dla ponad 50 osób i na drogach ewakuacyjnych z tych pomieszczeń oświetlonych wyłącznie światłem sztucznym,","b": "tylko w salach wystawowych o powierzchni ponad 300 m2 przeznaczonych dla ponad 100 osób i na drogach ewakuacyjnych z tych pomieszczeń,","c": "w salach wystawowych niezależnie od ich powierzchni i liczby przebywających osób oraz na drogach ewakuacyjnych z tych pomieszczeń."},"category": "Ewakuacja"},{"id": 149,"q": "Powierzchnia strefy pożarowej PM o gęstości obciążenia ogniowego równej 2000 MJ/m2, z pomieszczeniami zagrożonymi wybuchem, w wielokondygnacyjnym budynku o wysokości równej 25 m, chronionym całkowicie samoczynnym urządzeniem wodnym tryskaczowym, powinna być:","options": {"a": "nie większa niż 2000 m2,","b": "nie większa niż 1000 m2,","c": "nie dopuszcza się takich przypadków."},"category": "Odporność ogniowa i klasy budynków"},{"id": 150,"q": "W 7 kondygnacyjnym budynku magazynowym, w strefie pożarowej o gęstości obciążenia ogniowego 500 MJ/m2, wyposażonej w stałe samoczynne urządzenie oddymiające sterowane przez system wykrywania dymu, w pomieszczeniu o wysokości wynoszącej 5 m, maksymalna dopuszczalna długość przejścia ewakuacyjnego wynosi:","options": {"a": "150 m,","b": "175 m,","c": "225 m."},"category": "Ewakuacja"},{"id": 151,"q": "Budynek IN do przechowywania płodów rolnych, stanowiący odrębną strefę pożarową o kubaturze brutto 1000 m3:","options": {"a": "powinien być wybudowany co najmniej w klasie E odporności pożarowej,","b": "powinien być wybudowany w klasie odporności pożarowej wynikającej z ustalonej wielkości gęstości obciążenia ogniowego,","c": "jest zwolniony z wymagań dotyczących klasy odporności pożarowej."},"category": "Pozostałe / ogólne"},{"id": 152,"q": "Zgodnie z Polską Normą PN-B-02852:2001 „Ochrona przeciwpożarowa budynków. Obliczanie gęstości obciążenia ogniowego oraz wyznaczanie względnego czasu trwania pożaru.” przy obliczaniu gęstości obciążenia ogniowego nie uwzględnia się materiałów o zawartości wody ponad:","options": {"a": "40 %,","b": "60 %,","c": "80 %."},"category": "Pozostałe / ogólne"},{"id": 153,"q": "Na terenie bazy paliw płynnych stanowiska służące do przeładunku produktów naftowych I i II klasy powinny być oddalone od ogrodzenia baz paliw co najmniej o:","options": {"a": "5 m,","b": "10 m,","c": "15 m."},"category": "Pozostałe / ogólne"},{"id": 154,"q": "Dopuszczalna długość drugiego dojścia ewakuacyjnego w budynku wielofunkcyjnym, stanowiącym jedną strefę pożarową, którego poszczególne kondygnacje zaliczane są do jednej z kategorii zagrożenia ludzi, tj. ZL II, ZL I, ZL III, wynosi:","options": {"a": "60 m,","b": "80 m dla ZL I i ZL II oraz 120 m dla ZL III,","c": "80 m."},"category": "Ewakuacja"},{"id": 155,"q": "Wykładzina podłogowa w sali konferencyjnej przeznaczonej dla 200 osób powinna charakteryzować się klasą reakcji na ogień co najmniej:","options": {"a": "Bfl-s2,","b": "Cfl-s2,","c": "Efl."},"category": "Reakcja na ogień i materiały"},{"id": 156,"q": "Dla budynku mieszkalno-usługowego o wysokości 13,5 m i czterech kondygnacjach nadziemnych, w którym pierwszą kondygnację nadziemną stanowi odrębna strefa pożarowa zaliczona do kategorii zagrożenia ludzi ZL III, natomiast pozostałe kondygnacje zaliczone zostały do kategorii zagrożenia ludzi ZL IV, dopuszcza się przyjęcie najniższej klasy odporności pożarowej:","options": {"a": "D,","b": "C,","c": "B."},"category": "Odporność ogniowa i klasy budynków"},{"id": 157,"q": "Zapas środka pianotwórczego do urządzeń gaśniczych pianowych na terenie bazy paliw płynnych powinien wystarczyć na okres:","options": {"a": "30 minut,","b": "zużycia wymaganego zapasu wody,","c": "dwugodzinnego zużycia zapasu wody do gaszenia pożaru największego zbiornika."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 158,"q": "Pojemność zbiornika pośredniego uzupełnianego z sieci wodociągowej z natężeniem przepływu 10 dm3/s, stanowiącego wraz z pompą źródło wody dla instalacji tryskaczowej, której czas działania jest równy 60 min, przy wymaganym natężeniu przepływu wynikającym z obliczeń hydraulicznych wynoszącym 1800 dm3/min powinna być nie mniejsza niż:","options": {"a": "36 m3,","b": "72 m3,","c": "108 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 159,"q": "Dla budynku produkcyjnego, dla którego zapotrzebowanie na wodę do zewnętrznego gaszenia pożaru wynosi 40 dm3/s, względny czas trwania pożaru wynosi 6 godzin, a wydajność wodociągu wynosi 10 dm3/s, należy zapewnić uzupełniający zapas wody w zbiorniku przeciwpożarowym w ilości co najmniej:","options": {"a": "432 m3,","b": "576 m3,","c": "648 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 160,"q": "W ramach opracowania scenariusza pożarowego uwzględnia się:","options": {"a": "przede wszystkim sposób funkcjonowania urządzeń przeciwpożarowych, innych technicznych środków zabezpieczenia przeciwpożarowego, urządzeń użytkowych lub technologicznych, oraz ich współdziałanie i oddziaływanie na siebie,","b": "przede wszystkim rozwiązania organizacyjne niezbędne do właściwego funkcjonowania projektowanych zabezpieczeń,","c": "zarówno kwestie wymienione pod literą A, jak i literą B."},"category": "Pozostałe / ogólne"},{"id": 161,"q": "Lokal punktu przedszkolnego, znajdujący się na parterze budynku, w strefie pożarowej nie spełniającej wymagań ochrony przeciwpożarowej dla kategorii zagrożenia ludzi ZL II, chroniony stałym samoczynnym urządzeniem gaśniczym tryskaczowym, powinien być wyposażony w:","options": {"a": "gaśnicę proszkową ABC o zawartości co najmniej 4 kg środka gaśniczego,","b": "gaśnicę o skuteczności gaśniczej co najmniej 21 A, zgodnie z wymaganiami określonymi w przepisach dotyczących ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów, niezależnie od gaśnic zastosowanych w strefie pożarowej, w której znajduje się lokal,","c": "żadna z powyższych odpowiedzi nie jest prawidłowa."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 162,"q": "Zgodnie z Polską Normą PN-EN 15004-1:2008 Stałe urządzenia gaśnicze - Urządzenia gaśnicze gazowe - Część 1: Ogólne wymagania dotyczące projektowania i instalowania projektowe stężenie gaszące dla pożarów powierzchniowych klasy A powinno być:","options": {"a": "równe stężeniu gaszącemu wyznaczonemu wg normowej procedury badawczej,","b": "większe o co najmniej 30 % od stężenia gaszącego wyznaczonego wg normowej procedury badawczej,","c": "większe o co najmniej 50 % od stężenia gaszącego wyznaczonego wg normowej procedury badawczej."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 163,"q": "Tunele liniowe, stanowiące kolejowe obiekty inżynierskie, projektuje się i buduje lub przebudowuje przy zachowaniu wymagań bezpieczeństwa pożarowego sprecyzowanych w:","options": {"a": "rozporządzeniu Ministra Transportu i Gospodarki Morskiej z dnia 10 września 1998 r. w sprawie warunków technicznych, jakim powinny odpowiadać budowle kolejowe i ich usytuowanie (Dz. U. Nr 151, poz. 987 z późn. zm.),","b": "decyzji Komisji 2008/163/WE z dnia 20 grudnia 2007 r. dotyczącej technicznej specyfikacji interoperacyjności w zakresie aspektu \"Bezpieczeństwo w tunelach kolejowych\" transeuropejskiego systemu kolei konwencjonalnych i transeuropejskiego systemu kolei dużych prędkości (Dz. Urz. UE L 64 z 07.03.2008, str. 1, z późn. zm.),","c": "rozporządzeniu Ministra Transportu z dnia 19 marca 2007 r. w sprawie systemu zarządzania bezpieczeństwem w transporcie kolejowym (Dz. U. z 2016 r. poz. 328)."},"category": "Odporność ogniowa i klasy budynków"},{"id": 164,"q": "Dopuszczenie do jednostkowego zastosowania w obiekcie budowlanym, o którym mowa w art. 10 ustawy z dnia 16 kwietnia 2004 r. o wyrobach budowlanych (Dz. U. z 2016 r. poz. 1570 z późn. zm.):","options": {"a": "nie ma zastosowania do wyrobów służących zapewnieniu bezpieczeństwa pożarowego, chyba że dotyczy rozwiązań zamiennych uzgodnionych w trybie art. 6a ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej (Dz. U. z 2018 r. poz. 620) z komendantem wojewódzkim Państwowej Straży Pożarnej właściwym dla miejsca lokalizacji inwestycji, przy realizacji której wyroby te są wykorzystywane,","b": "może mieć zastosowanie w każdym przypadku wyrobu służącego zapewnieniu bezpieczeństwa pożarowego pod warunkiem jego wykonania według indywidualnej dokumentacji technicznej, sporządzonej przez projektanta obiektu lub z nim uzgodnionej, dla którego producent wydał oświadczenie, że zapewniono zgodność wyrobu budowlanego z tą dokumentacją oraz z przepisami,","c": "nie ma zastosowania do wyrobów służących zapewnieniu bezpieczeństwa pożarowego, objętych normą zharmonizowaną i wprowadzonych do obrotu lub udostępnionych na rynku krajowym zgodnie z rozporządzeniem Parlamentu Europejskiego i Rady (UE) nr 305/2011 z dnia 9 marca 2011 r. ustanawiające zharmonizowane warunki wprowadzania do obrotu wyrobów budowlanych i uchylające dyrektywę Rady 89/106/EWG (Dz. U. UE. L. z 2011 r. Nr 88, str. 5 z późn. zm.)."},"category": "Odporność ogniowa i klasy budynków"},{"id": 165,"q": "Zgodnie z przepisami dotyczącymi baz paliw płynnych, zbiorniki naziemne o osi głównej pionowej, przeznaczone do magazynowania produktów naftowych III klasy powinny być wyposażone w stałe lub półstałe urządzenia gaśnicze pianowe, gdy:","options": {"a": "rozpatrywane produkty są podgrzewane powyżej ich temperatury zapłonu,","b": "pojemność zbiornika przekracza 10 000 m3,","c": "pojemność zbiornika przekracza 32 000 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 166,"q": "Zgodnie Polską Normą PN-EN 12845 Stałe urządzenia gaśnicze - Automatyczne urządzenia tryskaczowe - Projektowanie, instalowanie i konserwacja przez punkt projektowy rozumie się:","options": {"a": "punkt na sieci przewodów rurowych, dla którego obliczane są ciśnienie i natężenie (-a) przepływu,","b": "punkt pracy pompy, dla którego ustalono nominalne dla instalacji tryskaczowej ciśnienie i wydatek,","c": "punkt na przewodzie rurowym rozdzielczym sekcji tryskaczowej wstępnie obliczonej, za którym sieć przewodów rurowych ma wymiary dobierane z tablic, a przed nim za pomocą obliczeń hydraulicznych."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 167,"q": "W przypadku jednokondygnacyjnego budynku handlowego, który w całości stanowi jedną strefę pożarową zakwalifikowaną do kategorii zagrożenia życia ludzi ZL I o powierzchni 9 500 m2:","options": {"a": "konieczne jest jego wyposażenie w samoczynne urządzenia gaśnicze wodne, system sygnalizacji pożarowej i dźwiękowy system ostrzegawczy,","b": "wystarczające jest jego wyposażenie w samoczynne urządzenia gaśnicze wodne i dźwiękowy system ostrzegawczego, ponieważ obiekty wyposażone w stałe urządzenia gaśnicze mogą być niewyposażone w system sygnalizacji pożarowej,","c": "wystarczające jest jego wyposażenie w system sygnalizacji pożarowej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 168,"q": "Obwody elektryczne instalacji bezpieczeństwa, zgodnie z PN-HD 60364-5-56 Instalacje elektryczne niskiego napięcia - Część 5-56: Dobór i montaż wyposażenia elektrycznego - Instalacje bezpieczeństwa nie mogą w żadnym przypadku przechodzić przez:","options": {"a": "strefy narażone na ryzyko pożarowe (BE2),","b": "strefy narażone na ryzyko wybuchu (BE3),","c": "pomieszczenia o dużym zagęszczeniu ludzi i trudnych warunkach ewakuacji ludzi (BD4)."},"category": "Ewakuacja"},{"id": 169,"q": "Budynek mieszkalny wielorodzinny o 9 kondygnacjach nadziemnych, który jest usytuowany bezpośrednio przy granicy niezabudowanej działki drogowej, powinien mieć od strony tej działki ścianę zewnętrzną wykonaną w klasie odporności ogniowej co najmniej:","options": {"a": "EI 60,","b": "REI 120, jako ściana oddzielenia przeciwpożarowego,","c": "EI 30."},"category": "Odporność ogniowa i klasy budynków"},{"id": 170,"q": "Tunel drogowy o długości większej niż 500 m powinien być wyposażony w:","options": {"a": "hydranty zewnętrzne nadziemne o średnicy nominalnej DN 80, usytuowane w tunelu w odległościach nieprzekraczających 250 m,","b": "hydranty zewnętrzne podziemne o średnicy nominalnej DN 100, usytuowane w tunelu w odległościach nieprzekraczających 150 m,","c": "hydranty zewnętrzne nadziemne DN 80 usytuowane w tunelu przy punktach alarmowych w odległościach nieprzekraczających 150 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 171,"q": "Obudowa schodów na stacji metra powinna mieć klasę reakcji na ogień co najmniej:","options": {"a": "A2-s1, d0,","b": "B-s1, d0,","c": "C-s1, d0."},"category": "Reakcja na ogień i materiały"},{"id": 172,"q": "Zgodnie z Polską Normą PN-EN 81-58:2005 Przepisy bezpieczeństwa dotyczące budowy i instalowania dźwigów - Badania i próby - Część 58: Próba odporności ogniowej drzwi przystankowych, odporność ogniową drzwi dźwigowych przystankowych określa się przy narażeniu na działanie ognia od strony:","options": {"a": "podestu przystankowego,","b": "podestu przystankowego oraz szybu dźwigowego,","c": "podestu przystankowego oraz ciepła i dymu od strony szybu dźwigowego."},"category": "Odporność ogniowa i klasy budynków"},{"id": 173,"q": "W budynku magazynowym, awaryjne oświetlenie ewakuacyjne należy zastosować w pomieszczeniu:","options": {"a": "przeznaczonym dla ponad 200 osób,","b": "o powierzchni netto ponad 1000 m2,","c": "o powierzchni netto ponad 2000 m2."},"category": "Ewakuacja"},{"id": 174,"q": "Czy rzeczoznawca do spraw zabezpieczeń przeciwpożarowych jest uprawniony do potwierdzania, w formie opinii, faktu spełniania wymagań przeciwpożarowych w obiektach, innych niż hotelarskie, w których są świadczone usługi hotelarskie:","options": {"a": "tak,","b": "nie, ponieważ do wydawania opinii uprawniony jest wyłącznie właściwy miejscowo komendant powiatowy (miejski) Państwowej Straży pożarnej,","c": "nie, ponieważ takie uprawnienie przysługuje osobom wykonującym czynności z zakresu ochrony przeciwpożarowej, o których mowa w art. 4 ust. 2a ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 175,"q": "Zgodnie z PN-B-02857:2017-04 Ochrona przeciwpożarowa - Przeciwpożarowe zbiorniki wodne - Wymagania ogólne głębokość przeciwpożarowego zbiornika wodnego, który nie jest chroniony przed zamarzaniem, nie powinna być mniejsza niż:","options": {"a": "1 m,","b": "2 m,","c": "3 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 176,"q": "W jednokondygnacyjnym budynku magazynowym podzielonym na dwie strefy pożarowe, każda o gęstości obciążenia ogniowego powyżej 4000 MJ/m2 i powierzchni 1000 m2, w dachu którego znajdują się klapy dymowe, ścianę oddzielenia przeciwpożarowego usytuowaną od nich w odległości poziomej mniejszej niż 5 m, należy wyprowadzić:","options": {"a": "na wysokość co najmniej 0,3 m ponad pokrycie dachu,","b": "na wysokość co najmniej 0,3 m ponad górną krawędź tych klap,","c": "na wysokość co najmniej 0,3 m ponad górną krawędź tych klap, przy czym wymaganie to nie dotyczy klap o klasie odporności ogniowej co najmniej E 30."},"category": "Odporność ogniowa i klasy budynków"},{"id": 177,"q": "Zgodnie Polską Normą PN-EN 12845 Stałe urządzenia gaśnicze - Automatyczne urządzenia tryskaczowe - Projektowanie, instalowanie i konserwacja maksymalna powierzchnia chroniona przez jeden tryskacz w budynku biurowym zwierającym pomieszczenia jednoprzestrzenne (typu „open space”) o powierzchniach większych niż 126 m2, nie powinna być większa niż:","options": {"a": "9 m2,","b": "12 m2,","c": "21 m2."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 178,"q": "Główne elementy konstrukcyjne w niepodpiwniczonym budynku o wysokości 11,5 m, w którym na pierwszych 3 kondygnacjach znajdują się mieszkania, a na ostatniej kondygnacji garaż wbudowany na 10 miejsc postojowych, powinny mieć w obrębie części mieszkalnej klasę odporności ogniowej co najmniej:","options": {"a": "R 30,","b": "R 60,","c": "R 120."},"category": "Odporność ogniowa i klasy budynków"},{"id": 179,"q": "Zgodnie z Polską Normą PN-EN 60079-10-1:2016-02 Atmosfery wybuchowe - Część 10-1: Klasyfikacja przestrzeni - Gazowe atmosfery wybuchowe rozróżnia się następujące poziomy dostępności (dyspozycyjności) wentylacji:","options": {"a": "dobry, dostateczny i słaby,","b": "wysoki, średni, niski i pomijalny,","c": "norma nie przewiduje określania dostępności (dyspozycyjności) wentylacji a miarą jej skuteczności są trzy stopnie rozcieńczenia."},"category": "Zagrożenie wybuchem"},{"id": 180,"q": "W średniowysokim budynku mieszkalnym wielorodzinnym ze strefą pożarową ZL III o powierzchni 250 m2, obejmującą pierwszą kondygnację nadziemną i podziemną, strefę tę należy wyposażyć w:","options": {"a": "hydranty 25,","b": "hydranty 33,","c": "nie jest wymagane stosowanie hydrantów wewnętrznych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 181,"q": "Zgodnie z Polską Normą PN-B-02852:2001 Ochrona przeciwpożarowa budynków - Obliczanie gęstości obciążenia ogniowego oraz wyznaczanie względnego czasu trwania pożaru przy obliczaniu gęstości obciążenia ogniowego nie uwzględnia się materiałów:","options": {"a": "niepalnych i niezapalnych,","b": "palnych o zawartości wody ponad 60 %,","c": "mrożonek owocowo-warzywnych w kartonach."},"category": "Reakcja na ogień i materiały"},{"id": 182,"q": "Ograniczenia, w stosunku do łącznej powierzchni otworów w ścianach oddzieleń przeciwpożarowych, która nie powinna przekraczać 15% powierzchni tych ścian, nie mają zastosowania w ścianach oddzieleń przeciwpożarowych:","options": {"a": "w garażach, w stosunku do ścian oddzieleń przeciwpożarowych, które znajdują się na drogach manewrowych,","b": "w galeriach handlowych, w stosunku do ścian oddzieleń przeciwpożarowych, które nie znajdują się na drogach ewakuacyjnych,","c": "mają zastosowanie bezwzględnie w każdym przypadku."},"category": "Ewakuacja"},{"id": 183,"q": "W ścianach zewnętrznych budynku wielokondygnacyjnego nad strefą pożarową PM, o gęstości obciążenia ogniowego do 1000 MJ/m2 zawierającą pomieszczenie zagrożone wybuchem, wysokość pasa międzykondygnacyjnego powinna wynosić:","options": {"a": "co najmniej 0,8 m,","b": "co najmniej 1,2 m,","c": "co najmniej 2 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 184,"q": "Zgodnie z rozporządzeniem Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie (Dz. U. z 2014 r. poz. 1853 z późn. zm.) w promieniu 1,5 m od wlotu przewodu oddechowego (odpowietrzenia) zbiornika podziemnego, przeznaczonego do magazynowania produktów naftowych I klasy, wyznacza się strefę zagrożenia wybuchem:","options": {"a": "strefę 0,","b": "strefę 2,","c": "strefę 20."},"category": "Zagrożenie wybuchem"},{"id": 185,"q": "W wolnostojącym budynku mieszkalnym wielorodzinnym o 5 kondygnacjach nadziemnych, posiadającym jedną ewakuacyjną klatkę schodową, w którym długość dojścia ewakuacyjnego wynosi 76 m, okno w ścianie zewnętrznej tej klatki, znajdujące się w odległości 2 m od okna mieszkania usytuowanego w ścianie zewnętrznej tego samego budynku, prostopadłej do ściany zewnętrznej klatki, powinno być wykonane w klasie odporności ogniowej co najmniej:","options": {"a": "EI 30,","b": "EI 60,","c": "może być wykonane bez klasy odporności ogniowej."},"category": "Ewakuacja"},{"id": 186,"q": "W budynku IN, odległość od najdalszego stanowiska dla zwierząt do wyjścia ewakuacyjnego przy bezściółkowym utrzymaniu zwierząt, nie powinna przekraczać:","options": {"a": "50 m,","b": "75 m,","c": "odległości tej nie reguluje się pod warunkiem zastosowania dwóch wyjść ewakuacyjnych powyżej 15 sztuk bydła."},"category": "Ewakuacja"},{"id": 187,"q": "W projektowanym budynku biurowym wysokim (W) ze strefami pożarowymi ZL III, korytarze ewakuacyjne o długości 90 m:","options": {"a": "należy podzielić na odcinki nie dłuższe niż 50 m za pomocą drzwi dymoszczelnych klasy co najmniej Sa,","b": "należy podzielić na odcinki nie dłuższe niż 50 m za pomocą drzwi dymoszczelnych klasy Sm lub S200,","c": "żadna z powyższych odpowiedzi nie jest prawidłowa."},"category": "Ewakuacja"},{"id": 188,"q": "Do wykrywania pożaru w pomieszczeniu biurowym typu „open space” o wysokości 4,5 m, długości 30 m i szerokości 20 m, w którym na suficie występują 4 belki stropowe o wysokości 21 cm, dzielące przestrzeń sufitu na 5 równych pól o wymiarach 20 m × 6 m, jest wymagane zastosowanie, co najmniej:","options": {"a": "10 punktowych czujek dymu,","b": "6 punktowych czujek dymu,","c": "5 punktowych czujek dymu."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 189,"q": "W przypadku występowania w budynku wysokim przedsionka przeciwpożarowego z dwoma drzwiami prowadzącymi do powierzchni użytkowej (np. jednoprzestrzennych pomieszczeń biurowych typu „open space”), zgodnie z Polską Normą PN-EN 12101-6 Systemy kontroli rozprzestrzeniania dymu i ciepła - Część 6: Wymagania techniczne dotyczące systemów różnicowania ciśnień - Zestawy urządzeń, w systemie klasy F minimalna prędkość przepływu powietrza przez wszystkie otwarte drzwi między przedsionkiem a strefą objętą pożarem, nie powinna być niższa niż:","options": {"a": "0,75 m/s,","b": "1 m/s,","c": "2 m/s."},"category": "Odporność ogniowa i klasy budynków"},{"id": 190,"q": "W budynku hotelu o wysokości 15 m, stanowiącym w całości jedną strefę pożarową o powierzchni 4000 m2, drzwi do pomieszczenia bagażowni, które jest dostępne z holu z recepcją stanowiącego drogę komunikacji ogólnej, przez który nie prowadzi droga ewakuacyjna z klatki schodowej, powinny być wykonane:","options": {"a": "w klasie odporności ogniowej co najmniej EI 30,","b": "w klasie odporności ogniowej co najmniej EI 30 i klasie dymoszczelności co najmniej Sa,","c": "żadna z powyższych odpowiedzi nie jest prawidłowa."},"category": "Ewakuacja"},{"id": 191,"q": "Dla budynku hotelowego o kubaturze brutto 2500 m3 i o powierzchni wewnętrznej 450 m2 znajdującego się poza jednostką osadniczą przeciwpożarowe zaopatrzenie w wodę do zewnętrznego gaszenia pożaru:","options": {"a": "jest wymagane w ilości co najmniej 10 dm3/s,","b": "jest wymagane w ilości co najmniej 20 dm3/s,","c": "nie jest wymagane."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 192,"q": "Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczeń:","options": {"a": "wszystkich w strefie pożarowej zakwalifikowanej do kategorii ludzi ZL II, przeznaczonych dla ponad 6 osób,","b": "zlokalizowanych w strefie pożarowej ZL II przeznaczonych dla ponad 6 osób o ograniczonej zdolności poruszania się,","c": "z wyznaczoną strefą zagrożenia wybuchem."},"category": "Ewakuacja"},{"id": 193,"q": "W pięciokondygnacyjnym budynku zakwalifikowanym w całości do kategorii zagrożenia ludzi ZL IV, ze względu na przekroczenie dopuszczalnej długości dojścia ewakuacyjnego, konieczne jest zamknięcie ewakuacyjnej klatki schodowej:","options": {"a": "drzwiami przeciwpożarowymi o klasie odporności ogniowej EI z samozamykaczem,","b": "drzwiami przeciwpożarowymi o klasie odporności ogniowej EI 30 dymoszczelnymi klasy Sa z samozamykaczem,","c": "drzwiami przeciwpożarowymi o klasie odporności ogniowej EI 30 dymoszczelnymi klasy S200 z samozamykaczem."},"category": "Ewakuacja"},{"id": 194,"q": "Każdy dźwig dla ekip ratowniczych w budynku powinien mieć połączenie z drogą pożarową dojściem:","options": {"a": "o długości nie większej niż 50 m, przy czym długości tego dojścia w obrębie budynku nie ogranicza się,","b": "o długości nie większej niż 50 m, przy czym długość tego dojścia w obrębie budynku nie powinna przekraczać dopuszczalnej długości dojścia ewakuacyjnego dla strefy pożarowej, przez którą ono przebiega,","c": "o długości nie większej niż 50 m, przy czym długość tego dojścia w obrębie budynku nie powinna przekraczać dopuszczalnej długości dojścia lub przejścia ewakuacyjnego dla strefy pożarowej lub pomieszczenia, przez które ono przebiega."},"category": "Ewakuacja"},{"id": 195,"q": "Maksymalna powierzchnia strefy dozorowej w budynku chronionym systemem sygnalizacji pożarowej z indywidualną adresacją czujek pożarowych w liniach dozorowych otwartych klasy „B”, zgodnie PKN-CEN TS 54-14: 2006 Systemy sygnalizacji pożarowej - Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, nie powinna przekraczać:","options": {"a": "6 000 m2,","b": "1 000 m2,","c": "1 600 m2."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 196,"q": "W jednokondygnacyjnym budynku produkcyjnym o wysokości kondygnacji w świetle 8 m, stanowiącym w całości jedną strefę pożarową o gęstości obciążenia ogniowego 5000 MJ/m2, która jest wyposażona w system sygnalizacji pożarowej oraz stałe samoczynne urządzenie gaśnicze tryskaczowe, maksymalna długość przejścia ewakuacyjnego wynosi:","options": {"a": "150 m,","b": "175 m,","c": "225 m."},"category": "Ewakuacja"},{"id": 197,"q": "Minimalna pojemność użyteczna zbiornika pośredniego uzupełnianego z sieci wodociągowej z natężeniem przepływu 5 l/s, stanowiącego wraz z pompą źródło wody dla instalacji tryskaczowej, której czas działania jest równy 60 min, przy wymaganym natężeniu przepływu wynikającym z obliczeń hydraulicznych wynoszącym 1200 dm3/min powinna wynosić:","options": {"a": "36 m3,","b": "72 m3,","c": "54 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 198,"q": "Zgodnie z Polską Normą PN-B-02857:2017-04 Ochrona przeciwpożarowa budynków - Przeciwpożarowe zbiorniki wodne - Wymagania ogólne przeciwpożarowy zbiornik wodny o pojemności 300 m3 zaprojektowany do pracy ze ssaniem, powinien posiadać co najmniej:","options": {"a": "jeden przewód ssawny,","b": "dwa przewody ssawne,","c": "trzy przewody ssawne."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 199,"q": "Powierzchnia strefy pożarowej ZL I w wielokondygnacyjnym budynku średniowysokim (SW), chronionym całkowicie przez stałe samoczynne urządzenie gaśnicze na mgłę wodną i wyposażonym w samoczynne urządzenia oddymiające uruchamianymi za pomocą systemu wykrywania dymu, powinna być nie większa niż:","options": {"a": "10 000 m2,","b": "12 500 m2,","c": "15 000 m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 200,"q": "Dla obiektu budowlanego niebędącego budynkiem, przeznaczonego na potrzeby użyteczności publicznej, w którym znajduje się strefa pożarowa przeznaczona do jednoczesnego przebywania ponad 50 osób, niebędących jej stałymi użytkownikami, zapewnienie przeciwpożarowego zaopatrzenia w wodę do zewnętrznego gaszenia pożaru jest:","options": {"a": "wymagane w ilości co najmniej 10 dm3/s,","b": "wymaganej w ilości co najmniej 20 dm3/s,","c": "nie wymagane, gdyż woda do celów przeciwpożarowych do zewnętrznego gaszenia pożaru jest zapewniana w ramach ilości wody przewidywanych dla jednostek osadniczych."},"category": "Strefy pożarowe i oddzielenia"},{"id": 201,"q": "Temperatura w pomieszczeniu magazynowym butli z gazami palnymi nie powinna przekraczać:","options": {"a": "35°C,","b": "najniższej temperatury zapłonu magazynowanych gazów,","c": "2/3 maksymalnej temperatury powierzchni wyrażonej w stopniach Celsjusza (°C), określonej Polską Normą dotyczącą urządzeń elektrycznych w przestrzeniach zagrożonych wybuchem dla poszczególnych klas temperaturowych gazów."},"category": "Zagrożenie wybuchem"},{"id": 202,"q": "Minimalna odległość silosa na zboże o pojemności większej niż 100 ton od otworów okiennych i drzwiowych budynku mieszkalnego wynosi:","options": {"a": "8 m,","b": "15 m,","c": "20 m."},"category": "Pozostałe / ogólne"},{"id": 203,"q": "Działka budowlana, o której mowa w przepisach rozporządzenia Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2019 r. poz. 1065), może obejmować:","options": {"a": "tylko jedną działkę ewidencyjną,","b": "nie więcej niż 2 działki ewidencyjne,","c": "wiele działek ewidencyjnych."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 204,"q": "Do średniowysokiego budynku zawierającego wyłącznie strefę pożarową produkcyjną o gęstości obciążenia ogniowego poniżej 500 MJ/m2 wymagane jest zapewnienie drogi pożarowej, jeżeli:","options": {"a": "w budynku występuje pomieszczenie zagrożone wybuchem,","b": "powierzchnia strefy pożarowej przekracza 10 000 m2,","c": "powierzchnia strefy pożarowej przekracza 20 000 m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 205,"q": "Wymaganą ilość wody do celów przeciwpożarowych dla składów i magazynów z gazami palnymi i cieczami o temperaturze zapłonu do 373,15 K (100 °C), zlokalizowanych poza budynkami, służąca do zewnętrznego gaszenia pożaru określa się na postawie:","options": {"a": "zajmowanej powierzchni w m2,","b": "całkowitej objętości zgromadzonych cieczy i gazów palnych w m3,","c": "gęstość obciążenia ogniowego w MJ/m2 i powierzchni strefy pożarowej składowiska w m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 206,"q": "Magazyn butli z gazem płynnym, zlokalizowany na terenie bazy i rozlewni gazu płynnego, powinien być usytuowany od budynków mieszkalnych, budynków zamieszkania zbiorowego oraz obiektów użyteczności publicznej w odległości co najmniej:","options": {"a": "20 m,","b": "30 m,","c": "60 m."},"category": "Pozostałe / ogólne"},{"id": 207,"q": "Zgodnie z Polską Normą PN-EN 12845 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja urządzenia tryskaczowe służące do ochrony przestrzeni biurowych w budynku wysokościowym powinny być projektowane zgodnie z wymaganiami dotyczącymi klasy zagrożenia pożarowego:","options": {"a": "LH,","b": "OH2,","c": "OH3."},"category": "Odporność ogniowa i klasy budynków"},{"id": 208,"q": "Zgodnie z Polską Normą PN-EN 12845 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja w sekcji tryskaczowej, której przewody rurowe za zaworem kontrolno-alarmowym wypełnione są gazem obojętnym, niedopuszczalne jest stosowanie tryskaczy o czułości:","options": {"a": "RTI < 50,","b": "50 ≤ RTI ≤ 80,","c": "80 ≤ RTI ≤ 200."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 209,"q": "W przypadku unieważnienia uzgodnienia projektu budowlanego obiektu budowlanego przez właściwego komendanta wojewódzkiego PSP, poprawiony projekt:","options": {"a": "powinien uzgodnić organ, który dokonał unieważnienia,","b": "powinien uzgodnić rzeczoznawca, który dokonał unieważnionego uzgodnienia,","c": "na wniosek inwestora, może uzgodnić organ, który dokonał unieważnienia."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 210,"q": "Budynek niski o dwóch kondygnacjach nadziemnych stanowiących jedną strefę pożarową i wysokości nieprzekraczającej 9 m, w którym na pierwszej (dolnej) kondygnacji przewidziano dwie sale konferencyjne zakwalifikowane do kategorii zagrożenia ludzi ZL I, natomiast na kondygnacji wyższej przewidziano część hotelową zakwalifikowaną do kategorii zagrożenia ludzi ZL V, można zaprojektować i wybudować w klasie odporności pożarowej nie mniejszej niż:","options": {"a": "B,","b": "C,","c": "D."},"category": "Ewakuacja"},{"id": 211,"q": "Klasą reakcji na ogień izolacji cieplnej zastosowanej na przewodach instalacji wodociągowej przeciwpożarowej jest:","options": {"a": "BL-s3, d0,","b": "BDL-s2, d0,","c": "CFL-s3, d0."},"category": "Reakcja na ogień i materiały"},{"id": 212,"q": "Stosowanie systemu sygnalizacji pożarowej jest wymagane w kinie o liczbie miejsc siedzących:","options": {"a": "300,","b": "500,","c": "700."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 213,"q": "W świetle aktualnego stanu prawnego, dla wyrobu budowlanego nieobjętego zakresem przedmiotowym Polskiej Normy wyrobu, w ramach krajowego procesu oceny właściwości użytkowych tego wyrobu, wydaje się:","options": {"a": "krajową ocenę techniczną,","b": "krajową aprobatę techniczną,","c": "krajowy certyfikat techniczny."},"category": "Pozostałe / ogólne"},{"id": 214,"q": "Pawilon stacji paliw:","options": {"a": "powinien być usytuowany poza strefą zagrożenia wybuchem,","b": "może być usytuowany w strefie zagrożenia wybuchem pod warunkiem wykonania go z elementów nierozprzestrzeniających ognia,","c": "może być usytuowany w strefie zagrożenia wybuchem pod warunkiem wykonania występujących w nim urządzeń elektrycznych w odpowiedniej klasie Ex."},"category": "Zagrożenie wybuchem"},{"id": 215,"q": "Wykonywanie robót budowlanych polegających na wyposażeniu istniejącego, niepodpiwniczonego niskiego budynku mieszkalnego w dźwig dla osób niepełnosprawnych, zlokalizowany w duszy trójbiegowej klatki schodowej, na podszybiu zaprojektowanym w konstrukcji żelbetowo – stalowej na poziomie parteru, w rozumieniu przepisów Prawa budowlanego, należy kwalifikować jako:","options": {"a": "remont,","b": "przebudowę,","c": "rozbudowę."},"category": "Pozostałe / ogólne"},{"id": 216,"q": "Obiektem, którego projekt budowlany nie wymaga uzgodnienia pod względem ochrony przeciwpożarowej jest:","options": {"a": "dwukondygnacyjny niski budynek administracyjno-biurowy, stanowiący jedną strefę pożarową, o powierzchni kondygnacji 750 m2,","b": "jednokondygnacyjny budynek hotelu, stanowiący jedną strefę pożarową, o powierzchni kondygnacji 750 m2, z 40 miejscami noclegowymi,","c": "czterokondygnacyjny budynek mieszkalny, w którym na pierwszej kondygnacji nadziemnej, wydzielono strefę pożarową (ZL III) na cele handlowo-usługowe, o powierzchni 1000 m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 217,"q": "Nierozprzestrzenianie ognia przez ocieplenie i okładziny zewnętrzne ścian zewnętrznych budynku powinno się określać zgodnie z:","options": {"a": "Polską Normą PN-B-02867 dotyczącą metody badania stopnia rozprzestrzeniania ognia przez ściany,","b": "Polską Normą PN-EN 13501-1 dotyczącą klasyfikacji ogniowej wyrobów budowlanych i elementów budynków,","c": "Polską Normą PN-EN 13501-7 dotyczącą klasyfikacji ogniowej wyrobów przeznaczonych do wykonywania izolacji elementów zewnętrznych wyrobów."},"category": "Odporność ogniowa i klasy budynków"},{"id": 218,"q": "W budynku użyteczności publicznej, w którym zastosowano wymagany przez przepisy przeciwpożarowe dźwiękowy system ostrzegawczy, stosowanie innych akustycznych pożarowych urządzeń alarmowych jest dopuszczalne tylko do zaalarmowania:","options": {"a": "użytkowników znajdujących się w strefach pożarowych obejmujących pomieszczenia handlowe,","b": "użytkowników pomieszczenia, w którym powstał pożar,","c": "służb dozoru lub ochrony."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 219,"q": "Minimalną odległość magazynu butli z gazem o masie do 1350 kg, zlokalizowanego na stacji paliw, od obiektów użyteczności publicznej, można zmniejszyć poprzez zastosowanie:","options": {"a": "ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 120, zasłaniającej zbiornik od strony obiektu,","b": "ściany oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 120, zasłaniającej obiekt od strony zbiornika,","c": "zmniejszenie ww. odległości jest niedopuszczalne."},"category": "Odporność ogniowa i klasy budynków"},{"id": 220,"q": "Natężenie wypływu wody z tryskaczy określa się na podstawie następujących parametrów:","options": {"a": "ciśnienia w zaworze kontrolno-alarmowym oraz współczynnika wypływu K,","b": "ciśnienia przed tryskaczem oraz współczynnika wypływu K,","c": "ciśnienia w sekcji tryskaczowej oraz wskaźnika RTI."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 221,"q": "Do zabezpieczenia pomieszczenia magazynowego o gęstości obciążenia ogniowego powyżej 1000 MJ/m2 i powierzchni 300 m2, zlokalizowanego w strefie pożarowej ZL III znajdującej się w budynku średniowysokim (SW), powinien być zastosowany:","options": {"a": "hydrant 52,","b": "hydrant 33 lub hydrant 52,","c": "hydrant 25."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 222,"q": "Zgodnie z postanowieniami rozporządzenia Ministra Edukacji Narodowej z dnia 28 sierpnia 2017 r. w sprawie rodzajów innych form wychowania przedszkolnego, warunków tworzenia i organizowania tych form oraz sposobu ich działania (Dz.U. poz. 1657, z późn.zm) wśród warunków dopuszczalności prowadzenia zajęć w ramach punktu przedszkolnego, w lokalu niespełniającym wymagań dla kategorii zagrożenia ludzi ZL II, znajdują się:","options": {"a": "zlokalizowanie lokalu na pierwszej kondygnacji nadziemnej budynku i użytkowanie go przez nie więcej niż 15 dzieci,","b": "zapewnienie co najmniej dwóch wyjść służących celom ewakuacji z lokalu i posiadanie przez elementy budowlane w strefie pożarowej (na pierwszej i drugiej kondygnacji nadziemnej), w której znajduje się lokal, cechy nierozprzestrzeniania ognia,","c": "użytkowanie go przez nie więcej niż 25 dzieci i wyposażenie w gaśnicę o masie środka gaśniczego co najmniej 6 kg."},"category": "Ewakuacja"},{"id": 223,"q": "Klatka schodowa w budynku niskim przeznaczonym na przedszkole, w przypadku w którym łączna długość jedynego dojścia ewakuacyjnego zmierzona poziomymi i pionowymi drogami ewakuacyjnymi wynosi 20 m, powinna być zamknięta drzwiami:","options": {"a": "dymoszczelnymi,","b": "o klasie odporności ogniowej co najmniej EI 30,","c": "o klasie odporności ogniowej co najmniej EI 30, będącymi jednocześnie drzwiami dymoszczelnymi."},"category": "Ewakuacja"},{"id": 224,"q": "Zgodnie z wymaganiami rozporządzenia Ministra Rolnictwa i Gospodarki Żywnościowej z dnia 7 października 1997 r. w sprawie warunków technicznych, jakim powinny odpowiadać budowle rolnicze i ich usytuowanie (Dz. U. z 2014 r. poz. 81), odległość zbiornika biogazu rolniczego od granicy sąsiedniej działki powinna wynosić co najmniej:","options": {"a": "2 m,","b": "5 m,","c": "20 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 225,"q": "Zgodnie z PN-B-02857:2017 Ochrona przeciwpożarowa – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne głębokość przeciwpożarowego zbiornika wodnego powinna być taka, aby w warunkach pracy z zasysaniem wody przez pompy pożarnicze odległość pionowa mierzona od poziomu stanowiska czerpania wody do najniższego użytecznego poziomu wody nie przekraczała:","options": {"a": "2 m,","b": "5 m,","c": "7 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 226,"q": "W budynku wielokondygnacyjnym wysokim, zakwalifikowanym do kategorii zagrożenia ludzi ZL III, chronionym stałymi samoczynnymi urządzeniami gaśniczymi mgłowymi, dopuszczalna powierzchnia strefy pożarowej:","options": {"a": "może być powiększona o 50%,","b": "może być powiększona o 100%,","c": "nie może być powiększona."},"category": "Odporność ogniowa i klasy budynków"},{"id": 227,"q": "W trakcie praktycznego sprawdzania warunków ewakuacji z obiektów, w których prowadzona jest działalność gospodarcza o charakterze rozrywkowym, polegająca na organizowaniu gier lub zabaw, w trakcie których ich uczestnicy uwalniają się z zamkniętej przestrzeni, wymagany jest udział:","options": {"a": "funkcjonariusza Państwowej Straży Pożarnej,","b": "rzeczoznawcy do spraw zabezpieczeń przeciwpożarowych lub osoby posiadającej tytuł zawodowy inżynier pożarnictwa, bądź osoby, która ukończyła studia w Szkole Głównej Służby Pożarniczej w zakresie inżynierii bezpieczeństwa w specjalności inżynieria bezpieczeństwa pożarowego,","c": "rzeczoznawcy do spraw zabezpieczeń przeciwpożarowych lub osoby, która ukończyła w Szkole Głównej Służby Pożarniczej szkolenie inspektora ochrony przeciwpożarowej."},"category": "Ewakuacja"},{"id": 228,"q": "Wyjście z klatki schodowej na strych w 12 kondygnacyjnym wielorodzinnym budynku mieszkalnym wymaga zamknięcia:","options": {"a": "drzwiami lub klapą wyjściową o klasie odporności ogniowej co najmniej EI 30,","b": "drzwiami lub klapą wyjściową o klasie odporności ogniowej co najmniej EI 60,","c": "przedsionkiem przeciwpożarowym."},"category": "Ewakuacja"},{"id": 229,"q": "Zgodnie z wymaganiami rozporządzenia Ministra Infrastruktury z dnia 16 stycznia 2002 r. w sprawie przepisów techniczno-budowlanych dotyczących autostrad płatnych (Dz.U. Nr 12, poz. 116, z późn. zm.), minimalna długość przejazdu awaryjnego przez pas dzielący jezdnie autostrady wynosi:","options": {"a": "75 m,","b": "150 m,","c": "250 m."},"category": "Drogi pożarowe i dojazd"},{"id": 230,"q": "Drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczenia:","options": {"a": "auli zlokalizowanej w budynku uczelni wyższej, ze 60 miejscami do siedzenia, przeznaczonej wyłącznie na potrzeby prowadzenia zajęć ze studentami, będącymi stałymi użytkownikami pomieszczenia,","b": "salki zlokalizowanej w domu opieki społecznej, przeznaczonej do prowadzenia zajęć rehabilitacyjnych z pensjonariuszami, przeznaczonej dla 6 osób,","c": "kuchni wyposażonej w 6 taboretów gazowych, obsługującej stołówkę w zakładzie pracy."},"category": "Ewakuacja"},{"id": 231,"q": "Zgodnie z postanowieniami rozporządzenia Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie (Dz.U. z 2014 r., poz.1853, z późn.zm), łączna dopuszczalna pojemność zbiorników magazynowych dla produktów naftowych w bazie paliw płynnych:","options": {"a": "nie powinna przekraczać 500 m3,","b": "nie powinna przekraczać 5000 m3,","c": "nie jest określana."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 232,"q": "Zgodnie z postanowieniami rozporządzenia Ministra Infrastruktury z dnia 17 czerwca 2011r. w sprawie warunków technicznych, jakim powinny odpowiadać obiekty budowlane metra i ich usytuowanie (Dz.U. Nr 144, poz. 859), wymaganą klasą odporności ogniowej dla zamknięć otworów w przegrodach budowlanych stanowiących wydzielenie przeciwpożarowe, jest klasa:","options": {"a": "EI 30,","b": "EI 60,","c": "EI 120."},"category": "Odporność ogniowa i klasy budynków"},{"id": 233,"q": "W przypadku zaprojektowania w budynku tymczasowym wykonanym z materiałów palnych wyłazu umożliwiającego dostęp do poddasza, zamykanego klapą wyjściową, wspomniana klapa powinna mieć wymiary wynoszące co najmniej:","options": {"a": "0,5 x 0,5 m,","b": "0,6 x 0,6 m,","c": "0,6 x 1,6 m."},"category": "Ewakuacja"},{"id": 234,"q": "Zastosowanie w jednokondygnacyjnym budynku produkcyjnym stałych samoczynnych urządzeń gaśniczych wodnych umożliwia przyjęcie klasy odporności pożarowej budynku:","options": {"a": "„E”,","b": "obniżonej o jedną w stosunku do wymaganej,","c": "„E”, pod warunkiem zastosowania elementów budynku nierozprzestrzeniających ognia."},"category": "Odporność ogniowa i klasy budynków"},{"id": 235,"q": "Zgodnie z PKN-CEN/TS 54-14:2006 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji przy rozmieszczaniu punktowych czujek dymu przegrody pionowe (ściany, przepierzenia lub regały) powinny być traktowane jako dochodzące do stropu, a tak powstałe części pomieszczenia – jak odrębne pomieszczenia, jeżeli przegrody te sięgają bliżej niż:","options": {"a": "0,3 m od stropu,","b": "0,5 m od stropu,","c": "odległość równa 5 % wysokości pomieszczenia."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 236,"q": "W jednokondygnacyjnym budynku magazynowym o gęstości obciążenia ogniowego powyżej 2000 MJ/m2, w którym zastosowano stałe urządzenia gaśnicze tryskaczowe i samoczynne urządzenia oddymiające, dopuszczalną powierzchnię strefy pożarowej:","options": {"a": "można powiększyć o 100%,","b": "można powiększyć o 150%,","c": "nie ogranicza się."},"category": "Odporność ogniowa i klasy budynków"},{"id": 237,"q": "Jeżeli w sali widowiskowej przeznaczonej do jednoczesnego przebywania ponad 200 osób fotele są trudno zapalne, to dodatkowo:","options": {"a": "nie mogą one wydzielać bardzo toksycznych produktów rozkładu i spalania,","b": "nie mogą one wydzielać bardzo toksycznych produktów rozkładu i spalania oraz być intensywnie dymiące,","c": "nie muszą one spełniać innych wymagań."},"category": "Pozostałe / ogólne"},{"id": 238,"q": "Długość przejścia od stanowiska postojowego do najbliższego wyjścia ewakuacyjnego w garażu podziemnym, wyposażonym w instalację wentylacji oddymiającej strumieniowej i stałe urządzenia tryskaczowe, nie może przekroczyć:","options": {"a": "40 m,","b": "60 m,","c": "80 m."},"category": "Ewakuacja"},{"id": 239,"q": "Przestrzenie zagrożone wybuchem dzieli sią na strefy, które klasyfikuje się na podstawie:","options": {"a": "prawdopodobieństwa i czasu występowania atmosfery wybuchowej,","b": "ryzyka zagrożenia wybuchem i czasu występowania atmosfery wybuchowej,","c": "stężenia mieszaniny wybuchowej i czasu jej występowania atmosferze wybuchowej."},"category": "Zagrożenie wybuchem"},{"id": 240,"q": "Zgodnie z PKN-CEN/TS 54-14:2006 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji maksymalny promień działania punktowej czujki dymu zainstalowanej w kalenicy dwupołaciowego stropodachu o nachyleniu 10° wynosi:","options": {"a": "5 m,","b": "7,5 m,","c": "8,25 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 241,"q": "Jednokondygnacyjny budynek magazynowy wysoki (W), w którym wszystkie strefy pożarowe są chronione przez stałe samoczynne urządzenia gaśnicze wodne (tryskaczowe), a gęstość obciążenia ogniowego w tych strefach jest większa niż 2000 MJ/m2 i nie większa niż 4000 MJ/m2, może być wykonany w klasie odporności pożarowej:","options": {"a": "co najmniej „B”,","b": "co najmniej „C”,","c": "co najmniej „E”."},"category": "Odporność ogniowa i klasy budynków"},{"id": 242,"q": "Ściany wewnętrzne stanowiące obudowę poziomej drogi ewakuacyjnej, do których przylegają mieszkania w budynku mieszkalnym wielorodzinnym czterokondygnacyjnym, powinny posiadać klasę odporności ogniowej co najmniej:","options": {"a": "EI 15,","b": "EI 30,","c": "EI 60."},"category": "Ewakuacja"},{"id": 243,"q": "Wentylatory służące do usuwania dymu i ciepła z tunelu drogowego powinny posiadać klasę F wynikającą z obliczeniowej temperatury dymu, przy czym klasa ta nie może być mniejsza niż:","options": {"a": "F400 120,","b": "F600 60,","c": "F600 120."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 244,"q": "Okładziny sufitów oraz sufity podwieszone w strefach pożarowych ZL I, ZL II, ZL III i ZL V należy wykonywać jako nieodpadające pod wpływem ognia z materiałów lub wyrobów budowlanych niekapiących klasy reakcji na ogień co najmniej (klasyfikacja podstawowa):","options": {"a": "A2,","b": "B,","c": "C."},"category": "Reakcja na ogień i materiały"},{"id": 245,"q": "Maksymalna dopuszczalna pojemność zbiorników magazynowych dla produktów naftowych w stacji kontenerowej wynosi:","options": {"a": "5 m3,","b": "30 m3,","c": "100 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 246,"q": "Piec na paliwo stałe może być stosowany w budynku zakwalifikowanym do kategorii zagrożenia ludzi ZL I:","options": {"a": "niskim,","b": "o wysokości do 3 kondygnacji nadziemnych włącznie,","c": "nie może być stosowany."},"category": "Odporność ogniowa i klasy budynków"},{"id": 247,"q": "Drogowe urządzenia przeciwhałasowe zainstalowane na obiektach mostowych, które są usytuowane w odległości mniejszej niż 8 m od budynków, powinny być wykonane z materiałów posiadających klasę reakcji na ogień co najmniej:","options": {"a": "A2, d0,","b": "B, d0,","c": "D."},"category": "Reakcja na ogień i materiały"},{"id": 248,"q": "Zgodnie ze specyfikacją techniczną PKN-CEN/TS 54-14:2006 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, przy rozmieszczeniu punktowych czujek dymu w pomieszczeniu o wysokości 5 m, szerokości 10 m i długości 20 m, ze stropem z wykształceniami podzielonym na pola o wymiarach 10 m × 1,8 m belkami o wysokości 24 cm, należy zastosować:","options": {"a": "czujkę w każdym polu,","b": "czujkę w co drugim polu,","c": "potraktować strop jak płaski i przyjąć promień działania czujki dymu 7,5 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 249,"q": "Klapy dymowe w grawitacyjnej wentylacji oddymiającej, otwierane automatycznie i ręcznie, powinny posiadać klasę co najmniej:","options": {"a": "B300 30,","b": "B400 30,","c": "B600 30."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 250,"q": "Średnie obciążenie ogniowe dla strefy pożarowej, w skład której wchodzą 3 pomieszczenia o gęstości obciążenia ogniowego odpowiednio: Q1=600 MJ/m2 (pomieszczenie o powierzchni 20 m2), Q2=1000 MJ/m2 (pomieszczenie o powierzchni 30 m2), Q3=2000 MJ/m2 (pomieszczenie o powierzchni 50 m2), wynosi:","options": {"a": "1200 MJ/m2,","b": "1310 MJ/m2,","c": "1420 MJ/m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 251,"q": "Maksymalna dopuszczalna długość przejścia ewakuacyjnego w garażu otwartym wyposażonym w stałe samoczynne urządzenia gaśnicze wodne wynosi:","options": {"a": "60 m,","b": "90 m,","c": "120 m."},"category": "Ewakuacja"},{"id": 252,"q": "Dopuszczalna długość przejścia ewakuacyjnego w pomieszczeniu zagrożonym wybuchem o wysokości 5 m, zlokalizowanym w budynku jednokondygnacyjnym, w strefie pożarowej PM o gęstości obciążenia ogniowego 2000 MJ/m2, wyposażonej w samoczynne urządzenia oddymiające uruchamiane za pomocą systemu wykrywania dymu, wynosi:","options": {"a": "40 m,","b": "60 m,","c": "70 m."},"category": "Ewakuacja"},{"id": 253,"q": "Instalacja systemu integracyjnego w obiektach budowlanych metrach powinna m.in. umożliwiać sterowanie automatyczne i ręczne urządzeniami przeciwpożarowymi, przy czym:","options": {"a": "priorytetowa powinna być możliwość sterowań automatycznych,","b": "priorytetowa powinna być możliwość sterowań ręcznych (przeznaczona do wykorzystania przez jednostki ratowniczo–gaśnicze i uprawniony personel),","c": "priorytety w zakresie sterowań (automatyczne czy ręczne) powinny wynikać wyłącznie z ustaleń dokonanych w trakcie opracowywania scenariusza rozwoju zdarzeń w czasie pożaru."},"category": "Pozostałe / ogólne"},{"id": 254,"q": "Pomieszczenie w budynku inwentarskim przeznaczone do bezściółkowego chowu 180 owiec powinno posiadać co najmniej:","options": {"a": "jedno wyjście ewakuacyjne,","b": "dwa wyjścia ewakuacyjne,","c": "trzy wyjścia ewakuacyjne."},"category": "Ewakuacja"},{"id": 255,"q": "W przypadku, gdy organem właściwym do wydania zezwolenia na zbieranie i przetwarzanie odpadów jest marszałek województwa, do wniosku o zezwolenie na zbieranie odpadów oraz do wniosku o zezwolenie na przetwarzanie odpadów należy dołączyć operat przeciwpożarowy, zawierający warunki ochrony przeciwpożarowej instalacji, obiektu lub jego części lub innego miejsca magazynowania odpadów, uzgodnione z komendantem powiatowym (miejskim) Państwowej Straży Pożarnej, wykonany przez:","options": {"a": "rzeczoznawcę do spraw zabezpieczeń przeciwpożarowych,","b": "inżyniera pożarnictwa lub rzeczoznawcę do spraw zabezpieczeń przeciwpożarowych,","c": "osobę, o której mowa w art. 4 ust. 2a ustawy z dnia 24 sierpnia 1991 r. o ochronie przeciwpożarowej lub rzeczoznawcę do spraw zabezpieczeń przeciwpożarowych."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 256,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 7 czerwca 2010 r. w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz.U. z 2010 r. Nr 109, poz. 719, z późn.zm.) materiałem niebezpiecznym pożarowo nie jest ciecz palna o temperaturze zapłonu:","options": {"a": "268,75 K,","b": "308,15 K,","c": "384,15 K."},"category": "Pozostałe / ogólne"},{"id": 257,"q": "W budynku biurowym o wysokości 165 m, do zabezpieczenia przed zadymieniem dwóch występujących w nim klatek schodowych zastosowano system różnicowania ciśnień wg Polskiej Normy PN-EN-12101-6:2007 Wymagania techniczne dotyczące systemów różnicowania ciśnień. Zestawy urządzeń. Jeżeli do tych klatek schodowych jest zapewniona możliwość ewakuacji ludzi z każdego miejsca na poszczególnych kondygnacjach, to wentylatory rezerwowe i mechanizmy napędowe (wyposażenie rezerwowe) w tych systemach różnicowania ciśnień:","options": {"a": "nie muszą być stosowane,","b": "powinny być zastosowane w co najmniej jednej klatce schodowej,","c": "powinny być zastosowane w obu klatkach schodowych."},"category": "Ewakuacja"},{"id": 258,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz. U. poz. 296) strefa pożarowa z odpadami stałymi o gęstości obciążenia ogniowego 1500 MJ/m2 i powierzchni 3000 m2, znajdująca się w jednokondygnacyjnym budynku, wykonanym w klasie odporności pożarowej „C”, wymaga wyposażenia w:","options": {"a": "samoczynne urządzenia oddymiające, system sygnalizacji pożarowej, stałe urządzenia gaśnicze wodne lub pianowe,","b": "samoczynne urządzenia oddymiające, system sygnalizacji pożarowej, bez konieczności wyposażenia w stałe urządzenia gaśnicze wodne lub pianowe,","c": "samoczynne urządzenia oddymiające, bez konieczności wyposażenia w system sygnalizacji pożarowej oraz stałe urządzenia gaśnicze wodne lub pianowe."},"category": "Odporność ogniowa i klasy budynków"},{"id": 259,"q": "Minimalna dopuszczalna odległość budynku ZL, ze ścianami rozprzestrzeniającymi ogień i dachem nierozprzestrzeniającym ognia od budynku PM o gęstości obciążenia ogniowego 4000 MJ/m2, z pomieszczeniem zagrożonym wybuchem, wyposażonego w stałe samoczynne urządzenia gaśnicze wodne inne niż tryskaczowe, którego ściany zewnętrzne i dach są nierozprzestrzeniające ognia, w przypadku gdy ściany zewnętrzne obu budynków posiadają na powierzchni 70 % wymaganą dla nich klasę odporności ogniowej (E), wynosi:","options": {"a": "22,5 m,","b": "20 m,","c": "16,875 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 260,"q": "Zgodnie z Polską Normą PN-B-02857:2017-04 Ochrona przeciwpożarowa – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne, przewody łączące ze sobą grupę pojemników stanowiących przeciwpożarowy zbiornik wodny powinny posiadać średnicę:","options": {"a": "co najmniej 250 mm,","b": "co najmniej 300 mm,","c": "co najmniej 500 mm."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 261,"q": "Do ochrony pomieszczenia o wysokości 4 m, szerokości 20 m i długości 30 m należy zastosować, zgodnie ze specyfikacją techniczną PKN-CEN/TS 54-14:2006 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, co najmniej:","options": {"a": "8 punktowych czujek dymu,","b": "6 punktowych czujek dymu,","c": "4 punktowe czujki dymu."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 262,"q": "Zastosowanie samoczynnego urządzenia oddymiającego uruchamianego za pomocą systemu wykrywania dymu w wielokondygnacyjnym budynku wysokim (W) zakwalifikowanym w całości do kategorii zagrożenia ludzi ZL I:","options": {"a": "umożliwia powiększenie dopuszczalnej powierzchni strefy pożarowej o maksymalnie 50%,","b": "umożliwia powiększenie dopuszczalnej powierzchni strefy pożarowej o maksymalnie 100%,","c": "nie umożliwia powiększenia dopuszczalnej powierzchni strefy pożarowej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 263,"q": "Zgodnie z Polską Normą PN-EN 12845 Stałe urządzenia gaśnicze. Automatyczne urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja wymagające ochrony urządzeniem tryskaczowym przestrzenie ukryte przy dachu (nad sufitem podwieszonym) znajdujące się w budynku zakwalifikowanym do klasy zagrożenia pożarowego OH2, kwalifikuje się do klasy zagrożenia pożarowego:","options": {"a": "LH","b": "OH1,","c": "OH2."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 264,"q": "Zgodnie z Polską Normą PN-EN 12845 Stałe urządzenia gaśnicze. Automatyczne urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja przyspieszacz stosowany w powietrznej sekcji tryskaczowej służy do skrócenia:","options": {"a": "czasu zadziałania zaworu kontrolno-alarmowego i turbinowego urządzenia alarmowego,","b": "czasu do otwarcia tryskaczy i otwarcia zaworu kontrolno-alarmowego,","c": "czasu zadziałania zintegrowanego zaworu przyspieszającego w automatycznym urządzeniu pompowym."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 265,"q": "Przy obiektach tymczasowych o konstrukcji palnej musi być zachowany pas ochronny o nawierzchni z materiałów niepalnych lub gruntowej oczyszczonej, którego szerokość nie może być mniejsza niż:","options": {"a": "2 m,","b": "5 m,","c": "8 m."},"category": "Reakcja na ogień i materiały"},{"id": 266,"q": "W strefie pożarowej PM o gęstości obciążenia ogniowego do 500 MJ/m2, usytuowanej na ostatniej kondygnacji 3-kondygnacyjnego budynku magazynowego, wyposażonej w stałe samoczynne urządzenie gaśnicze tryskaczowe i klapy dymowe otwierające się samoczynnie pod wpływem ciepła, maksymalna dopuszczalna długość przejścia ewakuacyjnego w pomieszczeniach o wysokości do 5 m, wynosi:","options": {"a": "150 m,","b": "200 m,","c": "225 m."},"category": "Ewakuacja"},{"id": 267,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz. U. poz. 296.) magazyn ciekłych odpadów palnych o powierzchni 300 m2 wyposaża się w:","options": {"a": "stałe lub półstałe urządzenia gaśnicze pianowe, lub zapewnia co najmniej jedno okno lub inny otwór w ścianie zewnętrznej, umożliwiające skuteczne podanie piany gaśniczej,","b": "stałe lub półstałe urządzenia gaśnicze pianowe,","c": "stałe urządzenia gaśnicze pianowe, a półstałe są niedopuszczalne."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 268,"q": "W pomieszczeniu archiwum, w którym z przeznaczenia i sposobu zagospodarowania nie wynika jednoznacznie maksymalna liczba jego użytkowników, liczbę tę należy przyjmować w odniesieniu do jego powierzchni, według współczynnika:","options": {"a": "5 m2/osobę,","b": "7 m2/osobę,","c": "30 m2/osobę."},"category": "Pozostałe / ogólne"},{"id": 269,"q": "W budynku, którego kąt nachylenia dachu wynosi 13º maksymalna odległość między klapami dymowymi a krawędzią budynku, zgodnie z Polską Normą PN-B-02877-4:2001 Ochrona przeciwpożarowa budynków – Instalacje grawitacyjne do odprowadzania dymu i ciepła  Zasady projektowania, nie może przekraczać:","options": {"a": "10m,","b": "15 m,","c": "20 m."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 270,"q": "Zgodnie z Polską Normą PN-HD 60364-5-56:2010 Instalacje elektryczne niskiego napięcia – Część 5-56: Dobór i montaż wyposażenia elektrycznego – Instalacje bezpieczeństwa stosowanie ognioodpornych obwodów elektrycznych instalacji bezpieczeństwa jest wymagane, w przypadku gdy są one prowadzone przez pomieszczenia narażone na ryzyko pożarowe:","options": {"a": "BE2,","b": "CB2,","c": "BD2."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 271,"q": "Zgodnie z Polską Normą PN-EN 1838:2005 Zastosowania oświetlenia – Oświetlenie awaryjne natężenie oświetlenia awaryjnego w strefie wysokiego ryzyka nie powinno być mniejsze niż:","options": {"a": "5 lx,","b": "10 lx,","c": "10% eksploatacyjnego natężenia oświetlania wymaganego dla danych czynności i jednocześnie nie mniejsze niż 15 lx."},"category": "Pozostałe / ogólne"},{"id": 272,"q": "Zgodnie z Polską Normą PN-EN 1838:2005 Zastosowania oświetlenia – Oświetlenie awaryjne, maksymalna odległość, przy jakiej znak jest jeszcze czytelny (odległość widzenia), dla oświetlonego wewnętrznie znaku ewakuacyjnego o wysokości 15 cm wynosi:","options": {"a": "15 m,","b": "20 m,","c": "30 m."},"category": "Ewakuacja"},{"id": 273,"q": "Zgodnie z załącznikiem do rozporządzenia Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie (Dz. U. z 2014 r. poz. 1853 z późn. zm.) dla odmierzacza paliw na stacji paliw płynnych wykorzystywanego do dystrybucji produktów naftowych I klasy ustala się następujące strefy zagrożenia wybuchem:","options": {"a": "wyłącznie strefę 2,","b": "strefę 1 oraz strefę 2,","c": "strefę 0, strefę 1 oraz strefę 2."},"category": "Zagrożenie wybuchem"},{"id": 274,"q": "W teatrze z widownią o liczbie miejsc 500 osób i sceną teatralną o powierzchni wewnętrznej 140 m2 i kubaturze brutto 1500 m3 wymagane jest zastosowanie:","options": {"a": "systemu sygnalizacji pożarowej oraz kurtyny przeciwpożarowej,","b": "systemu sygnalizacji pożarowej oraz dźwiękowego systemu ostrzegawczego,","c": "systemu sygnalizacji pożarowej, a zastosowanie kurtyn przeciwpożarowych oraz dźwiękowego systemu ostrzegawczego nie jest wymagane."},"category": "Ewakuacja"},{"id": 275,"q": "Zgodnie z rozporządzeniem Ministra Gospodarki z dnia 26 kwietnia 2013 r. w sprawie warunków technicznych, jakim powinny odpowiadać sieci gazowe i ich usytuowanie (Dz. U. poz. 640) układ sterowania tłocznią gazu powinien posiadać system sygnalizacji pożarowej obejmujący ochroną:","options": {"a": "wyłącznie pomieszczenia, w których znajdują się sprężarki gazu ziemnego, przy czym nie jest wymagane połączenie tego systemu z komendą Państwowej Straży Pożarnej lub innym obiektem wskazanym przez właściwego miejscowo komendanta powiatowego Państwowej Straży Pożarnej,","b": "wszystkie budynki na terenie tłoczni, przy czym nie jest wymagane połączenie tego systemu z komendą Państwowej Straży Pożarnej lub innym obiektem wskazanym przez właściwego miejscowo komendanta powiatowego Państwowej Straży Pożarnej,","c": "wszystkie budynki na terenie tłoczni, połączony z komendą Państwowej Straży Pożarnej lub innym obiektem wskazanym przez właściwego miejscowo komendanta powiatowego Państwowej Straży Pożarnej."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 276,"q": "W nieogrzewanych budynkach lub w ich częściach przewody zasilające instalacji wodociągowej przeciwpożarowej należy zabezpieczyć przed możliwością zamarznięcia i w tym przypadku można stosować instalację suchą, pod warunkiem zastosowania rozwiązań umożliwiających jej nawadnianie w sposób:","options": {"a": "ręczny i/lub automatyczny,","b": "wyłącznie automatyczny,","c": "zawsze ręczny i automatyczny."},"category": "Pozostałe / ogólne"},{"id": 277,"q": "Zgodnie z rozporządzeniem Ministra Edukacji Narodowej z dnia 25 sierpnia 2017 r. w sprawie wymagań ochrony przeciwpożarowej, jakie musi spełniać lokal, w którym są prowadzone oddział przedszkolny lub oddziały przedszkolne zorganizowane w szkole podstawowej albo jest prowadzone przedszkole utworzone w wyniku przekształcenia oddziału przedszkolnego lub oddziałów przedszkolnych zorganizowanych w szkole podstawowej (Dz. U. z 2020 r. poz. 1531) pomieszczenie stołówki znajdujące się poza lokalem przedszkola utworzonego w wyniku przekształcenia oddziału przedszkolnego zorganizowanego w szkole podstawowej, z którego mają korzystać dzieci uczęszczające do tego przedszkola:","options": {"a": "musi znajdować się na pierwszej kondygnacji nadziemnej,","b": "może znajdować się na kondygnacji innej niż pierwsza nadziemna,","c": "musi znajdować się na tej kondygnacji nadziemnej, na której znajduje się ten lokal."},"category": "Odporność ogniowa i klasy budynków"},{"id": 278,"q": "Odległości stanowisk postojowych dla pojazdów samochodowych i samojezdnych maszyn rolniczych od instalacji służących do otrzymywania biogazu rolniczego powinny wynosić co najmniej:","options": {"a": "8 m,","b": "10 m,","c": "15 m."},"category": "Garaże i parkingi"},{"id": 279,"q": "Do parametrów gazów palnych stosowanych w temperaturze 20 oC i przy ciśnieniu atmosferycznym, które należy wziąć pod uwagę przy ocenie stwarzanego przez te gazy zagrożenia wybuchowego i możliwości zainicjowania spalania tworzonej przez nie atmosfery wybuchowej, zalicza się:","options": {"a": "temperaturę zapłonu, a temperatury samozapłonu nie rozpatruje się,","b": "temperaturę samozapłonu, a temperatury zapłonu nie rozpatruje się,","c": "zarówno temperaturę zapłonu, jak i temperaturę samozapłonu."},"category": "Zagrożenie wybuchem"},{"id": 280,"q": "Na terenie działki znajdującej się poza obrębem miasta, na której jest usytuowany budynek zawierający strefę pożarową magazynową o gęstość obciążenia ogniowego 700 MJ/m2 i powierzchni 1400 m2, droga pożarowa powinna umożliwiać przejazd pojazdów o nacisku osi na nawierzchnię jezdni co najmniej:","options": {"a": "50 kN (kiloniutonów),","b": "100 kN (kiloniutonów),","c": "odpowiedzi a) oraz b) są nieprawdziwe, ponieważ doprowadzenie drogi pożarowej do tego budynku nie jest wymagane."},"category": "Strefy pożarowe i oddzielenia"},{"id": 281,"q": "W sali konferencyjnej przeznaczonej do jednoczesnego przebywania ponad 200 osób, maksymalna liczba siedzeń w rzędzie przyściennym przy odstępie pomiędzy stałymi elementami siedzeń 0,55 m wynosi:","options": {"a": "8,","b": "16,","c": "18."},"category": "Ewakuacja"},{"id": 282,"q": "Zgodnie z wymaganiami przepisów rozporządzenia Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2019 r. poz. 1065, z późn. zm.) minimalna szerokość użytkowa schodów zewnętrznych służących do ewakuacji z garażu usytuowanego na kondygnacji podziemnej powinna wynosić co najmniej:","options": {"a": "0,8 m,","b": "0,9 m,","c": "1,2 m."},"category": "Ewakuacja"},{"id": 283,"q": "Zgodnie z wymaganiami przepisów rozporządzenia Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2019 r. poz. 1065, z późn. zm.) biegi i spoczniki schodów ewakuacyjnych w budynku wysokim zlokalizowane w klatce schodowej oddzielonej na każdej kondygnacji przedsionkami przeciwpożarowymi, powinny być co najmniej:","options": {"a": "wykonane z materiałów niepalnych,","b": "wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej R 30,","c": "wykonane z materiałów niepalnych i mieć klasę odporności ogniowej co najmniej R 60."},"category": "Ewakuacja"},{"id": 284,"q": "Zgodnie z wymaganiami przepisów rozporządzenia Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2019 r. poz. 1065, z późn. zm.), odległość zbiornika z gazem płynnym zasilającego kotłownię w budynku od rzutu poziomego skrajnego przewodu elektroenergetycznej linii napowietrznej o napięciu 0,4 kV, powinna wynosić co najmniej:","options": {"a": "3 m,","b": "5 m,","c": "15 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 285,"q": "Zgodnie z wymaganiami przepisów rozporządzenia Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2019 r. poz. 1065, z późn. zm.) w projektowanym budynku wysokim użyteczności publicznej o wysokości nie większej niż 35 m zastosowanie instalacji gazowej:","options": {"a": "jest niedopuszczalne,","b": "jest dopuszczalne tylko w przypadku uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej,","c": "może być wykonane tylko do pomieszczeń technicznych, w których są zainstalowane urządzenia gazowe."},"category": "Odporność ogniowa i klasy budynków"},{"id": 286,"q": "W budynku hotelowym o wysokości 15 m drzwi z pomieszczenia przechowywania sprzętu do utrzymania czystości prowadzące na drogę ewakuacyjną, powinny:","options": {"a": "mieć klasę odporności ogniowej EI 30,","b": "mieć klasę odporności ogniowej EI 30 Sa,","c": "nie stawia się wymagań w zakresie klasy odporności ogniowej."},"category": "Ewakuacja"},{"id": 287,"q": "Dopuszczalna maksymalna powierzchnia strefy pożarowej PM o gęstości obciążenia ogniowego 2000 MJ/m2 bez pomieszczeń zagrożonych wybuchem, usytuowanej na kondygnacji podziemnej w wielokondygnacyjnym wysokim (W) budynku użyteczności publicznej, wyposażonym w stałe samoczynne urządzenie gaśnicze wodne, wynosi:","options": {"a": "500 m2,","b": "1000 m2,","c": "nie dopuszcza takich stref pożarowych w tym budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 288,"q": "W pomieszczeniu o wysokości w świetle 5,8 m zlokalizowanym w strefie pożarowej zakwalifikowanej do kategorii zagrożenia ludzi ZL III, chronionym przez stałe samoczynne urządzenie gaśnicze ze środkiem gaśniczym IG-100, maksymalna dopuszczalna długość przejścia ewakuacyjnego wynosi:","options": {"a": "40 m,","b": "50 m,","c": "60 m."},"category": "Ewakuacja"},{"id": 289,"q": "Przy spełnionym wymaganiu nierozprzestrzeniania ognia (NRO) przez ściany zewnętrzne i dachy sąsiadujących budynków, ściana zewnętrzna projektowanego budynku biurowego średniowysokiego (SW) o 4 kondygnacjach nadziemnych, posiadająca na 75% jej powierzchni klasę odporności ogniowej E 30, powinna być usytuowana od równoległej do niej ściany sąsiedniego budynku ZL, niebędącej ścianą oddzielenia przeciwpożarowego, w odległości nie mniejszej niż:","options": {"a": "8 m,","b": "12,5 m,","c": "16 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 290,"q": "W budynku magazynowym o 5 kondygnacjach nadziemnych i wysokości 28 m, w którego strefie pożarowej gęstość obciążenia ogniowego wynosi 1000 MJ/m2 występuje pomieszczenie magazynowe do składowania gazów palnych, powierzchnia tej strefy nie może przekroczyć dopuszczalnej maksymalnie powierzchni:","options": {"a": "500 m2,","b": "1000 m2,","c": "nie dopuszcza się takiego przypadku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 291,"q": "W niskim (N) budynku ZL II o dwóch kondygnacjach nadziemnych zastosowanie w ścianach zewnętrznych izolacji cieplnej palnej jest dopuszczalne, gdy osłaniająca ją od wewnątrz okładzina posiada:","options": {"a": "klasę reakcji na ogień co najmniej A2-s3, d0 i klasę odporności ogniowej co najmniej EI 30,","b": "klasę reakcji na ogień co najmniej B-s2, d0 i klasę odporności ogniowej co najmniej EI 60,","c": "klasę reakcji na ogień co najmniej A2-s2, d0 i klasę odporności ogniowej co najmniej EI 60."},"category": "Odporność ogniowa i klasy budynków"},{"id": 292,"q": "W niskim (N) budynku biurowym o 4 kondygnacjach nadziemnych, zaprojektowanym w klasie odporności pożarowej „D” ze względu na wyposażenie go w stałe urządzenia gaśnicze wodne, przepusty instalacyjne w ścianach oddzielenia przeciwpożarowego powinny posiadać klasę odporności ogniowej co najmniej:","options": {"a": "EI 60,","b": "EI 120,","c": "EI 60 tylko dla przepustów o średnicy ponad 4 cm."},"category": "Odporność ogniowa i klasy budynków"},{"id": 293,"q": "W budynku mieszkalnym wielorodzinnym o 30 kondygnacjach nadziemnych, w którym drogi ewakuacyjne chronione są przez stałe samoczynne urządzenia gaśnicze wodne, dopuszczalna długość dojścia ewakuacyjnego na poziomym odcinku drogi ewakuacyjnej, przy zapewnionym tylko jednym dojściu, wynosi:","options": {"a": "20 m,","b": "30 m,","c": "40 m."},"category": "Ewakuacja"},{"id": 294,"q": "Zgodnie z rozporządzeniem Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U z 2019 r. poz. 1065, z późn. zm.), w niskim (N) budynku użyteczności publicznej (ZL III) o 2 kondygnacjach nadziemnych, w którym każda kondygnacja stanowi odrębną strefę pożarową, klatki schodowe powinny być:","options": {"a": "obudowane ścianami wewnętrznymi o klasie odporności ogniowej co najmniej REI 60, zamykane drzwiami o klasie odporności ogniowej co najmniej EI 30 i wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu,","b": "obudowane ścianami wewnętrznymi o klasie odporności ogniowej co najmniej REI 30, zamykane drzwiami o klasie odporności ogniowej co najmniej EI 30 i wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu,","c": "obudowane ścianami o klasie odporności ogniowej co najmniej REI 60 i zamykane drzwiami dymoszczelnymi klasy Sa i wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu."},"category": "Ewakuacja"},{"id": 295,"q": "Maksymalna długość drugiego, dłuższego dojścia prowadzącego z sali chorych do drzwi innej strefy pożarowej w budynku szpitalnym chronionym całkowicie stałym urządzeniem gaśniczym tryskaczowym wynosi:","options": {"a": "60 m,","b": "80 m,","c": "120 m."},"category": "Ewakuacja"},{"id": 296,"q": "W garażu podziemnym o powierzchni 1500 m2, przeznaczonym na 50 stanowisk parkingowych oraz wyposażonym w kanałową instalację oddymiającą należy zastosować co najmniej:","options": {"a": "2 wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd,","b": "2 wyjścia ewakuacyjne oddalone od siebie minimum 5 m z drzwiami otwierającymi się na zewnątrz pomieszczenia,","c": "1 wyjście ewakuacyjne."},"category": "Ewakuacja"},{"id": 297,"q": "Zgodnie z rozporządzeniem Ministra Transportu i Gospodarki Morskiej z dnia 30 maja 2000 r. w sprawie warunków technicznych, jakim powinny odpowiadać drogowe obiekty inżynierskie i ich usytuowanie (Dz.U. Nr 63, poz. 735 z późn. zm.) tunel o długości 1000 m powinien być wyposażony w hydranty zewnętrzne nadziemne o średnicy nominalnej DN 80, usytuowane w pobliżu wjazdów do tunelu i w tunelu w odległościach nie przekraczających:","options": {"a": "75 m,","b": "150 m,","c": "250 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 298,"q": "Zlokalizowane na stacji paliw zbiorniki gazu płynnego, przykryte warstwą ziemi o grubości 0,5 m, powinny być usytuowane od budynków produkcyjnych i magazynowych, w odległości nie mniejszej niż:","options": {"a": "10 m,","b": "15 m,","c": "20 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 299,"q": "Stacja kontenerowa służąca do zaopatrywania jednostek pływających żeglugi śródlądowej w produkty naftowe I klasy może posiadać zbiorniki magazynowe o pojemności nie większej niż:","options": {"a": "5 m3,","b": "30 m3,","c": "50 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 300,"q": "Instalacja do otrzymywania biogazu rolniczego o pojemności 500 m3 powinna mieć ustaloną wokół siebie strefę bezpieczeństwa, mierzoną od zewnętrznych krawędzi skrajnych budowli i urządzeń budowlanych wchodzących w skład instalacji, wynoszącą co najmniej:","options": {"a": "3 m,","b": "5 m,","c": "8 m."},"category": "Pozostałe / ogólne"},{"id": 301,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz.U. z 2020r. poz. 296), w sekcji magazynowej stosy lub pryzmy z całymi lub rozdrobnionymi oponami oddziela się między sobą pasami wolnej przestrzeni lub terenu o szerokości co najmniej:","options": {"a": "2 m,","b": "3 m,","c": "5 m."},"category": "Pozostałe / ogólne"},{"id": 302,"q": "Maksymalne ciśnienie hydrostatyczne w sieci wodociągowej przeciwpożarowej nie może przekraczać:","options": {"a": "0,7 MPa,","b": "1,2 MPa,","c": "1,6 MPa."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 303,"q": "Na magistralnym przewodzie sieci wodociągowej przeciwpożarowej należy stosować hydranty zewnętrzne o średnicy nominalnej:","options": {"a": "DN 80,","b": "DN 100,","c": "DN 150."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 304,"q": "Dla strefy pożarowej produkcyjno-magazynowej (jednoprzestrzennej) o powierzchni 3000 m2 i gęstości obciążenia ogniowego 800 MJ/m2, znajdującej się w budynku średniowysokim (SW), należy zapewnić zaopatrzenie w wodę do wewnętrznego gaszenia pożaru z instalacji wodociągowej przeciwpożarowej w ilości co najmniej (wskazać wartość najmniejszą, jaka może być przyjęta zgodnie z obowiązującymi przepisami):","options": {"a": "10 dm3/s,","b": "5 dm3/s,","c": "3 dm3/s."},"category": "Strefy pożarowe i oddzielenia"},{"id": 305,"q": "Dla znajdującego się w zakładzie przemysłu spożywczego zbiornika magazynowego cieczy palnej o temperaturze zapłonu powyżej 373,15 K (100 °C), który posiada pojemność 2500 m3, jest zlokalizowany poza budynkiem i zajmuje powierzchnię 600 m2, wymagana ilość wody do zewnętrznego gaszenia pożaru wynosi co najmniej:","options": {"a": "10 dm3/s,","b": "20 dm3/s,","c": "30 dm3/s."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 306,"q": "Szerokość jezdni drogi pożarowej w przejeździe prowadzącym na dziedziniec wewnętrzny, która jest oddzielona od chodników słupkami, powinna być nie mniejsza niż:","options": {"a": "3 m,","b": "3,6 m,","c": "4 m."},"category": "Drogi pożarowe i dojazd"},{"id": 307,"q": "Wymagany zapas wody w zbiorniku przeznaczonym do zasilania instalacji wodociągowej przeciwpożarowej w wysokościowym (WW) budynku użyteczności publicznej o wysokości do 100 m i powierzchni wewnętrznej kondygnacji do 2000 m2, można w przypadku zapewnienia zasilania tego zbiornika w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s, zmniejszyć do:","options": {"a": "6 m3,","b": "25 m3,","c": "50 m3."},"category": "Odporność ogniowa i klasy budynków"},{"id": 308,"q": "Zgodnie z Polską Normą PN-HD 60364-5-56:2019-01 Instalacje elektryczne niskiego napięcia − Część 5-56: Dobór i montaż wyposażenia elektrycznego − Instalacje bezpieczeństwa obwody instalacji bezpieczeństwa, z uwagi na możliwe do wystąpienia w podwyższonych temperaturach w warunkach pożaru prądy upływu między przewodami:","options": {"a": "należy zabezpieczać urządzeniami ochronnymi różnicowoprądowymi (RCDs),","b": "nie należy zabezpieczać urządzeniami do detekcji zwarć łukowych (AFDDs),","c": "nie powinny być zabezpieczane urządzeniami ochronnymi różnicowoprądowymi (RCDs), ale dopuszcza się zabezpieczanie przez urządzenia do detekcji zwarć łukowych (AFDDs)."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 309,"q": "Zgodnie z Polską Normą PN-B-02857:2017-04 Ochrona przeciwpożarowa budynków - Przeciwpożarowe zbiorniki wodne - Wymagania ogólne przeciwpożarowy zbiornik wodny naziemny o pojemności 250 m3, zapewniający warunki ssania do pracy z napływem, powinien być uzbrojony w co najmniej:","options": {"a": "jeden przewód ssawny,","b": "dwa przewody ssawne,","c": "trzy przewody ssawne."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 310,"q": "Zgodnie z PKN-CEN/TS 54-14:2020-09 Systemy sygnalizacji pożarowej - Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, punktowe czujki ciepła klasy A1 mogą być stosowane bez dodatkowych warunków w pomieszczeniach o maksymalnej wysokości:","options": {"a": "7,5 m,","b": "9 m,","c": "11 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 311,"q": "W systemach sygnalizacji pożarowej sygnalizator optyczny Typu B, o którym mowa w Polskiej Normie PN-EN 54-23 Systemy sygnalizacji pożarowej. Cześć 23: Pożarowe urządzenia alarmowe. Sygnalizatory optyczne, to:","options": {"a": "urządzenie przeznaczone wyłącznie do zastosowań wewnętrznych,","b": "urządzenie przeznaczone głównie do zastosowań wewnętrznych,","c": "urządzenie przeznaczone głównie do zastosowań zewnętrznych."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 312,"q": "Zgodnie z PN-EN 12845+A1:2020-05 Stałe urządzenia gaśnicze. Automatyczne urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja sekcje tryskaczowe powietrzne:","options": {"a": "powinny być instalowane tylko tam, gdzie możliwe są uszkodzenia spowodowane mrozem i tam, gdzie temperatura otoczenia przekracza 70 °C,","b": "powinny być instalowane tylko tam, gdzie możliwe są uszkodzenia spowodowane mrozem,","c": "mogą być instalowane w każdej temperaturze występującej w chronionej przestrzeni, a powinny być instalowane tam, gdzie możliwe są uszkodzenia spowodowane mrozem."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 313,"q": "Zgodnie z PN-EN 12845 Stałe urządzenia gaśnicze. Automatyczne urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja klasa zagrożenia pożarowego wpływa na wartość:","options": {"a": "projektowej intensywności zraszania oraz powierzchni działania,","b": "projektowej intensywności zraszania, natomiast nie ma wpływu na wartość powierzchni działania,","c": "powierzchni działania, natomiast nie ma wpływu na wartość projektowej intensywności zraszania."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 314,"q": "Zgodnie z PN-EN 12845+A1:2020-05 Stałe urządzenia gaśnicze. Automatyczne urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja tryskacze nie powinny być instalowane niżej od palnych stropów niż:","options": {"a": "0,3 m,","b": "0,45 m,","c": "tryskacze nie mogą być instalowane bezpośrednio pod palnymi stropami."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 315,"q": "Gaz gaśniczy FK-5-1-12 to:","options": {"a": "obojętny gaz gaśniczy,","b": "gaz gaśniczy będący chlorowcopochodną węglowodorów (zamiennikiem halonów),","c": "nie jest ani obojętnym gazem gaśniczym, ani gazem gaśniczym będącym chlorowcopochodną węglowodorów (zamiennikiem halonów)."},"category": "Pozostałe / ogólne"},{"id": 316,"q": "Polska Norma PN-EN 12101-6:2007 Systemy kontroli rozprzestrzeniania dymu i ciepła. Część 6: Wymagania techniczne dotyczące systemów różnicowania ciśnień. Zestawy urządzeń przewiduje, że w przypadku braku informacji o sile wymaganej do pokonania samozamykacza drzwi we wczesnej fazie projektowania systemu, dla celów projektowych można stosować wartość maksymalnej różnicy ciśnień:","options": {"a": "50 Pa,","b": "60 Pa,","c": "70 Pa."},"category": "Odporność ogniowa i klasy budynków"},{"id": 317,"q": "Zgodnie z Polską Normą PN-EN 12101-6:2007 Systemy kontroli rozprzestrzeniania dymu i ciepła. Część 6: Wymagania techniczne dotyczące systemów różnicowania ciśnień. Zestawy urządzeń różnica ciśnień między „bezpiecznym pomieszczeniem dla ewakuowanych” a pomieszczeniem użytkowym powinna być nie mniejsza niż:","options": {"a": "50 Pa,","b": "80 Pa,","c": "Polska Norma PN-EN 12101-6:2007 nie określa wymagań w tym zakresie."},"category": "Odporność ogniowa i klasy budynków"},{"id": 318,"q": "Jeżeli zastosowano w budynku ręczny łącznik jazdy pożarowej, to zgodnie z Polską Normą PN-EN 81-73:2020-12 Zasady bezpieczeństwa dotyczące budowy i instalowania dźwigów. Szczególne zastosowania dźwigów osobowych i dźwigów towarowo-osobowych. Część 73: Funkcjonowanie dźwigów w przypadku pożaru powinien być on zlokalizowany:","options": {"a": "w centrum zarządzania budynkiem lub na głównym wyznaczonym przystanku,","b": "na pierwszej kondygnacji nadziemnej przy drzwiach przystankowych dźwigu,","c": "przy głównym wejściu do budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 319,"q": "Zgodnie z Polską Normą PN-EN-1838:2013 Zastosowania oświetlenia. Oświetlenie awaryjne, oświetlenie awaryjne na drodze ewakuacyjnej powinno zapewniać poziom pełnego wymaganego natężenia oświetlenia (100%) w czasie nie dłuższym niż:","options": {"a": "0,5 s,","b": "5 s,","c": "60 s."},"category": "Ewakuacja"},{"id": 320,"q": "Do ręcznego uruchamiania grawitacyjnej instalacji oddymiającej zaprojektowanej wg Polskiej Normy PN-B-02877-4:2001 Ochrona przeciwpożarowa budynków. Instalacje grawitacyjne do odprowadzania dymu i ciepła, przeznaczonej do usuwania dymu z klatki schodowej w 8 kondygnacyjnym budynku mieszkalnym, jest wymagane zastosowanie, co najmniej:","options": {"a": "3 ręcznych przycisków oddymiania,","b": "4 ręcznych przycisków oddymiania,","c": "5 ręcznych przycisków oddymiania."},"category": "Odporność ogniowa i klasy budynków"},{"id": 321,"q": "Sytuowanie wyniesionych ponad dach wylotów kanałów dymowych w dachu budynku niższego, w pasie o szerokości mniejszej niż 8 m od budynku wyższego ze ścianą zewnętrzną z bezklasowymi otworami okiennymi zlokalizowanymi w odległości mniejszej niż 10 m od dachu budynku niższego, jest:","options": {"a": "dopuszczalne,","b": "dopuszczalne pod warunkiem, że odległość wylotu kanału od najbliższego okna wynosi co najmniej 8 m,","c": "niedopuszczalne."},"category": "Pozostałe / ogólne"},{"id": 322,"q": "Podział korytarza na odcinki nie dłuższe niż 50 m, za pomocą przegród z drzwiami dymoszczelnymi wymagany jest:","options": {"a": "we wszystkich korytarzach o długościach przekraczających 50 m w strefach pożarowych ZL i PM,","b": "w korytarzach o długościach przekraczających 50 m w strefach pożarowych ZL i PM, ale tylko tych, które nie są wyposażone w rozwiązania techniczno-budowlane zapobiegające zadymieniu,","c": "odpowiedzi w lit. a i b nie są prawidłowe."},"category": "Pozostałe / ogólne"},{"id": 323,"q": "Dla budynku magazynowego PM o jednej kondygnacji nadziemnej i wysokości 18 m, stanowiącym jedną strefę pożarową o gęstości obciążenia ogniowego przekraczającej 4000 MJ/m2, który jest wyposażony w stałe samoczynne urządzenia gaśnicze wodne tryskaczowe, wymagane jest zapewnienie klasy odporności pożarowej co najmniej:","options": {"a": "„B”,","b": "„C”,","c": "„E”."},"category": "Odporność ogniowa i klasy budynków"},{"id": 324,"q": "Powierzchnia strefy pożarowej PM o gęstości obciążenia ogniowego 2000 MJ/m2, bez pomieszczeń zagrożonych wybuchem, w wielokondygnacyjnym budynku wysokościowym chronionym przez stałe samoczynne urządzenie gaśnicze zraszaczowe, powinna być:","options": {"a": "nie większa niż 2000 m2,","b": "nie większa niż 1000 m2,","c": "nie dopuszcza się takich przypadków."},"category": "Odporność ogniowa i klasy budynków"},{"id": 325,"q": "Cechę niezapalny i niekapiący posiada sufit podwieszany o klasie reakcji na ogień:","options": {"a": "A2-s1, d1,","b": "B-s3, d0,","c": "C-s1, d0."},"category": "Reakcja na ogień i materiały"},{"id": 326,"q": "W jednokondygnacyjnym budynku produkcyjno-magazynowym o wysokości 15 m, stanowiącym jedną strefę pożarową PM o gęstości obciążenia ogniowego 400 MJ/m2, wyposażonym w stałe urządzenie gaśnicze tryskaczowe, elementy tego budynku powinny być co najmniej:","options": {"a": "nierozprzestrzeniające ognia,","b": "słabo rozprzestrzeniające ogień,","c": "nierozprzestrzeniające ognia, przy czym ściany wewnętrzne i zewnętrzne powinny być co najmniej słabo rozprzestrzeniające ogień."},"category": "Odporność ogniowa i klasy budynków"},{"id": 327,"q": "Minimalna pojemność przeciwpożarowego zbiornika wodnego, stanowiącego uzupełniający zapas wody do zewnętrznego gaszenia pożaru dla budynku hotelowego o pięciu kondygnacjach nadziemnych i powierzchni 5000 m2, przy zapewnionej możliwości pobierania wody z hydrantów zewnętrznych na sieci wodociągowej przeciwpożarowej z wydajnością 17 dm3/s, wynosi:","options": {"a": "30 m3,","b": "50 m3,","c": "100 m3."},"category": "Odporność ogniowa i klasy budynków"},{"id": 328,"q": "Ściana oddzielenia przeciwpożarowego między jednokondygnacyjnym budynkiem biurowym zaliczonym do kategorii zagrożenia ludzi ZL III a wyposażonym w stałe urządzenia gaśnicze wodne dwukondygnacyjnym budynkiem magazynowym PM o wysokości nieprzekraczającej 16 m, stanowiącym jedną strefę pożarową o powierzchni 1000 m2, w którym magazynuje się tworzywa sztuczne w ilości 100 ton, charakteryzujące się ciepłem spalania 42 kJ/g, powinna posiadać klasę odporności ogniowej, co najmniej:","options": {"a": "REI 60,","b": "REI 120,","c": "REI 240."},"category": "Odporność ogniowa i klasy budynków"},{"id": 329,"q": "Zgodnie z rozporządzeniem Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2019 r. poz. 1065 z późn. zm.) odległość zbiornika naziemnego z gazem płynnym o pojemności 4,85 m3, zasilającego instalację gazową w budynku, od granicy działki budowlanej z tym zbiornikiem, przy zachowaniu wymaganej odległości od budynku danego rodzaju, powinna być nie mniejsza niż:","options": {"a": "1 m,","b": "2,5 m,","c": "3 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 330,"q": "W pomieszczeniu o wysokości 7,5 m znajdującym się w strefie pożarowej ZL, chronionej przez system sygnalizacji pożarowej i stałe samoczynne urządzenia gaśnicze wodne tryskaczowe, długość przejścia ewakuacyjnego nie powinna przekraczać:","options": {"a": "60 m,","b": "70 m,","c": "80 m."},"category": "Ewakuacja"},{"id": 331,"q": "Ściany wewnętrzne w samodzielnym pomieszczeniu mieszkalnym w budynku mieszkalnym wysokim, powinny posiadać klasę odporności ogniowej nie mniejszą niż:","options": {"a": "EI 30,","b": "EI 60,","c": "dopuszcza się wykonane tych ścian bez klasy odporności ogniowej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 332,"q": "Ściany oddzielające pomieszczenie zagrożone wybuchem od innych pomieszczeń powinny być odporne na parcie o wartości:","options": {"a": "5 kN/m2,","b": "15 MPa,","c": "15  103 Pa."},"category": "Zagrożenie wybuchem"},{"id": 333,"q": "W tunelu okładziny jego głównej konstrukcji, sufity lub sufity podwieszane wykonuje się z materiałów lub wyrobów co najmniej klasy reakcji na ogień:","options": {"a": "A2-s1, d0,","b": "A2-s3, d0,","c": "A2-s1, d1."},"category": "Reakcja na ogień i materiały"},{"id": 334,"q": "Za warunki, które zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 7 czerwca 2010 r. w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. Nr 109, poz. 719 z późn. zm.) mogą stanowić podstawę do uznania budynku za zagrażający życiu ludzi nie uważa się:","options": {"a": "brak awaryjnego oświetlenia ewakuacyjnego w muzeum w pomieszczeniach wystawowych przewidzianych dla więcej niż 50-ciu zwiedzających,","b": "występowania okładziny ściennej o klasie reakcji na ogień D-s2, d0 na drodze ewakuacyjnej w strefie pożarowej ZL III, jeżeli zapewnione są dwa kierunki ewakuacji,","c": "występowania w wielokondygnacyjnym budynku opieki zdrowotnej wyjścia ewakuacyjnego z budynku o szerokości w świetle 0,9 m, które służy do ewakuacji ludzi ze wszystkich kondygnacji w budynku."},"category": "Ewakuacja"},{"id": 335,"q": "Bazy gazu płynnego powinny być wyposażone w urządzenia i instalacje przeciwpożarowe wodne, przy czym przeciwpożarowe hydranty i działka wodne powinny być rozmieszczone w odległości co najmniej:","options": {"a": "15 m od chronionych obiektów lecz nie dalej niż 75 m,","b": "20 m od chronionych obiektów lecz nie dalej niż 100 m,","c": "25 m od chronionych obiektów lecz nie dalej niż 150 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 336,"q": "Tryskacz o wskaźniku czasu zadziałania RTI=60 m1/2s1/2 i współczynniku przewodności C=0,5 (m/s)1/2 kwalifikuje się do grupy tryskaczy:","options": {"a": "szybkiego reagowania,","b": "specjalnego reagowania,","c": "normalnego reagowania."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 337,"q": "Zgodnie z rozporządzeniem Ministra Gospodarki z dnia 21 listopada 2005 r. w sprawie warunków technicznych, jakim powinny odpowiadać bazy i stacje paliw płynnych, rurociągi przesyłowe dalekosiężne służące do transportu ropy naftowej i produktów naftowych i ich usytuowanie (Dz. U. z 2014 r. poz. 1853 z późn. zm.), pompownie przeciwpożarowe należy lokalizować w odległości od osi obwałowania zbiornika lub jego ściany osłonowej nie mniejszej niż;","options": {"a": "15 m,","b": "20 m,","c": "25 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 338,"q": "Wymagana wydajność sieci wodociągowej przeciwpożarowej, zasilającej hydranty zewnętrzne stanowiące źródło wody do zewnętrznego gaszenia pożaru dla obiektu magazynowego stanowiącego jedną strefę pożarową o gęstości obciążenia ogniowego 4500 MJ/m2 i powierzchni 5500 m2, wyposażonego w urządzenie gaśnicze pianowe o projektowanej wydajności wody 1200 dm3/min przez 4 godziny, zapewnianej ze zbiornika własnego tego urządzenia gaśniczego, wynosi:","options": {"a": "15 dm3/s,","b": "30 dm3/s,","c": "40 dm3/s."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 339,"q": "Drogę pożarową należy doprowadzić do obejmującej plac składowy strefy pożarowej PM poza budynkiem, zawsze w przypadku gdy:","options": {"a": "powierzchnia strefy pożarowej przekracza 20 000 m2, niezależenie od wielkości gęstości obciążenia ogniowego,","b": "gęstość obciążenia ogniowego w strefie pożarowej przekracza 500 MJ/m2 a powierzchnia strefy pożarowej przekracza 1000 m2,","c": "gęstość obciążenia ogniowego w strefie pożarowej przekracza 1000 MJ/m2 a powierzchnia strefy pożarowej przekracza 500 m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 340,"q": "W budynku hotelowym o wysokości 60 m, w którym do zabezpieczenia przed zadymieniem klatek schodowych zastosowano system różnicowania ciśnień zaprojektowany zgodnie z Polską Normą PN-EN-12101-6:2007 Wymagania techniczne dotyczące systemów różnicowania ciśnień – Zestawy urządzeń punkty dostarczania powietrza nie powinny być umieszczane w zasięgu:","options": {"a": "3 m od końcowych drzwi wyjściowych,","b": "5 m od końcowych drzwi wyjściowych,","c": "11 m od końcowych drzwi wyjściowych."},"category": "Ewakuacja"},{"id": 341,"q": "Na magistralnym przewodzie sieci wodociągowej przeciwpożarowej należy stosować hydranty zewnętrzne:","options": {"a": "nadziemne o wydajności co najmniej 20 dm3/s,","b": "nadziemne o średnicy nominalnej DN 100,","c": "podziemne lub nadziemne o średnicy nominalnej DN 150."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 342,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 7 czerwca 2010 r. w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. Nr 109, poz. 719, z późn. zm.) w obiekcie budowlanym niebędącym budynkiem, klasyfikowanym jako produkcyjno-magazynowy, którego powierzchnia strefy pożarowej PM wynosi 1500 m2 a gęstość obciążenia ogniowego w tej strefie nie przekracza 1000 MJ/m2, wymaganym jest zastosowanie:","options": {"a": "tylko hydrantów 52,","b": "hydrantów 33 lub hydrantów 52,","c": "hydranty wewnętrzne nie muszą być stosowane."},"category": "Strefy pożarowe i oddzielenia"},{"id": 343,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 7 czerwca 2010 r. w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. Nr 109, poz. 719, z późn. zm.) w punktach sprzedaży przyborów gazowych gaz płynny można składować w butlach o łącznej masie gazu:","options": {"a": "do 70 kg,","b": "do 440 kg,","c": "do 1350 kg."},"category": "Pozostałe / ogólne"},{"id": 344,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja maksymalna powierzchnia chroniona przez sekcję tryskaczową wodną, przypadająca na jedno stanowisko kontrolno-alarmowe, dla przestrzeni o kategorii zagrożenia pożarowego LH, nie powinna być większa niż:","options": {"a": "8 000 m2,","b": "10 000 m2,","c": "12 000 m2."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 345,"q": "Zgodnie z rozporządzeniem Ministra Transportu i Gospodarki Morskiej z dnia 30 maja 2000 r. w sprawie warunków technicznych, jakim powinny odpowiadać drogowe obiekty inżynierskie i ich usytuowanie (Dz. U. Nr 63 poz. 735, z późn. zm.) wentylatory służące do usuwania dymu i ciepła powinny posiadać́ klasę̨ F, określoną zgodnie z Polską Normą dotyczącą wymagań dla wentylatorów oddymiających, wynikającą̨ z obliczeniowej temperatury dymu, przy czym klasa ta nie może być mniejsza niż:","options": {"a": "F600 60,","b": "F400 120,","c": "dopuszcza się̨ inne klasy niż wskazane w odpowiedziach lit. a i b, jeżeli z analizy obliczeniowej temperatury dymu oraz zapewnienia bezpieczeństwa ekip ratowniczych wynika taka możliwość."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 346,"q": "Minimalna wysokość kurtyny dymowej w hali produkcyjnej o wysokości 5 m w grawitacyjnej instalacji oddymiającej zaprojektowanej według wymagań Polskiej Normy PN-B-02877-4:2001 Ochrona przeciwpożarowa budynków – Instalacje grawitacyjne do odprowadzania dymu i ciepła, wynosi:","options": {"a": "2 m,","b": "1 m,","c": "0,5 m."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 347,"q": "W instalacji wodociągowej przeciwpożarowej minimalna wydajność poboru wody z hydrantu wewnętrznego z wężem płasko składanym o nominalnej średnicy węża 52 mm mierzona na wylocie prądownicy wynosi:","options": {"a": "2,5 dm3/min,","b": "120 dm3/min,","c": "150 dm3/min."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 348,"q": "Zgodnie z Polską Normą PN-B-02877-4:2001/Az1:2006 Ochrona przeciwpożarowa budynków – Instalacje grawitacyjne do odprowadzania dymu i ciepła – Zasady projektowania ze względu na niebezpieczeństwo przeniesienia się pożaru przez klapy dymowe otwory tych klap powinny być usytuowane od ścian oddzielenia przeciwpożarowego o klasie odporności ogniowej REI 240 w odległości co najmniej:","options": {"a": "7 m,","b": "5 m,","c": "norma nie określa wymagań w tym zakresie."},"category": "Odporność ogniowa i klasy budynków"},{"id": 349,"q": "Zgodnie z Polską Normą PN-B-02857:2017 Ochrona przeciwpożarowa budynków – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne maksymalna odległość przeciwpożarowego zbiornika wodnego od obiektu chronionego nie powinna przekraczać:","options": {"a": "500 m,","b": "350 m,","c": "250 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 350,"q": "Co do zasady, im temperatura krytyczna stalowego elementu konstrukcyjnego (nośnego) jest wyższa, tym:","options": {"a": "czas zachowania nośności ogniowej przez ten element jest dłuższy,","b": "czas zachowania nośności ogniowej przez ten element jest krótszy,","c": "temperatura krytyczna nie ma związku z nośnością ogniową elementu."},"category": "Pozostałe / ogólne"},{"id": 351,"q": "Zgodnie z PKN-CEN/TS 54-14:2020 Systemy sygnalizacji pożarowej - Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji w przypadku zastosowania czujek dymu do ochrony korytarza o szerokości 1,8 m i wysokości 2,5 m maksymalna odległość czujki od ściany końcowej tego korytarza wynosi:","options": {"a": "4,4 m,","b": "6,2 m,","c": "7,5 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 352,"q": "Zgodnie z Polską Normą PN-B-02857:2017 Ochrona przeciwpożarowa budynków – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne, dla przeciwpożarowego zbiornika wodnego naziemnego o pojemności powyżej 300 m3, który zapewnia warunki ssania do pracy z napływem, dopuszcza się wykonanie jednego przewodu ssawnego z rury o średnicy nominalnej nie mniejszej niż:","options": {"a": "100 mm,","b": "150 mm,","c": "w normie nie przewidziano takiego rozwiązania."},"category": "Ewakuacja"},{"id": 353,"q": "Zgodnie z Polską Normą PN-B-02431-1:1999 Ogrzewnictwo – Kotłownie wbudowane na paliwo gazowe o gęstości względnej mniejszej niż 1 – Wymagania, drzwi wejściowe do kotłowni o łącznej mocy cieplnej powyżej 60 kW do 2000 kW, na paliwo gazowe o gęstości względnej mniejszej niż 1, powinny:","options": {"a": "być trudno zapalne i mieć szerokość co najmniej 0,8 m,","b": "być niepalne i mieć szerokość co najmniej 0,9 m,","c": "mieć szerokość co najmniej 1,2 m, a wymagań w zakresie palności nie stawia się."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 354,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja intensywność zraszania instalacji tryskaczowej wyraża się w:","options": {"a": "mm/min,","b": "dm3/min,","c": "dm3/m2."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 355,"q": "Zgodnie z rozporządzeniem Ministra Transportu i Gospodarki Morskiej z dnia 30 maja 2000 r. w sprawie warunków technicznych, jakim powinny odpowiadać drogowe obiekty inżynierskie i ich usytuowanie (Dz. U. Nr 63 poz. 735, z późn. zm.), tunel o długości większej niż 500 m powinien być wyposażony w hydranty zewnętrzne, według jednego spośród poniższych wymagań:","options": {"a": "hydranty zewnętrzne nadziemne o średnicy nominalnej DN 80 usytuowane w pobliżu wjazdów do tunelu i w tunelu w odległościach nieprzekraczających 250 m,","b": "hydranty zewnętrzne podziemne o średnicy nominalnej DN 80 usytuowane w pobliżu wjazdów do tunelu i w tunelu w odległościach nieprzekraczających 250 m,","c": "hydranty zewnętrzne nadziemne o średnicy nominalnej DN 100 usytuowane w pobliżu wjazdów do tunelu i w tunelu w odległościach nieprzekraczających 150 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 356,"q": "Urządzenie przeznaczone do użytku w atmosferze potencjalnie wybuchowej, którego znakowanie zawiera symbole „II 1D Ex”, może być zastosowane w przestrzeni zagrożonej wybuchem sklasyfikowanej jako:","options": {"a": "strefa 0,","b": "strefa 1,","c": "strefa 20."},"category": "Zagrożenie wybuchem"},{"id": 357,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 7 czerwca 2010 r. w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. Nr 109, poz. 719, z późn. zm.) pomieszczenia magazynowe, w których składuje się materiały wybuchowe, powodujące podczas wybuchu wytworzenie fali uderzeniowej przekraczającej 5 kPa, rozpatruje się jako:","options": {"a": "pomieszczenia zagrożone wybuchem ze strefami zagrożenia wybuchem,","b": "pomieszczenie zagrożone wybuchem bez stref zagrożenia wybuchem,","c": "odpowiedzi w lit. a i b nie są prawidłowe."},"category": "Zagrożenie wybuchem"},{"id": 358,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 24 lipca 2009 r. w sprawie przeciwpożarowego zaopatrzenia w wodę oraz dróg pożarowych (Dz. U. Nr 124, poz. 1030) wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla znajdującej się w granicach miasta stacji gazu ziemnego wynosi:","options": {"a": "10 dm3/s,","b": "20 dm3/s,","c": "ww. rozporządzenie nie określa wymagań w tym zakresie."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 359,"q": "Zgodnie z Polską Normą PN-EN 671-1:2012 Stałe urządzenia gaśnicze – Hydranty wewnętrzne – Część 1: Hydranty wewnętrzne z wężem półsztywnym efektywny zasięg rzutu prądu gaśniczego rozproszonego płaskiego przy ciśnieniu 0,2 MPa w przypadku hydrantu z wężem półsztywnym nie powinien być mniejszy niż:","options": {"a": "10 m,","b": "6 m,","c": "3 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 360,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz. U. z 2020 r. poz. 296), stałe urządzenia gaśnicze wodne lub pianowe, uruchamiane automatycznie lub ręcznie – w przypadku zapewnienia stałej obsługi tych urządzeń lub posiadania zakładowej straży pożarnej, stosuje się:","options": {"a": "do ochrony strefy pożarowej z odpadami stałymi o gęstości obciążenia ogniowego przekraczającej 2000 MJ/m2 i powierzchni do 2000 m2, która znajduje się w budynku,","b": "w strefie pożarowej z odpadami stałymi o gęstości obciążenia ogniowego do 2000 MJ/m2 i powierzchni przekraczającej 1000 m2, do ochrony lokalnej obszaru magazynowania stałych odpadów palnych, jeżeli gęstość obciążenia ogniowego na dowolnie wybranej jednostce mniejszej niż 500 m2 powierzchni tego obszaru przekracza 4000 MJ/m2,","c": "do ochrony lokalnej obszaru magazynowania stałych odpadów palnych, jeżeli w strefie pożarowej z odpadami stałymi gęstość obciążenia ogniowego przekracza 4000 MJ/m2 na dowolnie wybranej jednostce 500 m2 powierzchni magazynowania tych odpadów."},"category": "Strefy pożarowe i oddzielenia"},{"id": 361,"q": "W budynku wysokim (W) w strefie pożarowej ZL II, podłogi podniesione o 25 cm ponad poziom stropu, powinny mieć co najmniej:","options": {"a": "niepalną konstrukcję nośną oraz niezapalne płyty podłogi od strony przestrzeni podpodłogowej, mające klasę odporności ogniowej REI 60 oraz przestrzeń podpodłogową podzieloną na sektory o powierzchni nie większej niż 1000 m2 przegrodami o klasie odporności ogniowej EI 30,","b": "niepalną konstrukcję nośną oraz niezapalne płyty podłogi od strony przestrzeni podpodłogowej, mające klasę odporności ogniowej REI 60 oraz przestrzeń podpodłogową podzieloną na sektory o powierzchni nie większej niż 1000 m2 przegrodami o klasie odporności ogniowej EI 60,","c": "niepalną konstrukcję nośną oraz niezapalne płyty podłogi od strony przestrzeni podpodłogowej, mające klasę odporności ogniowej REI 30 oraz przestrzeń podpodłogową podzieloną na sektory o powierzchni nie większej niż 1000 m2 przegrodami o klasie odporności ogniowej EI 30."},"category": "Odporność ogniowa i klasy budynków"},{"id": 362,"q": "Czujka роżarowa о klasie czułości A1S:","options": {"a": "zadziała szybciej w przypadku gwałtownej zmiany temperatury otoczenia, nawet poniżej temperaturowego progu zadziałania,","b": "wykrywa dym z podwyższoną czułością,","c": "zadziała po przekroczeniu określonego progu temperatury, niezależnie od szybkości narastania temperatury."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 363,"q": "Magazyn butli z gazem płynnym, zlokalizowany na terenie bazy gazu płynnego, powinien być usytuowany od budynku PM, w którym maksymalna gęstość obciążenia ogniowego wynosi 1000 MJ/m2, w odległości co najmniej:","options": {"a": "8 m,","b": "15 m,","c": "30 m."},"category": "Strefy pożarowe i oddzielenia"},{"id": 364,"q": "Sytuowanie wylotów kanałów dymowych, w dachu budynku niższego, w pasie o szerokości mniejszej niż 8 m od budynku wyższego ze ścianą zewnętrzną z oknami, jest:","options": {"a": "dopuszczalne bez dodatkowych wymagań,","b": "dopuszczalne pod warunkiem, że odległość wylotu kanału od najbliższego okna wynosi co najmniej 8 m,","c": "niedopuszczalne."},"category": "Pozostałe / ogólne"},{"id": 365,"q": "Instalacja gazowa w budynku może być zasilana gazem płynnym z grupy zbiorników naziemnych (w ilości nieprzekraczającej 6 sztuk), pod warunkiem, że ich łączna pojemność nie przekroczy:","options": {"a": "20 m3,","b": "40 m3,","c": "100 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 366,"q": "Zgodnie z rozporządzeniem Ministra Transportu i Gospodarki Morskiej z dnia 30 maja 2000 r. w sprawie warunków technicznych, jakim powinny odpowiadać drogowe obiekty inżynierskie i ich usytuowanie (Dz. U. Nr 63, poz. 735 z późn. zm.) w tunelu drogowym o długości 1,5 km, przewody i kable elektryczne wraz z ich zamocowaniami, które są stosowane w systemach zasilania i sterowania, powinny w przypadku obwodów urządzeń służących ochronie przeciwpożarowej zapewniać ciągłość dostawy energii elektrycznej lub przekazu sygnału przez czas nie mniejszy niż:","options": {"a": "60 minut,","b": "90 minut,","c": "120 minut, z uwagi na bezpieczeństwo ekip ratowniczych."},"category": "Reakcja na ogień i materiały"},{"id": 367,"q": "Zgodnie z Polską Normą PN-B-02857:2017 Ochrona przeciwpożarowa budynków – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne, minimalna odległość stanowiska czerpania wody przy przeciwpożarowym zbiorniku wodnym, przeznaczonym do zewnętrznego gaszenia pożaru jednokondygnacyjnego budynku magazynowego o powierzchni wewnętrznej 2000 m2 i gęstości obciążenia ogniowego 1000 MJ/m2, wykonanego w klasie odporności pożarowej „E”, powinna od ściany zewnętrznej tego budynku wynosić co najmniej:","options": {"a": "8 m,","b": "16 m,","c": "20 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 368,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 7 czerwca 2010 r. w sprawie ochrony przeciwpożarowej budynków, innych obiektów budowlanych i terenów (Dz. U. Nr 109 poz. 719, z późn. zm.) materiałem niebezpiecznym pożarowo nie jest ciecz palna o temperaturze zapłonu:","options": {"a": "327 K,","b": "328 K,","c": "odpowiedzi a i b nie są prawidłowe."},"category": "Pozostałe / ogólne"},{"id": 369,"q": "Zgodnie z Polską Normą PN-EN 12101-6 Systemy kontroli rozprzestrzeniania dymu i ciepła – Część 6: Wymagania techniczne dotyczące systemów różnicowania ciśnień – Zestawy urządzeń, pojedynczy punkt dostarczania powietrza dla każdej klatki schodowej o podwyższonym ciśnieniu dopuszczalny jest w budynkach:","options": {"a": "niskich (N),","b": "o wysokości do 15 m,","c": "o wysokości poniżej 11 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 370,"q": "W wielokondygnacyjnym budynku wysokim (W) wyposażonym w stałe samoczynne urządzenie gaśnicze wodne (tryskaczowe) oraz samoczynne urządzenia oddymiające, dopuszczalna powierzchnia strefy pożarowej PM o gęstości obciążenia ogniowego 2500 MJ/m2 może być powiększona:","options": {"a": "o 100 %,","b": "o 150 %,","c": "nie dopuszcza się występowania takiego przypadku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 371,"q": "Wymagana ilość wody do celów przeciwpożarowych w przeciwpożarowym zbiorniku wodnym służąca do zewnętrznego gaszenia pożaru dla budynku magazynowego, stanowiącego strefę pożarową o gęstości obciążenia ogniowego 5000 MJ/m2 i powierzchni 6000 m2, wyposażonego w urządzenie gaśnicze tryskaczowe o natężeniu przepływu wymaganym dla najbardziej korzystnej powierzchni działania 8000 dm3/min i czasie działania 90 minut, które jest zasilane z własnego odrębnego zbiornika, wynosi:","options": {"a": "432 m3,","b": "864 m3,","c": "1152 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 372,"q": "W jednokondygnacyjnym budynku magazynowym o wysokości kondygnacji w świetle 6 m, wyposażonym w samoczynne urządzenia oddymiające uruchamiane za pomocą systemu wykrywania dymu, stanowiącym jedną strefę pożarową PM o gęstości obciążenia ogniowego 3900 MJ/m2 i powierzchni 1100 m2, w której z przewidywanego przeznaczenia pomieszczeń nie wynika jednoznacznie sposób ich zagospodarowania, maksymalna dopuszczalna długość przejścia ewakuacyjnego wynosi:","options": {"a": "140 m,","b": "150 m,","c": "175 m."},"category": "Ewakuacja"},{"id": 373,"q": "Maksymalna długość drugiego, dłuższego dojścia ewakuacyjnego prowadzącego od wyjścia z pomieszczenia dla ponad 50 osób niebędących ich stałymi użytkownikami do drzwi sąsiedniej strefy pożarowej, znajdującego się w budynku chronionym stałym samoczynnym urządzeniem gaśniczym wodnym (mgłowym), wynosi:","options": {"a": "60 m,","b": "80 m,","c": "120 m."},"category": "Ewakuacja"},{"id": 374,"q": "Zgodnie z Polską Normą PN-EN 81-72:2020 Zasady bezpieczeństwa dotyczące budowy i instalowania dźwigów – Szczególne zastosowania dźwigów osobowych i dźwigów towarowo-osobowych – Część 72: Dźwigi dla straży pożarnej, minimalna szerokość w świetle drzwi do kabiny dźwigu dla straży pożarnej powinna wynosić:","options": {"a": "0,8 m,","b": "0,9 m,","c": "1,1 m."},"category": "Pozostałe / ogólne"},{"id": 375,"q": "Niski (N) budynek biurowy, stanowiący w całości strefę pożarową ZL III z jednym wyjściem ewakuacyjnym na parterze, posiadający trzy kondygnacje nadziemne o łącznej wysokości 11 m oraz jedną kondygnację podziemną o wysokości 3 m, powinien być wykonany w klasie odporności pożarowej co najmniej:","options": {"a": "B,","b": "C,","c": "D."},"category": "Ewakuacja"},{"id": 376,"q": "W garażu podziemnym o powierzchni wewnętrznej 1400 m2, posiadającym 45 stanowisk postojowych, który jest wyposażony w instalację wentylacji oddymiającej strumieniowej, uruchamianą przez system wykrywania dymu, powinny być zapewnione, co najmniej:","options": {"a": "2 wyjścia ewakuacyjne oddalone od siebie minimum 5 m, prowadzące do klatek schodowych lub sąsiednich stref pożarowych,","b": "2 wyjścia ewakuacyjne, przy czym jedno może stanowić wjazd lub wyjazd do garażu,","c": "1 wyjście ewakuacyjne, jeżeli długość przejścia od każdego stanowiska postojowego do tego wyjścia nie przekracza 40 m."},"category": "Ewakuacja"},{"id": 377,"q": "W budynku użyteczności publicznej o wysokości 35 m zastosowanie w lokalu restauracji urządzeń gastronomicznych zasilanych z instalacji gazowej na gaz ziemny jest:","options": {"a": "niedopuszczalne,","b": "dopuszczalne pod warunkiem uzyskania pozytywnej opinii wydanej przez właściwego komendanta wojewódzkiego Państwowej Straży Pożarnej,","c": "dopuszczalne wyłącznie pod warunkiem uzyskania zgody na odstępstwo wydanej w trybie art. 9 ustawy Prawo budowlane."},"category": "Instalacje użytkowe (gazowe, elektryczne, wentylacyjne)"},{"id": 378,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, przestrzenie między dolną płaszczyzną dachu a górną płaszczyzną sufitu podwieszonego lub między stropem a dolną płaszczyzną podłogi podniesionej, powinny być chronione urządzeniem tryskaczowym, jeżeli wysokość tych przestrzeni ukrytych przy dachu lub podłodze jest większa niż:","options": {"a": "0,5 m,","b": "0,8 m,","c": "1 m."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 379,"q": "W bazach paliw płynnych pompownie przeciwpożarowe należy lokalizować od osi obwałowania zbiornika przeznaczonego do magazynowania ropy naftowej i produktów naftowych lub od jego ściany osłonowej w odległości nie mniejszej niż:","options": {"a": "20 m,","b": "25 m,","c": "30 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 380,"q": "W budynku biurowym zaprojektowanym w klasie odporności pożarowej „C”, ze stropodachem wentylowanym, przekrycie dachu może nie posiadać klasy odporności ogniowej RE 15, jeżeli nad najwyższą kondygnacją nadziemną zastosowano strop lub inną przegrodę, które spełniają kryterium klasy odporności ogniowej co najmniej:","options": {"a": "REI 15,","b": "REI 30,","c": "REI 60."},"category": "Odporność ogniowa i klasy budynków"},{"id": 381,"q": "Zgodnie z rozporządzeniem Ministra Rozwoju z dnia 11 września 2020 r. w sprawie szczegółowego zakresu i formy projektu budowlanego (Dz. U. poz. 1609 z późn. zm.) na części rysunkowej projektu architektoniczno-budowlanego oraz projektu technicznego muszą być oznaczone:","options": {"a": "klasy odporności ogniowej elementów budowlanych, stanowiących oddzielenia przeciwpożarowe oraz obudowy dróg ewakuacyjnych,","b": "klasy odporności ogniowej lub dymoszczelności elementów budowlanych, stanowiących oddzielenia przeciwpożarowe oraz obudowy dróg ewakuacyjnych,","c": "klasy odporności ogniowej lub dymoszczelności elementów oddzielenia przeciwpożarowego i innych elementów obiektu budowlanego, w których przejścia instalacyjne muszą być zabezpieczone pod względem przeciwpożarowym, a także drzwi, bram lub innych zamknięć przeciwpożarowych."},"category": "Ewakuacja"},{"id": 382,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze –Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, w poziomach pośrednich w regałach dopuszcza się zainstalowanie tryskaczy zasilanych z tego samego stanowiska kontrolno-alarmowego co tryskacze zainstalowane przy dachu lub stropie, pod warunkiem, że będzie to nie więcej niż:","options": {"a": "50 tryskaczy w regałach,","b": "100 tryskaczy w regałach,","c": "500 tryskaczy w regałach."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 383,"q": "Ściany zewnętrzne kotłowni gazowej z kotłem o mocy cieplnej 350 kW, przeznaczonym do spalania gazu ziemnego, która jest zlokalizowana ponad dachem czterokondygnacyjnego budynku mieszkalnego wielorodzinnego:","options": {"a": "powinny mieć co najmniej klasę odporności ogniowej jak ściany zewnętrzne wynikającą z klasy odporności pożarowej budynku i być wykonane z materiałów klasy reakcji na ogień co najmniej B, d0,","b": "powinny mieć co najmniej klasę odporności ogniowej EI 60 i być wykonane z materiałów niepalnych,","c": "mogą nie podsiadać klasy odporności ogniowej, jeżeli są wykonane z materiałów niepalnych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 384,"q": "W podziemnym garażu zamkniętym o powierzchni 2500 m2, podzielonym na dwie strefy pożarowe o równych powierzchniach, z których tylko jedna ma bezpośredni wjazd i wyjazd na zewnątrz budynku:","options": {"a": "jest wymagane zastosowanie instalacji wentylacji oddymiającej uruchamianej za pomocą systemu wykrywania dymu w całym garażu (w obu strefach pożarowych),","b": "jest wymagane zastosowanie instalacji wentylacji oddymiającej uruchamianej za pomocą systemu wykrywania dymu tylko w strefie pożarowej pozbawionej bezpośredniego wjazdu lub wyjazdu z budynku,","c": "w takim garażu można nie stosować instalacji wentylacji oddymiającej."},"category": "Strefy pożarowe i oddzielenia"},{"id": 385,"q": "W strefie pożarowej PM o powierzchni 8000 m2 i gęstości obciążenia ogniowego 400 MJ/m2, w której znajduje się pomieszczenie o powierzchni 150 m2 i gęstości obciążenia ogniowego 1200 MJ/m2:","options": {"a": "wymagane jest zastosowanie hydrantów 52 w całej strefie pożarowej,","b": "wymagane jest zastosowanie hydrantów 52 wyłącznie do ochrony pomieszczenia, w którym gęstość obciążenia ogniowego przekracza 500 МJ/m2,","c": "nie jest wymagane zastosowanie hydrantów 52."},"category": "Strefy pożarowe i oddzielenia"},{"id": 386,"q": "Zgodnie z Polską Normą PN-EN 12101-1:2007 Systemy kontroli rozprzestrzeniania się dymu i ciepła – Część 1: Wymagania techniczne dotyczące kurtyn dymowych, kurtyna dymowa DA spełnia wymagania klasyfikacji:","options": {"a": "D 30,","b": "D 90,","c": "wszystkie wymagania klasyfikacji D."},"category": "Odporność ogniowa i klasy budynków"},{"id": 387,"q": "Do niskiego (N) dwukondygnacyjnego budynku motelu, posiadającego 20 dwuosobowych pokoi z miejscami noclegowymi:","options": {"a": "wymagane jest doprowadzenie drogi pożarowej w odległości co najmniej 5 m od ścian zewnętrznych budynku i nie większej niż 15 m,","b": "dopuszczalne jest wykonanie drogi pożarowej w odległości nie większej niż 30 m od wejść do klatek schodowych budynku,","c": "doprowadzenie drogi pożarowej nie jest wymagane."},"category": "Ewakuacja"},{"id": 388,"q": "Zgodnie z Polską Normą PN-EN 12845+А1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, każde zasilanie wodą powinno mieć wydajność wystarczającą do tego, aby dla klasy zagrożenia pożarowego HHP zapewnić minimalny czas działania:","options": {"a": "60 minut,","b": "90 minut,","c": "wynikający z obliczeniowego czasu trwania pożaru."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 389,"q": "Awaryjne oświetlenie ewakuacyjne należy obligatoryjnie zastosować w pomieszczeniu:","options": {"a": "lokalu rozrywkowego przeznaczonego dla 150 osób,","b": "o powierzchni netto 1200 m2 w budynku użyteczności publicznej, niezależnie od liczby przebywających w nim osób,","c": "sali widowiskowej z widownią przeznaczoną dla 40 osób."},"category": "Ewakuacja"},{"id": 390,"q": "Na terenie zamkniętym służącym obronności państwa stosowanie systemu sygnalizacji pożarowej jest wymagane w przypadku:","options": {"a": "budynku zamieszkania zbiorowego, w którym przewidywany okres pobytu tych samych osób przekracza trzy doby, a liczba miejsc noclegowych przekracza 150,","b": "budynku o liczbie miejsc służących celom gastronomicznym wynoszącej 500,","c": "odpowiedzi a i b nie są prawidłowe."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 391,"q": "W przypadku jednokondygnacyjnego budynku magazynowego ze strefami pożarowymi o gęstości obciążenia ogniowego poniżej 500 MJ/m2 drogę pożarową należy doprowadzić, jeżeli powierzchnia strefy pożarowej PM przekracza:","options": {"a": "10 000 m2,","b": "20 000 m2,","c": "obowiązek doprowadzenia drogi pożarowej nie dotyczy takich budynków bez względu na ich powierzchnię."},"category": "Odporność ogniowa i klasy budynków"},{"id": 392,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 24 lipca 2009 r. w sprawie przeciwpożarowego zaopatrzenia w wodę oraz dróg pożarowych (Dz. U. Nr 124, poz. 1030) w przypadku stosowania w budynku o wysokości 24 m z 8 kondygnacjami nadziemnymi okien dla ekip ratowniczych w klatkach schodowych zapewniających komunikację z każdą kondygnacją, okna te powinny znajdować się:","options": {"a": "w każdej klatce schodowej, zarówno służącej ewakuacji, jak i nieprzewidzianej do tego celu,","b": "w każdej klatce schodowej służącej ewakuacji,","c": "w tylu klatkach schodowych, aby zapewniona była możliwość dotarcia do takiego okna poziomymi drogami ewakuacyjnymi o długości nieprzekraczającej 50 m."},"category": "Ewakuacja"},{"id": 393,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz. U. z 2020 r. poz. 296), strefę pożarową z odpadami stałymi, która znajduje się w budynku, wyposaża się w samoczynne urządzenia oddymiające, jeżeli jej powierzchnia przekracza:","options": {"a": "500 m2 i gęstość obciążenia ogniowego przekracza 4000 MJ/m2, a przedmiotowy obowiązek nie dotyczy stref pożarowych niespełniających tych warunków,","b": "1000 m2 i gęstość obciążenia ogniowego przekracza 1000 MJ/m2, a przedmiotowy obowiązek nie dotyczy stref pożarowych niespełniających tych warunków,","c": "2000 m2 i gęstość obciążenia ogniowego przekracza 2000 MJ/m2, a przedmiotowy obowiązek nie dotyczy stref pożarowych niespełniających tych warunków."},"category": "Strefy pożarowe i oddzielenia"},{"id": 394,"q": "Zgodnie z Polska Normą PN-BN 1838:2013 Zastosowania oświetlenia – Oświetlenie awaryjne, awaryjne oświetlenie ewakuacyjne na drodze ewakuacyjnej powinno być zaprojektowane i wykonane w taki sposób, aby:","options": {"a": "50 % wymaganego natężenia oświetlenia było wytworzone w ciągu 30 s, a 100 % natężenia oświetlenia w ciągu 60 s,","b": "50 % wymaganego natężenia oświetlenia było wytworzone w ciągu 5 s, a 100 % natężenia oświetlenia w ciągu 60 s,","c": "100 % natężenia oświetlenia było wytworzone w ciągu 5 s."},"category": "Ewakuacja"},{"id": 395,"q": "Uzgodnienia pod względem zgodności z wymaganiami ochrony przeciwpożarowej wymaga projekt architektoniczno-budowlany budynku:","options": {"a": "niskiego (N) zawierającego strefę pożarową o powierzchni m2, zakwalifikowaną do kategorii zagrożenia ludzi ZL III, która obejmuje dwie pierwsze kondygnacje nadziemne,","b": "niskiego (N) jednokondygnacyjnego garażu, zawierającego w strefie pożarowej stanowiska postojowe przeznaczone dla 30 samochodów na stanowiskach wielopoziomowych oraz stanowiska postojowe z 20 punktami ładowania pojazdów elektrycznych,","c": "średniowysokiego (SW) produkcyjnego stanowiącego jedną strefę pożarową PM o powierzchni 4000 m2 i gęstości obciążenia ogniowego wynoszącej 200 MJ/m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 396,"q": "Zgodnie z Polską Normą PN-BN 12101-2:2017 Systemy kontroli rozprzestrzeniania dymu i ciepła – Część 2: Urządzenia do grawitacyjnego odprowadzania dymu i ciepła, klasyfikacja klapy dymowej w zakresie parametru Re dotyczy:","options": {"a": "obciążenia śniegiem,","b": "odporności na wysoką temperaturę,","c": "niezawodności."},"category": "Odporność ogniowa i klasy budynków"},{"id": 397,"q": "Zapewnienie przeciwpożarowego zaopatrzenia w wodę do zewnętrznego gaszenia pożaru jest wymagane dla zlokalizowanego poza jednostką osadniczą:","options": {"a": "obiektu gospodarki rolnej o powierzchni strefy pożarowej 1500 m2,","b": "budynku użyteczności publicznej o kubaturze 2000 m3 i powierzchni 400 m2,","c": "stacji paliw ze zbiornikami podziemnymi o łącznej pojemności do 180 m3."},"category": "Strefy pożarowe i oddzielenia"},{"id": 398,"q": "Zgodnie ze specyfikacją techniczną PKN-CENT/TS 54-14: 2020 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, maksymalny promień działania punktowej czujki dymu, zastosowanej w budynku wysokościowym (WW) w pomieszczeniu biurowym о wysokości 3 m, wynosi:","options": {"a": "4,5 m,","b": "6,2 m,","c": "7,5 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 399,"q": "Urządzenie przeznaczone do użytku w atmosferze potencjalnie wybuchowej, którego znakowanie zawiera symbole „II 2G Ex”, może być zastosowane w przestrzeni zagrożonej wybuchem sklasyfikowanej jako:","options": {"a": "strefa 0,","b": "strefa 1,","c": "strefa 20."},"category": "Zagrożenie wybuchem"},{"id": 400,"q": "Zgodnie z Polską Normą PN-B-02857:2017 Ochrona przeciwpożarowa budynków – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne, długość przewodu ssawnego do pracy ze ssaniem, zastosowanego przy przeciwpożarowym zbiorniku wodnym o pojemności do 150 m3, nie powinna przekraczać:","options": {"a": "8 m,","b": "10 m,","c": "16 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 401,"q": "W budynku mieszkalnym wielorodzinnym o 9 kondygnacjach nadziemnych z jedną klatką schodową, w którym na dwóch pierwszych kondygnacjach nadziemnych znajduje się strefa pożarowa z lokalami handlowo-usługowymi przeznaczonymi do jednoczesnego przebywania w nich nie więcej niż 50 osób, a na dwóch kondygnacjach podziemnych znajduje się strefa pożarowa z garażem zamkniętym, klatka schodowa służąca do ewakuacji ze wszystkich stref pożarowych w tym budynku, powinna być obudowana i zamykana drzwiami co najmniej:","options": {"a": "przeciwpożarowymi o klasie odporności ogniowej EI 30 i dymoszczelnymi na kondygnacjach nadziemnych oraz przeciwpożarowymi o klasie odporności ogniowej E 30 i dymoszczelnymi na kondygnacjach podziemnych oddzielonych od klatki przedsionkiem przeciwpożarowym prowadzącym z garażu,","b": "dymoszczelnymi na kondygnacjach nadziemnych oraz podziemnych i dodatkowo przeciwpożarowymi o klasie odporności ogniowej EI 30 na kondygnacjach podziemnych,","c": "przeciwpożarowymi o klasie odporności ogniowej EI 30 i dymoszczelnymi, zarówno na kondygnacjach nadziemnych, jak i podziemnych."},"category": "Ewakuacja"},{"id": 402,"q": "W badaniu uderzeniowym (uderzenia mechanicznego) przeprowadzanym zgodnie z Polską Normą PN-EN 1363-2:2001 Badania odporności ogniowej – Część 2: Procedury alternatywne i dodatkowe, w celu klasyfikacji ściany nośnej o funkcji oddzielającej z uwagi na jej odporność na oddziaływanie mechaniczne M, całkowity ciężar elementu uderzającego wynosi:","options": {"a": "200 kg,","b": "500 kg,","c": "1000 kg."},"category": "Odporność ogniowa i klasy budynków"},{"id": 403,"q": "Zbiornik naziemny z gazem płynnym o pojemności 50 m3 zasilający instalację gazową w budynku produkcyjno-magazynowym, powinien być usytuowany od tego budynku w odległość co najmniej:","options": {"a": "15 m,","b": "20 m,","c": "30 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 404,"q": "Zgodnie z postanowieniami Polskiej Normy PN-EN 12101-13:2022 Systemy kontroli rozprzestrzeniania dymu i ciepła – Część 13: Systemy różnicowania ciśnień (SRC) – Projektowanie i metody obliczeniowe, instalowanie, badania okresowe i konserwacja, określone w tej normie zasady, wymagania i procedury projektowania systemów różnicowania ciśnień (SRC) mają zastosowanie bez konieczności stosowania dodatkowych metod weryfikacji, o których mowa w załączniku D tej normy, dla budynków:","options": {"a": "o wysokości do 60 m,","b": "o wysokości do 60 m, jednak poniżej limitu wysokości określonego dla budynków wysokościowych zgodnie z wymogami krajowymi,","c": "wysokich lub niższych zgodnie z wymogami krajowymi."},"category": "Odporność ogniowa i klasy budynków"},{"id": 405,"q": "Zgodnie z rozporządzeniem Ministra Gospodarki z dnia 26 kwietnia 2013 r. w sprawie warunków technicznych, jakim powinny odpowiadać sieci gazowe i ich usytuowanie (Dz. U. poz. 640) w tłoczni gazu system awaryjnej wentylacji mechanicznej zapewniającej wymianę powietrza w ilości uniemożliwiającej przekroczenie dolnej granicy wybuchowości w pomieszczeniu, w którym znajdują się sprężarki gazu ziemnego, powinien być uruchamiany automatycznie przy przekroczeniu:","options": {"a": "10% dolnej granicy wybuchowości metanu,","b": "20% dolnej granicy wybuchowości metanu,","c": "40% dolnej granicy wybuchowości metanu."},"category": "Zagrożenie wybuchem"},{"id": 406,"q": "W budynku administracyjno-biurowym znajdującym się na terenie zakładu karnego drzwi stanowiące wyjście ewakuacyjne powinny otwierać się na zewnątrz pomieszczenia:","options": {"a": "przeznaczonego do jednoczesnego przebywania w nim ponad 50 osób będących jego stałymi użytkownikami,","b": "do którego jest możliwe niespodziewane przedostanie się mieszanin wybuchowych lub substancji trujących, duszących bądź innych, mogących utrudnić ewakuację,","c": "odpowiedzi w lit. a) i b) są prawidłowe."},"category": "Ewakuacja"},{"id": 407,"q": "Zgodnie z wymaganiami rozporządzenia Ministra Rolnictwa i Rozwoju Wsi z dnia 13 stycznia 2023 r. w sprawie warunków technicznych, jakim powinny odpowiadać budowle rolnicze i ich usytuowanie (Dz. U. poz. 297), silos na zboże lub pasze o pojemności większej niż 100 ton powinien być usytuowany od nieprzeznaczonego na pobyt ludzi budynku produkcyjno-magazynowego o gęstości obciążenia ogniowego powyżej 4000 MJ/m2 w odległości co najmniej:","options": {"a": "8 m,","b": "15 m,","c": "20 m."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 408,"q": "W budynku o wymaganej klasie odporności pożarowej „C” przeszklenia wypełniające otwory w ścianie wewnętrznej pomiędzy dwoma pomieszczeniami biurowymi, stanowiącej element oddzielenia przeciwpożarowego, których łączna powierzchnia nie przekracza 10 % powierzchni tej ściany, powinny być wykonane w klasie odporności ogniowej nie niższej niż:","options": {"a": "E 60,","b": "EI 60,","c": "E 120."},"category": "Odporność ogniowa i klasy budynków"},{"id": 409,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz. U. poz. 296), znajdująca się w budynku strefa pożarowa z odpadami stałymi o powierzchni 2500 m2 powinna być wyposażona w:","options": {"a": "samoczynne urządzenia oddymiające i stałe urządzenia gaśnicze wodne lub pianowe, jeżeli gęstość obciążenia ogniowego w tej strefie pożarowej przekracza 1000 MJ/m2,","b": "samoczynne urządzenia gaśnicze wodne lub pianowe przeznaczone do ochrony lokalnej obszarów magazynowania stałych odpadów palnych, jeżeli gęstość obciążenia ogniowego na przynajmniej jednej dowolnie wybranej jednostce 500 m2 powierzchni magazynowania tych odpadów przekracza 2000 MJ/m2,","c": "samoczynne urządzenia oddymiające, jeżeli gęstość obciążenia ogniowego w tej strefie pożarowej na każdej jednostce jej powierzchni 500 m2 przekracza 1000 MJ/m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 410,"q": "W projektowanym pomieszczeniu przeznaczonym do jednoczesnego przebywania do 300 osób, w którym miejsca do siedzenia są ustawione w 7 rzędach po 35 miejsc w jednym rzędzie, wymagane jest zapewnienie zgodnie z przepisami techniczno-budowlanymi przejść ewakuacyjnych pomiędzy tymi rzędami o szerokości nie mniejszej niż:","options": {"a": "0,64 m,","b": "0,72 m,","c": "0,90 m."},"category": "Ewakuacja"},{"id": 411,"q": "Nad pomieszczeniem zagrożonym wybuchem o powierzchni 150 m2 i wysokości 4 m, nie jest wymagane stosowanie lekkiego dachu (o masie nieprzekraczającej 75 kg/m2 rzutu), w przypadku zastosowania urządzeń odciążających o łącznej powierzchni:","options": {"a": "39,0 m2,","b": "39,5 m2, a odpowiedzi w lit. a) i c) są nieprawidłowe,","c": "39,0 m2, przy czym nie mniej niż wynikająca z obliczeń przyrostu ciśnienia w pomieszczeniu oraz parcia na ściany o wartości nie większej niż 15 kN/m2."},"category": "Zagrożenie wybuchem"},{"id": 412,"q": "Do usuwania dymu i ciepła z tunelu drogowego o długości większej niż 500 m, prowadzącego jezdnię dwukierunkową, można zastosować system wentylacji mechanicznej półporzecznej, bez konieczności potwierdzania skuteczności działania tego rodzaju wentylacji w analizie ryzyka lub stosowania szczególnych środków, takich jak np. krótsze odległości do wyjść awaryjnych, jeżeli długość tego tunelu jest nie większa niż:","options": {"a": "1000 m,","b": "1500 m,","c": "3000 m."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 413,"q": "W danych tabelarycznych zawartych w Polskiej Normie PN-EN 1992-1-2:2008 Eurokod 2: Projektowanie konstrukcji z betonu – Część 1-2: Reguły ogólne – Projektowanie z uwagi na warunki pożarowe, jedną z danych ujętych w tabeli Metody A, służącej do określania (oceny) klasy odporności ogniowej słupów żelbetowych, jest:","options": {"a": "odległość osiowa skrajnych prętów zbrojenia pomocniczego,","b": "grubość otuliny zbrojenia (głównych prętów),","c": "odległość osiowa zbrojenia (głównych prętów)."},"category": "Odporność ogniowa i klasy budynków"},{"id": 414,"q": "Źródłem wody do celów przeciwpożarowych w lasach, które samoistnie lub wspólnie tworzą kompleks leśny o powierzchni ponad 300 ha, jest studnia z pompą oraz z innym niż hydrant zewnętrzny punktem poboru wody z nasadą:","options": {"a": "tłoczną typu 75 lub 110,","b": "ssawną typu 110,","c": "tłoczną typu 75 i ssawną typu 110."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 415,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, w sekcji tryskaczowej tandemowej przy klasie zagrożenia pożarowego LH, maksymalny czas od otwarcia pojedynczego tryskacza do wypływu wody nie powinien przekraczać:","options": {"a": "60 s,","b": "90 s,","c": "120 s."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 416,"q": "Wolnostojący garaż o pięciu kondygnacjach nadziemnych, zlokalizowany na terenie zamkniętym podległym Ministrowi Spraw Wewnętrznych i Administracji, powinien być wyposażony w następujące punkty poboru wody do celów przeciwpożarowych:","options": {"a": "hydranty 33,","b": "hydranty 52,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe – hydranty wewnętrzne w tym garażu nie są wymagane."},"category": "Odporność ogniowa i klasy budynków"},{"id": 417,"q": "W ścianie zewnętrznej czterokondygnacyjnego budynku żłobka o wysokości 14 m, zastosowanie izolacji cieplnej z samogasnącego polistyrenu spienionego jest dopuszczalne w przypadku, gdy okładzina osłaniająca tę izolację od wewnątrz ma:","options": {"a": "klasę odporności ogniowej co najmniej EI 60 i klasę reakcji na ogień A2-s3, d0,","b": "klasę odporności ogniowej co najmniej EI 60 (o↔i) i klasę reakcji na ogień B-s1, d0,","c": "klasę odporności ogniowej co najmniej EI 30 (o↔i) i klasę reakcji na ogień A2-s1, d0."},"category": "Odporność ogniowa i klasy budynków"},{"id": 418,"q": "Zgodnie z Polską Normą PN-B-02852:2001 Ochrona przeciwpożarowa budynków − Obliczanie gęstości obciążenia ogniowego oraz wyznaczanie względnego czasu trwania pożaru, przy obliczaniu gęstości obciążenia ogniowego strefy pożarowej chłodni, w której składowane są mrożonki mięsne zapakowane w workach foliowych, złożone w kartonach na paletach z tworzyw sztucznych:","options": {"a": "uwzględnia się tylko 10% masy rzeczywistej tak składowanych materiałów palnych,","b": "uwzględnia się tylko 20% masy rzeczywistej tak składowanych materiałów palnych,","c": "uwzględnia się całkowitą masę tak składowanych materiałów palnych."},"category": "Strefy pożarowe i oddzielenia"},{"id": 419,"q": "W niskim (N) budynku PM o gęstości obciążenia ogniowego 800 MJ/m2, wyposażonym w stałe samoczynne urządzenia gaśnicze wodne, dopuszczalne jest zastosowanie następujących elementów słabo rozprzestrzeniających ogień:","options": {"a": "stropów, ścian zewnętrznych i elementów konstrukcji dachu,","b": "ścian zewnętrznych i elementów konstrukcji dachu, a stropy powinny być nierozprzestrzeniające ognia,","c": "ścian wewnętrznych i zewnętrznych, a konstrukcja i przekrycie dachu powinny być nierozprzestrzeniające ognia."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 420,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 17 września 2021 r. w sprawie uzgadniania projektu zagospodarowania działki lub terenu, projektu architektoniczno-budowlanego, projektu technicznego oraz projektu urządzenia przeciwpożarowego pod względem zgodności z wymaganiami ochrony przeciwpożarowej (Dz. U. poz. 1722), scenariusz pożarowy nie jest wymagany dla:","options": {"a": "budynku przedszkola dwukondygnacyjnego o wysokości poniżej 12 m,","b": "garażu podziemnego jednokondygnacyjnego, otwartego, obejmującego dwie strefy pożarowe o powierzchni 1500 m2, w którym wyjazd z jednej strefy na zewnątrz budynku prowadzi pośrednio przez sąsiednią strefę pożarową,","c": "garażu podziemnego, obejmującego dwie kondygnacje podziemne stanowiące odrębne strefy pożarowe o powierzchni 1000 m2, z których każda posiada bezpośredni wyjazd na zewnątrz, zlokalizowanego na terenie zamkniętym służącym obronności państwa."},"category": "Odporność ogniowa i klasy budynków"},{"id": 421,"q": "W strefie pożarowej PM o powierzchni 5000 m2 i gęstości obciążenia ogniowego 1000 MJ/m2, obejmującej pomieszczenie magazynowe o powierzchni netto 3000 m2, która znajduje się w projektowanym jednokondygnacyjnym budynku produkcyjno- magazynowym o wysokości 35 m, wymagane jest zastosowanie następujących urządzeń przeciwpożarowych:","options": {"a": "instalacji wodociągowej przeciwpożarowej z hydrantami wewnętrznymi 52 i zaworami hydrantowymi 52 oraz awaryjnego oświetlenia ewakuacyjnego w pomieszczeniu magazynowym i na drogach ewakuacyjnych z tego pomieszczenia,","b": "instalacji wodociągowej przeciwpożarowej z hydrantami wewnętrznymi 33 i zaworami hydrantowymi 52 oraz awaryjnego oświetlenia ewakuacyjnego i stałe samoczynne urządzenie gaśnicze wodne,","c": "instalacji wodociągowej przeciwpożarowej z hydrantami wewnętrznymi 52 oraz awaryjnego oświetlenia ewakuacyjnego w pomieszczeniu magazynowym i na drogach ewakuacyjnych z tego pomieszczenia."},"category": "Ewakuacja"},{"id": 422,"q": "Na podstawie Polskiej Normy PN-EN IEC 60079-10-1:2021-09 Atmosfery wybuchowe – Część 10-1: Klasyfikacja przestrzeni – Gazowe atmosfery wybuchowe, strefę obejmującą przestrzeń, w której atmosfera wybuchowa gazu ziemnego o średnim stężeniu objętościowym 50% DGW w postaci obłoku o objętości mniejszej niż 0,1 m3 i 1% danej zwartej przestrzeni zamkniętej, występuje sporadycznie podczas normalnej pracy, klasyfikuje się jako:","options": {"a": "strefę 1,","b": "strefę 1 NE,","c": "strefę 2."},"category": "Zagrożenie wybuchem"},{"id": 423,"q": "W budynku produkcyjno-magazynowym o dwóch kondygnacjach nadziemnych, nieznajdującym się na terenie zamkniętym, pomieszczenie zagrożone wybuchem może być usytuowane na pierwszej kondygnacji nadziemnej, jeżeli będzie ono wyposażone w instalacje i urządzenia przeciwwybuchowe:","options": {"a": "odciążające o powierzchni 0,065 m2/m3 kubatury przestrzeni powietrznej pomieszczenia,","b": "uzgodnione z właściwym komendantem wojewódzkim Państwowej Straży Pożarnej,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe."},"category": "Odporność ogniowa i klasy budynków"},{"id": 424,"q": "W budynku biurowym wysokim (W) strefa pożarowa PM archiwum o gęstości obciążenia ogniowego 1500 MJ/m2, usytuowana na kondygnacji podziemnej, z której wyjścia ewakuacyjne prowadzą bezpośrednio na zewnątrz budynku, nie może przekraczać powierzchni dopuszczalnej wynoszącej:","options": {"a": "500 m2,","b": "1000 m2,","c": "2000 m2."},"category": "Ewakuacja"},{"id": 425,"q": "Zgodnie z Polską Normą PN-EN 15004-1:2019 Stałe urządzenia gaśnicze − Urządzenia gaśnicze gazowe − Część 1: Projektowanie, montaż i konserwacja, w przypadku pomieszczeń zabezpieczanych gazem gaśniczym, w których przebywają ludzie:","options": {"a": "niedopuszczalne jest przyjęcie stężenia projektowego gazu gaśniczego powyżej NOAEL (najwyższe stężenie, przy którym nie zaobserwowano niekorzystnych skutków toksykologicznych lub fizjologicznych),","b": "niedopuszczalne jest przyjęcie stężenia maksymalnego gazu gaśniczego powyżej LOAEL (najniższe stężenie, przy którym zaobserwowano niekorzystny efekt toksykologiczny lub fizjologiczny),","c": "dopuszcza się przekroczenie stężenia gazu gaśniczego powyżej LOAEL, pod warunkiem zastosowania ręcznego, mechanicznego urządzenia blokującego, zabezpieczającego przed wyładowaniem gazu gaśniczego."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 426,"q": "Środkiem gaśniczym stosowanym w urządzeniach gaśniczych pianowych instalowanych na zbiornikach naziemnych z dachem stałym o pojemności ponad 3200 m3, przeznaczonych do magazynowania w bazach paliw płynnych produktów naftowych I i II klasy, powinna być piana, która ma współczynnik spienienia:","options": {"a": "większy niż lub równy 200,","b": "większy niż 20, ale mniejszy niż 200,","c": "mniejszy niż 20."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 427,"q": "Zgodnie z Polską Normą PN-EN 12101-13:2022 Systemy kontroli rozprzestrzeniania dymu i ciepła – Część 13: Systemy różnicowania ciśnień (SRC) – Projektowanie i metody obliczeniowe, instalowanie, badania okresowe i konserwacja w klatce schodowej budynku mieszkalnego wielorodzinnego o wysokości 29 m i 9 kondygnacjach nadziemnych, system różnicowania cieśnień (SRC) powinien spełniać wymagania według kryteriów:","options": {"a": "klasy B,","b": "klasy 1,","c": "klasy 2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 428,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, w przypadku urządzeń tryskaczowych przeznaczonych do ochrony kategorii zagrożenia pożarowego HHP lub HHS, pompa tryskaczowa napędzana silnikiem spalinowym powinna posiadać zbiornik paliwa z ilością paliwa wystarczającą do zapewnienia pracy silnika przy pełnym obciążeniu przez czas co najmniej:","options": {"a": "2 godziny,","b": "4 godziny,","c": "6 godzin."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 429,"q": "Zgodnie z Polską Normą PN-B-02857:2017 Ochrona przeciwpożarowa budynków. Przeciwpożarowe zbiorniki wodne. Wymagania ogólne, studzienka ssawna oraz jej połączenie ze zbiornikiem o pojemności powyżej 300 m3, powinny zapewniać możliwość jednoczesnego poboru wody każdym przewodem ssawnym z wydajnością co najmniej:","options": {"a": "10 dm3/s,","b": "15 dm3/s,","c": "20 dm3/s."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 430,"q": "Drogę pożarową należy zapewnić do:","options": {"a": "budynku średniowysokiego zawierającego strefę pożarową produkcyjną lub magazynową o powierzchni 2000 m2 i gęstości obciążenia ogniowego poniżej 500 MJ/m2, w którym występuje pomieszczenie zagrożone wybuchem,","b": "strefy pożarowej poza budynkiem, obejmującej urządzenia technologiczne, w której występuje zagrożenie wybuchem,","c": "wiaty obejmującej strefę pożarową produkcyjną lub magazynową o gęstości obciążenia ogniowego 1000 MJ/m2 i powierzchni 1500 m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 431,"q": "W budynku o wysokości 13 m przeznaczonym przede wszystkim dla osób o ograniczonej zdolności poruszania się (osób starszych), poddasze użytkowe przeznaczone na cele obsługi administracyjnej powinno być oddzielone od konstrukcji i przekrycia dachu o klasie reakcji na ogień A2-s3, d0 przegrodami o klasie odporności ogniowej:","options": {"a": "EI 30,","b": "EI 60,","c": "nie wymaga się stosowania przegród o klasie odporności ogniowej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 432,"q": "Zgodnie ze Specyfikacją Techniczną PKN-CEN/TS 54-14: 2020 Systemy sygnalizacji pożarowej − Wytyczne planowania, projektowania, instalowania, uruchamiania, eksploatacji i konserwacji, punktowe czujki ciepła klasy A1 nie powinny być stosowane do ochrony pomieszczeń o wysokości przekraczającej:","options": {"a": "5 m,","b": "6 m,","c": "7,5 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 433,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze. Automatyczne urządzenia tryskaczowe. Projektowanie, instalowanie i konserwacja, minimalna objętość wody w hydroforze zasilającym stałe urządzenie gaśnicze wodne tryskaczowe, chroniące przestrzeń zakwalifikowaną do klasy zagrożenia pożarowego LH, powinna wynosić:","options": {"a": "6 m3,","b": "15 m3,","c": "23 m3."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 434,"q": "Zastosowanie danych ujętych w tabeli Metody A, określonej w Polskiej Normie PN-EN 1992-1-2:2008 Eurokod 2: Projektowanie konstrukcji z betonu – Część 1-2: Reguły ogólne – Projektowanie z uwagi na warunki pożarowe, dla słupów żelbetowych o długości 8 m, które podtrzymują lekką stalową konstrukcję dachu budynku jednokondygnacyjnego i są sztywno utwierdzone w podłożu, jest:","options": {"a": "właściwe,","b": "niewłaściwe,","c": "właściwe pod warunkiem, że pole przekroju zbrojenia nie przekracza 4 % pola przekroju słupa."},"category": "Odporność ogniowa i klasy budynków"},{"id": 435,"q": "W budynku stanowiącym jedną strefę pożarową ZL, przeznaczoną do sprzedaży produktów z cieczami palnymi o temperaturze zapłonu poniżej 294,15 K (21oC), jest dopuszczalne przechowywanie tych cieczy w pomieszczeniach handlowo-usługowych w ilości:","options": {"a": "do 10 dm3,","b": "do 50 dm3,","c": "takiej, że gęstość obciążenia ogniowego stwarzana przez te ciecze będzie nie większa niż 500 MJ/m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 436,"q": "Zgodnie ze Specyfikacją Techniczną PKN-CEN/TS 54-14: 2020 Systemy sygnalizacji pożarowej − Wytyczne planowania, projektowania, instalowania, uruchamiania, eksploatacji i konserwacji, w magazynach, w których najwyższy poziom składowania towarów przekracza 9 m, maksymalna odległość między otworami próbkującymi zasysającej czujki dymu, powinna wynosić nie więcej niż:","options": {"a": "6,2 m,","b": "6,5 m,","c": "7,5 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 437,"q": "Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynku produkcyjnego, stanowiącego jedną strefę pożarową o powierzchni 200 m2 i gęstości obciążenia ogniowego 3500 MJ/m2, zapewniana przez wodociąg powinna wynosić co najmniej:","options": {"a": "10 dm3/s,","b": "15 dm3/s,","c": "20 dm3/s."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 438,"q": "Zgodnie z Polską Normą PN-EN 12101-8:2012 Systemy kontroli rozprzestrzeniania dymu i ciepła – Część 8: Klapy odcinające w systemach wentylacji pożarowej, przejście klapy odcinającej do wentylacji pożarowej z jednej pozycji krańcowej do drugiej powinno następować od momentu otrzymania sygnału w ciągu:","options": {"a": "60 s,","b": "90 s,","c": "120 s."},"category": "Odporność ogniowa i klasy budynków"},{"id": 439,"q": "Uzgodnienia pod względem zgodności z wymaganiami ochrony przeciwpożarowej nie wymaga projekt architektoniczno-budowlany:","options": {"a": "garażu dwukondygnacyjnego o powierzchni wewnętrznej 1000 m2,","b": "jednokondygnacyjnego budynku handlowo-usługowego parterowego o wysokości nieprzekraczającej 12 m, który stanowi strefę pożarową ZL III o powierzchni 5000 m2,","c": "przejścia podziemnego przeznaczonego tylko do ruchu pieszych, stanowiącego tunel o długości 150 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 440,"q": "Dobierając zabezpieczenie konturowe w celu zapewnienia odpowiedniej klasy odporności ogniowej (w postaci konkretnej farby pęczniejącej) dla dwóch różnych belek stalowych o takiej samej temperaturze krytycznej, przy założeniu takich samych warunków oddziaływania pożaru belka o istotnie niższym wskaźniku ekspozycji przekroju co do zasady będzie wymagała zastosowania zabezpieczenia o grubości:","options": {"a": "większej,","b": "mniejszej,","c": "takie samej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 441,"q": "Zgodnie z rozporządzeniem Ministra Cyfryzacji z dnia 4 grudnia 2019 r. w sprawie warunków organizacyjnych i technicznych dla podmiotów świadczących usługi z zakresu cyberbezpieczeństwa oraz wewnętrznych struktur organizacyjnych operatorów usług kluczowych odpowiedzialnych za cyberbezpieczeństwo (Dz. U. poz. 2479) budynek o jednej kondygnacji nadziemnej projektowany w całości do celów świadczenia usług z zakresu cyberbezpieczeństwa powinien być wykonany w klasie odporności pożarowej nie niższej niż:","options": {"a": "D,","b": "C,","c": "B."},"category": "Odporność ogniowa i klasy budynków"},{"id": 442,"q": "W budynku niskim muzeum awaryjne oświetlenie ewakuacyjne należy zastosować:","options": {"a": "w pomieszczeniach wystawowych oraz na drogach ewakuacyjnych z tych pomieszczeń,","b": "w pomieszczeniach magazynowych zbiorów o powierzchni netto ponad 1000 m2 oraz na drogach ewakuacyjnych z tych pomieszczeń oświetlonych wyłącznie światłem sztucznym,","c": "w pomieszczeniach, o których mowa w odpowiedzi lit. a) i b), oraz w pomieszczeniach konferencyjnych z siedzeniami ustawionymi w rzędach przeznaczonych dla ponad 200 osób i na drogach ewakuacyjnych z tych pomieszczeń."},"category": "Ewakuacja"},{"id": 443,"q": "W budynku średniowysokim stanowiącym dom dla osób starszych, wyposażonym w stałe samoczynne urządzenie gaśnicze wodne, dopuszczalne jest uwzględnienie tego urządzenia gaśniczego do:","options": {"a": "obniżenia klasy odporności pożarowej budynku oraz powiększenia o 50% długości zarówno przejścia ewakuacyjnego, jak i dojścia ewakuacyjnego,","b": "powiększenia o 100% powierzchni strefy pożarowej,","c": "odpowiedzi w lit. a) i b) są prawidłowe."},"category": "Ewakuacja"},{"id": 444,"q": "Zgodnie ze Specyfikacją Techniczną PKN CEN/TS 54-14:2020 Systemy sygnalizacji pożarowej. Wytyczne planowania, projektowania, instalowania, uruchamiania, eksploatacji i konserwacji, w przypadku kwadratowego układu czujek na otwartym obszarze czujki ciepła w pomieszczeniu ze stropem płaskim, powinny być rozmieszczone od ściany lub głównej przeszkody w odległości nie większej niż:","options": {"a": "2,25 m,","b": "3,2 m,","c": "4,5 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 445,"q": "Zgodnie z załącznikiem nr 3 do rozporządzenia Ministra Infrastruktury z dnia 12 kwietnia 2002 r. w sprawie warunków technicznych, jakim powinny odpowiadać budynki i ich usytuowanie (Dz. U. z 2022 r. poz. 1225) przekrycia dachu klasy BR00F uznane za spełniające wymagania w zakresie odporności wyrobów na działanie ognia zewnętrznego, bez potrzeby przeprowadzenia badań, których wykazy zawarte są w decyzjach Komisji Europejskiej publikowanych w Dzienniku Urzędowym Unii Europejskiej, odpowiadają przekryciom:","options": {"a": "nierozprzestrzeniającym ognia,","b": "słabo rozprzestrzeniającym ogień,","c": "silnie rozprzestrzeniającym ogień."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 446,"q": "Zgodnie z Polską Normą PN-EN 15004-1:2019 Stałe urządzenia gaśnicze - Urządzenia gaśnicze gazowe - Część 1: Projektowanie, montaż i konserwacja czas utrzymywania stężenia gazu gaśniczego w pomieszczeniu serwerowni, w którym po wyładowaniu gazu będzie działała klimatyzacja w obiegu zamkniętym, rozpoczyna się w chwili, gdy stężenie gazu gaśniczego osiągnie w całym pomieszczeniu wartość minimalnego stężenia projektowego a kończy się, gdy stężenie gazu gaśniczego osiągnie w dowolnym miejscu pomieszczenia wartość:","options": {"a": "niższą niż 80 % stężenia projektowego,","b": "niższą niż 85 % stężenia projektowego,","c": "odpowiedzi w lit. a) i b) nie są prawidłowe, ponieważ po wyładowaniu gazu gaśniczego klimatyzacja powinna być wyłączona."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 447,"q": "Zgodnie z Polską Normą PN-EN 13501-2:2023 Klasyfikacja ogniowa wyrobów budowlanych i elementów budynków – Część 2: Klasyfikacja na podstawie wyników badań odporności ogniowej i/lub dymoszczelności, z wyłączeniem instalacji wentylacyjnej klasyfikacja elementów budowlanych z uwagi na promieniowanie (W) jest podawana jako czas, przez który maksymalna wartość promieniowania, mierzonego w sposób podany w normie badań, nie przekroczyła wartości:","options": {"a": "8 kW/m2,","b": "12,5 kW/m2,","c": "15 kW/m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 448,"q": "Uzgodnienie projektu urządzenia przeciwpożarowego z rzeczoznawcą do spraw zabezpieczeń przeciwpożarowych pod względem zgodności z wymaganiami ochrony przeciwpożarowej w przypadku jego sporządzenia w postaci elektronicznej potwierdza się przez opatrzenie go:","options": {"a": "kwalifikowanym podpisem elektronicznym oraz wydaniem dla niego karty uzgodnienia opatrzonej tym podpisem, która stanowi załącznik do projektu,","b": "kwalifikowanym podpisem elektronicznym lub podpisem zaufanym oraz wydaniem dla niego karty uzgodnienia opatrzonej tym podpisem, która stanowi załącznik do projektu,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe – obecnie nie jest dopuszczalne uzgodnienie projektu urządzenia przeciwpożarowego w postaci elektronicznej."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 449,"q": "W budynku mieszkalnym wielorodzinnym o wysokości 14 m, posiadającym na ostatniej czwartej kondygnacji nadziemnej kotłownię gazową zasilaną z sieci gazowej, zastosowanie w mieszkaniach odrębnych instalacji gazowych zasilanych gazem płynnym jest:","options": {"a": "niedopuszczalne,","b": "dopuszczalne przy zasilaniu indywidualnym z jednej butli o nominalnej zawartości gazu do 22 kg,","c": "dopuszczalne przy zasilaniu indywidualnym z maksymalnie dwóch butli o nominalnej zawartości gazu w butli do 11 kg."},"category": "Odporność ogniowa i klasy budynków"},{"id": 450,"q": "Średniowysoki budynek garażu otwartego wielokondygnacyjnego z pomieszczeniami technicznymi nad najwyższą kondygnacją przeznaczoną do parkowania samochodów, w którym najwyższy poziom parkowania znajduje się na wysokości 20 m nad poziomem otaczającego terenu, powinien być wykonany w klasie odporności pożarowej:","options": {"a": "co najmniej D, jeżeli poza pomieszczeniami technicznymi występującymi nad kondygnacją przeznaczoną do parkowania samochodów nie znajdują się inne pomieszczenia przeznaczone na pobyt ludzi,","b": "co najmniej C, jeżeli jest wykonany z elementów nierozprzestrzeniających ognia, niekapiących i nieodpadających pod wpływem ognia,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe."},"category": "Odporność ogniowa i klasy budynków"},{"id": 451,"q": "W obszarze miejskim sieć wodociągowa przeciwpożarowa, która służy nie tylko do celów przeciwpożarowych, może być wykonana jako sieć rozgałęzieniowa:","options": {"a": "jeżeli przy wymaganej ilości wody do celów przeciwpożarowych przekraczającej 20 dm3/s zapewnione będzie zasilanie w dwóch punktach znajdujących się w możliwie największej odległości od siebie,","b": "jeżeli łączna wymagana ilość wody dla potrzeb przeciwpożarowych, bytowo- gospodarczych oraz przemysłowych jest nie większa niż 20 dm3/s,","c": "tylko w odgałęzieniach sieci obwodowej zasilających hydranty zewnętrzne."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 452,"q": "Projektowany na terenie bazy paliw płynnych zbiornik naziemny z dachem stałym o pojemności 20 000 m3, przeznaczony do magazynowania produktów naftowych o temperaturze zapłonu 23oC powinien być wyposażony w:","options": {"a": "stałe urządzenia gaśnicze pianowe i półstałe urządzenia zraszaczowe,","b": "półstałe urządzenia gaśnicze pianowe i stałe urządzenia zraszaczowe,","c": "stałe urządzenia gaśnicze pianowe i stałe urządzenia zraszaczowe."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 453,"q": "Kable i przewody elektryczne oraz światłowodowe zainstalowane wewnątrz tunelu lub stacji metra muszą posiadać klasę reakcji na ogień:","options": {"a": "co najmniej Bca-s3, d0, a produkty ich rozkładu termicznego kwasowość mniejszą niż pH 4,3,","b": "co najmniej B1ca-s1, d0, a1,","c": "co najmniej B2ca-s1, d0, a1."},"category": "Reakcja na ogień i materiały"},{"id": 454,"q": "W budynku mieszkalnym wielorodzinnym wysokościowym, w którym drogi ewakuacyjne są chronione przez stałe urządzenia gaśnicze, uruchamiane samoczynnie za pomocą systemu wykrywania dymu, długość dojścia ewakuacyjnego mierzona przy jednym dojściu na poziomej drodze ewakuacyjnej, nie powinna przekraczać:","options": {"a": "20 m,","b": "30 m,","c": "40 m."},"category": "Ewakuacja"},{"id": 455,"q": "Zgodnie z Polską Normą PN-B-02431-1:1999 Ogrzewnictwo. Kotłownie wbudowane na paliwa gazowe o gęstości względnej mniejszej niż 1. Wymagania sygnalizator akustyczny zastosowany w kotłowni z kotłami na paliwo gazowe o łącznej mocy cieplnej 100 kW powinien informować użytkowników budynku o przekroczeniu dopuszczalnego stężenia wynoszącego:","options": {"a": "10 % dolnej granicy wybuchowości mieszaniny gazu z powietrzem,","b": "20 % dolnej granicy wybuchowości mieszaniny gazu z powietrzem,","c": "30 % dolnej granicy wybuchowości mieszaniny gazu z powietrzem."},"category": "Zagrożenie wybuchem"},{"id": 456,"q": "Sieć wodociągowa stanowiąca źródło wody do celów przeciwpożarowych, w której łączna wymagana ilość wody przekracza 30 dm3/s, a długość obwodu wynosi 900 m, powinna być zasilana w dwóch punktach znajdujących się od siebie w odległości nie mniejszej niż:","options": {"a": "125 m,","b": "225 m,","c": "325 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 457,"q": "Doprowadzenie drogi pożarowej nie jest wymagane do:","options": {"a": "niskiego dwukondygnacyjnego domu dla osób starszych o powierzchni strefy pożarowej 1000 m2, która obejmuje kondygnację inną niż pierwsza,","b": "budynku średniowysokiego zawierającego strefę pożarową PM o powierzchni 2000 m2 i gęstości obciążenia ogniowego 450 MJ/m2, w którym nie występuje pomieszczenie zagrożone wybuchem,","c": "stanowiska czerpania wody do celów przeciwpożarowych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 458,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, kombinowane źródła zasilania wodą, które są projektowane w celu zasilania więcej niż jednego urządzenia do gaszenia pożaru, mogą być wykonane jako:","options": {"a": "pojedyncze źródła zasilania wodą lub pojedyncze źródła zasilania wodą o zwiększonej niezawodności,","b": "pojedyncze źródła zasilania wodą o zwiększonej niezawodności lub podwójne źródła zasilania wodą,","c": "wyłącznie podwójne źródła zasilania wodą."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 459,"q": "Zgodnie z Polską Normą PN-EN 12101-13:2022 Systemy kontroli rozprzestrzeniania dymu i ciepła − Część 13: Systemy różnicowania ciśnień (SRC) − Projektowanie i metody obliczeniowe, instalowanie, badania okresowe i konserwacja, w systemie klasy 1 prędkość przepływu powietrza w otworze drzwiowym na kondygnacji objętej pożarem powinna być nie mniejsza niż:","options": {"a": "0,75 m/s,","b": "1 m/s,","c": "2 m/s."},"category": "Odporność ogniowa i klasy budynków"},{"id": 460,"q": "Indywidualna dokumentacja techniczna wyrobu budowlanego, służącego zapewnieniu w obiekcie budowlanym wymagania podstawowego „Bezpieczeństwo pożarowe”, sporządzona w ramach jego dopuszczenia do jednostkowego zastosowania w obiekcie budowlanym powinna być sporządzona przez:","options": {"a": "producenta wyrobu i musi być uzgodniona z rzeczoznawcą do spraw zabezpieczeń przeciwpożarowych,","b": "projektanta obiektu i musi być uzgodniona z rzeczoznawcą do spraw zabezpieczeń przeciwpożarowych,","c": "projektanta obiektu lub z nim uzgodniona."},"category": "Przepisy formalno-prawne i uzgodnienia"},{"id": 461,"q": "Projektowany budynek domu pomocy społecznej, w którym przewidziano 80 miejsc przeznaczonych dla jego mieszkańców, powinien być wyposażony w:","options": {"a": "system alarmu przeciwpożarowego wykonany w oparciu o autonomiczne czujki dymu,","b": "system sygnalizacji pożarowej, obejmujący urządzenia sygnalizacyjno-alarmowe, służące do samoczynnego wykrywania i przekazywania informacji o pożarze, a także urządzenia odbiorcze alarmów pożarowych i urządzenia odbiorcze sygnałów uszkodzeniowych,","c": "system sygnalizacji pożarowej, który nie musi być połączony z obiektem komendy Państwowej Straży Pożarnej lub innym obiektem, wskazanym przez właściwego miejscowo komendanta powiatowego (miejskiego) Państwowej Straży Pożarnej."},"category": "Ewakuacja"},{"id": 462,"q": "Zgodnie z rozporządzeniem Ministra Gospodarki z dnia 26 kwietnia 2013 r. w sprawie warunków technicznych, jakim powinny odpowiadać sieci gazowe i ich usytuowanie (Dz. U. poz. 640) pomieszczenie w tłoczni gazu, w którym znajdują się sprężarki gazu ziemnego, musi posiadać następujące urządzenia przeciwpożarowe:","options": {"a": "system sygnalizacji pożarowej, a stosowanie stałego urządzenia gaśniczego nie jest wymagane,","b": "stałe urządzenie gaśnicze, a stosowanie systemu sygnalizacji pożarowej nie jest wymagane,","c": "system sygnalizacji pożarowej i stałe urządzenie gaśnicze."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 463,"q": "Zgodnie ze Specyfikacją Techniczną PKN-CEN/TS 54-14:2020 Systemy sygnalizacji pożarowej. Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, maksymalny dopuszczalny promień działania dodatkowej czujki liniowej dymu zainstalowanej na wysokości 10 m nad najbardziej prawdopodobnym miejscem wystąpienia pożaru w pomieszczeniu o wysokości 20 m, wynosi:","options": {"a": "1,25 m,","b": "3,1 m,","c": "6,2 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 464,"q": "Minimalna dopuszczalna odległość dwukondygnacyjnego niskiego budynku PM stanowiącego strefę pożarową PM o maksymalnej gęstości obciążenia ogniowego 3000 MJ/m2, od niskiego budynku mieszkalnego wielorodzinnego, w przypadku, gdy w obu budynkach: ściany zewnętrzne są nierozprzestrzeniające ognia i mają na powierzchni 75 % klasę odporności ogniowej EI 30, przekrycia dachów są klasy BROOF (t1), brak jest pomieszczeń zagrożonych wybuchem oraz stałych urządzeń gaśniczych wodnych i urządzeń oddymiających, wynosi:","options": {"a": "15 m,","b": "20 m,","c": "30 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 465,"q": "Zgodnie ze Specyfikacją Techniczną PKN-CEN/TS 54-14:2020 Systemy sygnalizacji pożarowej. Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji czujki ciepła rozmieszczone na stropie płaskim (poziomym) nie mogą być instalowane niżej niż:","options": {"a": "150 mm poniżej stropu,","b": "300 mm poniżej stropu,","c": "600 mm poniżej stropu."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 466,"q": "W budynku użyteczności publicznej w przestrzeni zagrożonej wybuchem, w której atmosfera wybuchowa zawierająca mieszaninę z powietrzem substancji palnych w postaci gazów, par lub mgieł może czasami wystąpić w trakcie normalnego działania, stosuje się urządzenia kategorii:","options": {"a": "tylko 1,","b": "1 lub 2,","c": "1, 2 lub 3."},"category": "Zagrożenie wybuchem"},{"id": 467,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja w przestrzeni magazynowej chronionej tryskaczami ESFR świetliki zainstalowane w płaszczyźnie sufitu, powinny:","options": {"a": "posiadać klasę B300 30,","b": "wytrzymywać temperaturę wyższą od temperatury zadziałania tryskaczy o minimum 30 °C przez okres co najmniej 10 min.,","c": "wytrzymywać temperaturę 300 °C przez okres co najmniej 5 min."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 468,"q": "Pomieszczenie z cyklonami do palnych pyłów zlokalizowane w budynku niskim produkcyjnym o dwóch kondygnacjach nadziemnych i gęstości obciążenia ogniowego do 1000 MJ/m2, powinno być wydzielone:","options": {"a": "ścianami i stropami o klasie odporności ogniowej co najmniej EI 60 i zamykane drzwiami o klasie odporności ogniowej co najmniej EI 30,","b": "elementami oddzielenia przeciwpożarowego,","c": "ścianami odpornymi na parcie o wartości 15 kN/cm2 – z uwagi na występujące zawsze w tym pomieszczeniu zagrożenie wybuchem."},"category": "Odporność ogniowa i klasy budynków"},{"id": 469,"q": "W pomieszczeniu biurowym przeznaczonym do jednoczesnego przebywania nie więcej niż 6 osób dopuszczalne jest stosowanie wykładzin podłogowych sklasyfikowanych w zakresie klasy reakcji na ogień co najmniej:","options": {"a": "Efl,","b": "Dfl -s2,","c": "Dfl -s1."},"category": "Reakcja na ogień i materiały"},{"id": 470,"q": "Zgodnie z Polską Normą PN-B-02877-4:2001/Az1:2006 Ochrona przeciwpożarowa budynków. Instalacje grawitacyjne do odprowadzania dymu i ciepła. Zasady projektowania, ze względu na niebezpieczeństwo przeniesienia się pożaru przez klapy dymowe zainstalowane w dachu budynku niższego, otwory tych klap powinny być usytuowane od ściany zewnętrznej przylegającego budynku wyższego, która jest wykonana jako nierozprzestrzeniająca ognia, ma klasę odporności ogniowej EI 30 i nie posiada otworów, w odległości co najmniej:","options": {"a": "2,5 m,","b": "5 m,","c": "8 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 471,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz. U. poz. 296) w magazynie ciekłych odpadów palnych chronionym przez stałe samoczynne urządzenia gaśnicze przeznaczone do gaszenia pożarów znajdujących się w nim cieczy palnych, dopuszcza się zwiększenie ilości magazynowanych ciekłych odpadów w strefie pożarowej o:","options": {"a": "50 %,","b": "100 %,","c": "200 %."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 472,"q": "Zgodnie z Polską Normą PN-EN 13501-4:2016 Klasyfikacja ogniowa wyrobów budowlanych i elementów budynków – Część 4: Klasyfikacja na podstawie wyników badań odporności ogniowej elementów systemów kontroli rozprzestrzeniania dymu klapa odcinająca sklasyfikowana jako C300 może być stosowana:","options": {"a": "w mieszanych systemach kontroli rozprzestrzeniania dymu i wentylacji ogólnej, jako klapa regulacyjna,","b": "w mieszanych systemach kontroli rozprzestrzeniania dymu i wentylacji ogólnej, jako klapa nieregulacyjna,","c": "wyłącznie w systemach kontroli rozprzestrzeniania dymu."},"category": "Odporność ogniowa i klasy budynków"},{"id": 473,"q": "Zgodnie z rozporządzeniem Ministra Spraw Wewnętrznych i Administracji z dnia 19 lutego 2020 r. w sprawie wymagań w zakresie ochrony przeciwpożarowej, jakie mają spełniać obiekty budowlane lub ich części oraz inne miejsca przeznaczone do zbierania, magazynowania lub przetwarzania odpadów (Dz. U. poz. 296) w kontenerze magazynowym cieczy palnych o całkowitej objętości magazynowanych ciekłych odpadów palnych wynoszącej 10 m3, w którym ciecze palne magazynowane są w zbiornikach przenośnych o pojemności 1 m3, pojemność netto rozwiązania ograniczającego rozlewisko nie powinna być mniejsza niż:","options": {"a": "1 m3,","b": "1,1 m3,","c": "11 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 474,"q": "Przeciwpożarowy zbiornik wodny podziemny, stanowiący źródło wody do zewnętrznego gaszenia pożaru budynku magazynowego ze strefą pożarową PM o powierzchni 2000 m2 i gęstości obciążenia ogniowego 4000 MJ/m2, powinien posiadać co najmniej:","options": {"a": "jedno stanowisko czerpania wody,","b": "dwa stanowiska czerpania wody,","c": "trzy stanowiska czerpania wody."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 475,"q": "Zastosowany w budynku użyteczności publicznej wysokościowym dźwig dla ekip ratowniczych o wysokości toru jazdy 120 m, powinien, zgodnie z wymaganiami Polskiej Normy PN-EN 81-72:2020 Zasady bezpieczeństwa dotyczące budowy i instalowania dźwigów – Szczególne zastosowania dźwigów osobowych i dźwigów towarowo-osobowych – Część 72: Dźwigi dla straży pożarnej, docierać od poziomu dostępu dla straży pożarnej do najwyższego przystanku przewidzianego do prowadzenia działań gaśniczych w czasie:","options": {"a": "60 s mierzonym od chwili zamknięcia drzwi dźwigu,","b": "60 s mierzonym od chwili uruchomienia łącznika dźwigu,","c": "120 s mierzonym od chwili wysterowania kabinowego łącznika kluczykowego."},"category": "Ewakuacja"},{"id": 476,"q": "W kinie posiadającym 5 pomieszczeń widowni, w którym każde z tych pomieszczeń stanowi odrębną strefę pożarową ZL I z liczbą miejsc na widowni 150, wymagane jest zastosowanie:","options": {"a": "systemu sygnalizacji pożarowej, a zastosowanie dźwiękowego systemu ostrzegawczego nie jest wymagane,","b": "awaryjnego oświetlenia ewakuacyjnego, a zastosowanie systemu sygnalizacji pożarowej i dźwiękowego systemu ostrzegawczego nie jest wymagane,","c": "systemu sygnalizacji pożarowej, dźwiękowego systemu ostrzegawczego oraz awaryjnego oświetlenia ewakuacyjnego."},"category": "Ewakuacja"},{"id": 477,"q": "Odległość odmierzacza paliw płynnych od budynku mieszkalnego wielorodzinnego o konstrukcji niepalnej, który od strony stacji paliw posiada ścianę oddzielenia przeciwpożarowego o klasie odporności ogniowej REI 60, powinna wynosić co najmniej:","options": {"a": "10 m,","b": "20 m,","c": "30 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 478,"q": "Zbiornik podziemny z gazem płynnym o nominalnej pojemności 30 000 dm3, zasilający instalację gazową w budynku, powinien być usytuowany od granicy działki budowlanej z tym zbiornikiem, przy zachowaniu wymaganej odległości od budynku danego rodzaju, w odległości nie mniejszej niż:","options": {"a": "5 m,","b": "10 m,","c": "15 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 479,"q": "W pomieszczeniu zagrożonym wybuchem, nad którym jest zastosowany dach wykonany z materiałów trudno zapalnych, o masie 80 kg/m2 rzutu, licząc bez elementów konstrukcji nośnej dachu, takich jak podciągi, wiązary i belki, łączna powierzchnia urządzeń odciążających (przeciwwybuchowych) może wynosić:","options": {"a": "0,05 m2/m3 kubatury pomieszczenia,","b": "0,06 m2/m3 kubatury pomieszczenia,","c": "0,07 m2/m3 kubatury pomieszczenia."},"category": "Zagrożenie wybuchem"},{"id": 480,"q": "Jednokondygnacyjny budynek galerii handlowo-usługowej o powierzchni wewnętrznej 15 000 m2, z kinem o liczbie miejsc 400 i lokalami gastronomicznymi o łącznej liczbie miejsc służących celom gastronomicznym wynoszącej 500, w którym jako odrębną strefę pożarową wydzielono lokal handlowy (market) o powierzchni 7 500 m2:","options": {"a": "musi być wyposażony w dźwiękowy system ostrzegawczy, a nie wymaga wyposażenia w stałe samoczynne urządzenie gaśnicze wodne,","b": "musi być wyposażony w stałe samoczynne urządzenie gaśnicze wodne, a nie wymaga wyposażenia w dźwiękowy system ostrzegawczy,","c": "nie wymaga wyposażenia w stałe samoczynne urządzenie gaśnicze wodne, ani w dźwiękowy system ostrzegawczy."},"category": "Odporność ogniowa i klasy budynków"},{"id": 481,"q": "Nieizolowane termicznie i akustycznie elastyczne przewody wentylacyjne zastosowane jako elementy łączące do połączenia sztywnych przewodów wentylacyjnych z urządzeniami wentylacyjnymi innymi niż wentylatory, które posiadają długość 3 m, powinny być wykonane z materiałów co najmniej:","options": {"a": "niepalnych,","b": "niezapalnych,","c": "trudno zapalnych."},"category": "Pozostałe / ogólne"},{"id": 482,"q": "Zgodnie z Polską Normą PN-B 02877-4:2025-07 Ochrona przeciwpożarowa budynków – Systemy do grawitacyjnego odprowadzania dymu i ciepła – Część 4: Zasady projektowania, efektywna powierzchnia otworów napływu powietrza kompensacyjnego dostarczanego bezpośrednio z zewnątrz budynku do klatki schodowej w budynku średniowysokim, powinna być nie mniejsza niż:","options": {"a": "łączna wymagana powierzchnia czynna oddymiania tej klatki schodowej,","b": "łączna powierzchnia geometryczna klap dymowych w tej klatce schodowej,","c": "130 % łącznej powierzchni czynnej oddymiania tej klatki schodowej."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 483,"q": "W jednokondygnacyjnym budynku magazynowym o gęstości obciążenia ogniowego powyżej 4000 MJ/m2, wykonanym z elementów nierozprzestrzeniających ognia oraz wyposażonym w samoczynne urządzenia oddymiające, w miejscu połączenia stropu antresoli przeznaczonej do użytku powyżej 10 osób ze ścianą zewnętrzną:","options": {"a": "wymagany jest pas międzykondygnacyjny o wysokości co najmniej 0,8 m,","b": "wymagany jest pas międzykondygnacyjny o wysokości co najmniej 1,2 m,","c": "pas międzykondygnacyjny nie jest wymagany."},"category": "Odporność ogniowa i klasy budynków"},{"id": 484,"q": "Do budynku magazynowego z największą strefą pożarową PM o powierzchni wewnętrznej 980 m2 i całkowitej 1020 m2 oraz gęstości obciążenia ogniowego 4000 MJ/m2, bez pomieszczeń zagrożonych wybuchem, wymagane jest zapewnienie drogi pożarowej, która na terenie działki budowlanej z tym budynkiem, powinna umożliwiać przejazd pojazdów jednostek ochrony przeciwpożarowej o nacisku osi na nawierzchnię jezdni co najmniej:","options": {"a": "50 kN (kiloniutonów),","b": "100 kN (kiloniutonów),","c": "odpowiedzi w lit. a) i b) są nieprawidłowe, ponieważ budynek nie wymaga doprowadzenia drogi pożarowej."},"category": "Zagrożenie wybuchem"},{"id": 485,"q": "W budynku mieszkalnym wielorodzinnym posiadającym 10 kondygnacji nadziemnych, dopuszcza się w obrębie jednego lokalu mieszkalnego stosowanie przewodów wentylacyjnych o klasie reakcji na ogień co najmniej E, pod warunkiem zainstalowania w miejscu przejścia przewodów wentylacyjnych przez przegrody wydzielające lokal mieszkalny:","options": {"a": "zabezpieczenia ogniochronnego o klasie odporności ogniowej co najmniej EI 60,","b": "przeciwpożarowej klapy odcinającej o klasie odporności ogniowej co najmniej EIS 60,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe."},"category": "Odporność ogniowa i klasy budynków"},{"id": 486,"q": "W strefie pożarowej ZL III do wykończenia wnętrz pomieszczeń niestanowiących drogi komunikacji ogólnej, służącej celom ewakuacji, można stosować materiały o klasie reakcji na ogień i o wskaźniku toksykometrycznym (WLC50SM):","options": {"a": "D-s2, d0; WLC50SM ≤ 15,","b": "D-s2, d0; 15 < WLC50SM ≤ 40,","c": "E-d2; WLC50SM > 40."},"category": "Ewakuacja"},{"id": 487,"q": "Uzgodnienia pod względem zgodności z wymaganiami ochrony przeciwpożarowej nie wymaga projekt techniczny wchodzący w skład projektu budowlanego, o którym mowa w ustawie z dnia 7 lipca 1994 r. Prawo budowlane:","options": {"a": "budynku niskiego (N) zawierającego strefę pożarową o powierzchni 1500 m2, zakwalifikowaną do kategorii zagrożenia ludzi ZL III, obejmującą kondygnację nadziemną inną niż pierwsza,","b": "obiektu budowlanego innego niż budynek, przeznaczonego do użyteczności publicznej, w którym przewiduje się możliwość jednoczesnego przebywania w strefie pożarowej 80 osób na powierzchni 1800 m2,","c": "tunelu technologicznego o długości ponad 100 m nieprzeznaczonego do ruchu pojazdów lub pieszych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 488,"q": "W strefie pożarowej z odpadami stałymi znajdującej się poza budynkiem, chronionej przez stałe samoczynne urządzenie gaśnicze wodne, maksymalna dopuszczalna powierzchnia sekcji magazynowej o gęstości obciążenia ogniowego 1000 MJ/m2 wynosi:","options": {"a": "600 m2,","b": "800 m2,","c": "1000 m2."},"category": "Pozostałe / ogólne"},{"id": 489,"q": "Zgodnie ze Specyfikacją Techniczną PKN-CEN/TS 54-14:2020 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, odległość punktowej czujki dymu od ściany pomieszczenia użytkowego nie może wynosić więcej niż:","options": {"a": "3,2 m,","b": "4,4 m,","c": "6,4 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 490,"q": "Maksymalna dopuszczalna powierzchnia strefy pożarowej podziemnego garażu zamkniętego, w której zastosowano stałe samoczynne urządzenia gaśnicze wodne oraz instalację wentylacji oddymiającej uruchamianą za pomocą systemu wykrywania dymu, wynosi:","options": {"a": "5 000 m2,","b": "10 000 m2,","c": "12 500 m2."},"category": "Strefy pożarowe i oddzielenia"},{"id": 491,"q": "Droga pożarowa do budynku produkcyjnego z pomieszczeniem zagrożonym wybuchem, stanowiącego jedną strefę pożarową o gęstości obciążenia ogniowego 400 MJ/m2 i powierzchni 12 000 m2, na terenie działki, na której jest usytuowany ten budynek, w miejscu jej przebiegu wzdłuż dłuższego boku budynku powinna posiadać szerokość co najmniej:","options": {"a": "3,5 m,","b": "4 m,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe – do budynku nie wymaga się doprowadzenia drogi pożarowej."},"category": "Zagrożenie wybuchem"},{"id": 492,"q": "W budynku hali sportowej o wysokości 14 m i jednej kondygnacji nadziemnej, w której może jednocześnie przebywać 100 osób niebędących jej stałymi użytkownikami, belki wykonane z drewna klejonego warstwowo, stanowiące konstrukcję dachu, powinny spełniać łącznie co najmniej następujące wymagania:","options": {"a": "klasa odporności ogniowej R 30, wymiary przekroju poprzecznego 14 cm, klasa reakcji na ogień D-s1,d0,","b": "klasa odporności ogniowej R 15, wymiary przekroju poprzecznego 14 cm, klasa reakcji na ogień D-s1,d0,","c": "klasa odporności ogniowej R 30, wymiary przekroju poprzecznego 12 cm, klasa reakcji na ogień D-s2,d0."},"category": "Odporność ogniowa i klasy budynków"},{"id": 493,"q": "Liczba zbiorników podziemnych z gazem płynnym o pojemności 10 m3 każdy, służących do magazynowania gazu płynnego w stacji paliw płynnych, nie może być większa niż:","options": {"a": "1,","b": "2,","c": "4."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 494,"q": "Zgodnie z Polską Normą PN-EN 13501-4:2016-07 Klasyfikacja ogniowa wyrobów budowlanych i elementów budynków – Część 4: Klasyfikacja na podstawie wyników badań odporności ogniowej elementów systemów kontroli rozprzestrzeniania dymu, klasyfikacja HOT 400/30 w przypadku ognioodpornej klapy odcinającej do wielostrefowych systemów kontroli rozprzestrzeniania się dymu oznacza, że:","options": {"a": "przyrost temperatury po stronie nienagrzewanej jest nie większy niż 400°C,","b": "klapa odcinająca ma zdolność do wykonania 30 cykli otwierania i zamykania w warunkach oddziaływania temperatury niższej niż 400°C,","c": "klapa odcinająca ma zdolność do otwierania i zamykania przez 30 minut w warunkach oddziaływania temperatury niższej niż 400°C."},"category": "Odporność ogniowa i klasy budynków"},{"id": 495,"q": "Budynek tymczasowy średniowysoki (SW) stanowiący jedną strefę pożarową o powierzchni 2500 m2, w którym przewiduje się możliwość jednoczesnego przebywania 60 osób niebędących jego stałymi użytkownikami, powinien być wyposażony w:","options": {"a": "instalację wodociągową przeciwpożarową z hydrantami 25,","b": "instalację wodociągową przeciwpożarową z hydrantami 52,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 496,"q": "Zgodnie z Polską Normą PN-B-02857:2017-04 Ochrona przeciwpożarowa – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne, w przypadku przeciwpożarowego zbiornika wodnego o pojemności 300 m3 zasilanego z innego źródła niż sieć wodociągowa przeciwpożarowa, źródło zasilające powinno napełnić cały zbiornik po jego opróżnieniu w czasie nie dłuższym niż:","options": {"a": "36 h,","b": "48 h,","c": "72 h."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 497,"q": "Klatki schodowe stanowiące drogi ewakuacyjne w budynku o wysokości 28 m przeznaczonym do zakwaterowania osób osadzonych:","options": {"a": "powinny być wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu, uruchamiane samoczynnie za pomocą systemu wykrywania dymu,","b": "powinny być wyposażone w urządzenia zapobiegające ich zadymieniu,","c": "nie muszą być wyposażone w urządzenia zapobiegające zadymieniu lub służące do usuwania dymu."},"category": "Ewakuacja"},{"id": 498,"q": "W budynku hotelu o wysokości 60 m:","options": {"a": "dopuszcza się prowadzenie ewakuacji tylko do jednej klatki schodowej, jeżeli powierzchnia wewnętrzna kondygnacji nie przekracza 750 m2,","b": "dopuszcza się prowadzenie ewakuacji tylko do jednej klatki schodowej na kondygnacji stanowiącej odrębną strefę pożarową PM,","c": "należy zapewnić możliwość ewakuacji do co najmniej dwóch klatek schodowych."},"category": "Ewakuacja"},{"id": 499,"q": "W dwukondygnacyjnym budynku produkcyjnym o wysokości 27 m, stanowiącym jedną strefę pożarową o gęstości obciążenia ogniowego 1800 MJ/m2, w którym zastosowano stałe samoczynne urządzenia gaśnicze wodne oraz samoczynne urządzenia oddymiające, strop antresoli przeznaczonej do użytku 30 osób, znajdującej się w pomieszczeniu produkcyjnym, powinien mieć klasę odporności ogniowej co najmniej:","options": {"a": "REI 15,","b": "REI 30,","c": "REI 60."},"category": "Odporność ogniowa i klasy budynków"},{"id": 500,"q": "W budynku biurowym wysokim (W), w którym każda kondygnacja o powierzchni wewnętrznej 1500 m2 stanowi odrębną strefę pożarową, do zasilania w wodę instalacji wodociągowej przeciwpożarowej może być zastosowany zbiornik o pojemności 30 m3, w przypadku:","options": {"a": "zapewnienia jego zasilania w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s,","b": "zapewnienia jego zasilania w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 15 dm3/s,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe – nie uwzględniają wymogu dotyczącego wyprowadzenia w elewacji budynku, od strony drogi pożarowej, dodatkowej nasady o średnicy 75 mm, umożliwiającej zasilanie instalacji wodociągowej przeciwpożarowej z samochodów gaśniczych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 501,"q": "Minimalna dopuszczalna odległość budynku biurowego o wysokości 18 m, który jest w całości chroniony przez stałe samoczynne urządzenia gaśnicze wodne, od dwukondygnacyjnego budynku PM o wysokości 9 m, stanowiącego jedną strefę pożarową PM o gęstości obciążenia ogniowego 3500 MJ/m2, niewyposażonego w stałe samoczynne urządzenia gaśnicze wodne, w przypadku, gdy w obu budynkach: ściany zewnętrzne są nierozprzestrzeniające ognia i posiadają na powierzchni 75 % klasę odporności ogniowej EI 30, przekrycia dachów są klasy BROOF (t1) oraz brak jest pomieszczeń zagrożonych wybuchem, wynosi:","options": {"a": "11,25 m,","b": "15 m,","c": "22,5 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 502,"q": "Wydajność wentylacji służącej do usuwania dymu i ciepła z tunelu służącego do przeprowadzenia drogi publicznej, w którym do ruchu pojazdów dopuszczono autobusy oraz inne pojazdy o masie całkowitej do 20 t, powinna być ustalona przy uwzględnieniu całkowitej mocy pożaru projektowego nie mniejszej niż:","options": {"a": "5 MW,","b": "30 MW,","c": "50 MW."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 503,"q": "Maksymalna dopuszczalna powierzchnia strefy pożarowej PM o gęstości obciążenia ogniowego 1000 MJ/m2 z pomieszczeniem zagrożonym wybuchem, wyposażonej w samoczynne urządzenia oddymiające, obejmującej wyłącznie najwyższą kondygnację nadziemną w trzykondygnacyjnym budynku PM o wysokości 13 m, wykonanym z elementów nierozprzestrzeniających ognia, niewyposażonym w stałe samoczynne urządzenie gaśnicze wodne, wynosi:","options": {"a": "2000 m2,","b": "3000 m2,","c": "4000 m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 504,"q": "Sieć wodociągowa przeciwpożarowa zasilana ze zbiornika wieżowego powinna zapewniać:","options": {"a": "wydajność nie mniejszą niż 5 dm3/s i ciśnienie w hydrancie zewnętrznym nie mniejsze niż 0,1 MPa, przez co najmniej 1 godzinę,","b": "wydajność nie mniejszą niż 5 dm3/s i ciśnienie w hydrancie zewnętrznym nie mniejsze niż 0,1 MPa, przez co najmniej 2 godziny,","c": "wydajność nie mniejszą niż 10 dm3/s i ciśnienie w hydrancie zewnętrznym nie mniejsze niż 0,2 MPa, przez co najmniej 2 godziny."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 505,"q": "Dla zapewnienia możliwości intensywnego czerpania wody do celów przeciwpożarowych na sieciach wodociągowych o średnicy nominalnej nie mniejszej niż DN 250 powinny być instalowane hydranty nadziemne, spełniające następujące wymaganie:","options": {"a": "średnica nominalna hydrantu powinna wynosić DN 125 na sieci rozgałęzieniowej,","b": "wydajność nominalna przy ciśnieniu nominalnym 0,2 MPa mierzonym na zaworze hydrantowym podczas poboru wody nie może być mniejsza niż 15 dm3/s,","c": "przy hydrancie należy przewidzieć stanowisko czerpania wody o wymiarach zapewniających swobodny dostęp do hydrantu."},"category": "Ewakuacja"},{"id": 506,"q": "Elementami systemu sygnalizacji pożarowej, które nie wymagają uzyskania dopuszczenia do użytkowania w formie świadectwa dopuszczenia wydanego przez instytut badawczy Państwowej Straży Pożarnej (CNBOP-PIB) są:","options": {"a": "czujki punktowe dymu,","b": "sygnalizatory optyczne,","c": "ręczne ostrzegacze pożarowe."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 507,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, hydrofor stosowany jako pojedyncze zasilanie wodą, powinien być wyposażony w urządzenia do automatycznego utrzymywania ciśnienia powietrza i poziomu wody, które powinny być w stanie całkowicie napełnić hydrofor i zapewnić wymagane ciśnienie w hydroforze, w czasie nie dłuższym niż:","options": {"a": "4 godziny,","b": "8 godzin,","c": "12 godzin."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 508,"q": "Wymagana pojemność zbiornika wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla strefy pożarowej z odpadami stałymi poza budynkiem, o powierzchni 1500 m2 i gęstości obciążenia ogniowego 1000 MJ/m2, w przypadku braku możliwości zapewnienia wymaganej ilości wody do celów przeciwpożarowych z sieci wodociągowej przeciwpożarowej, wynosi:","options": {"a": "200 m3,","b": "288 m3,","c": "100 m3."},"category": "Strefy pożarowe i oddzielenia"},{"id": 509,"q": "Zapewnienie dojścia i dojazdu, przystosowanych do prowadzenia działań ratowniczych przez jednostki ochrony przeciwpożarowej, jest wymagane do budowli rolniczej, w której:","options": {"a": "występuje strefa pożarowa o gęstości obciążenia ogniowego 2000 MJ/m2 i powierzchni 800 m2,","b": "występuje strefa pożarowa o gęstości obciążenia ogniowego 800 MJ/m2 i powierzchni 2000 m2,","c": "występuje wewnątrz budowli strefa zagrożenia wybuchem, a gęstość obciążenia ogniowego w strefie pożarowej z tą strefą zagrożenia wybuchem wynosi 400 MJ/m2."},"category": "Ewakuacja"},{"id": 510,"q": "Zgodnie z Polską Norma PN-EN 1838:2025-05 Zastosowanie oświetlenia – Oświetlenie awaryjne budynków, poziom natężenia oświetlenia w przypadku strefy otwartej, z wyłączeniem obwodowego pasa o szerokości 0,5 m, powinien wynosić na poziomie podłogi co najmniej:","options": {"a": "0,5 lx,","b": "0,5 lx, z wyjątkiem pomieszczeń audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, w obrębie których natężenie to powinno wynosić co najmniej 5 lx,","c": "0,5 lx, z wyjątkiem pomieszczeń audytoriów, sal konferencyjnych, czytelni, lokali rozrywkowych oraz sal sportowych, przeznaczonych dla ponad 200 osób, w obrębie których natężenie to powinno wynosić co najmniej 15 lx."},"category": "Pozostałe / ogólne"},{"id": 511,"q": "Zgodnie z Polską Normą PN-EN 12101-13:2022-09 Systemy kontroli rozprzestrzeniania dymu i ciepła; Cześć 13: Systemy różnicowania ciśnień (SRC); Projektowanie i metody obliczeniowe, instalowanie, badania okresowe i konserwacja, w projektowanym budynku biurowym wysokościowym (WW) chronionym przez instalację tryskaczową z tryskaczami o temperaturze zadziałania 68° i RTI < 50, należy zastosować system różnicowania ciśnień, zapewniający:","options": {"a": "różnicę ciśnień pomiędzy klatką schodową a przestrzenią użytkową co najmniej 50 Pa oraz prędkość przepływu powietrza przez otwór drzwiowy między klatką schodową a przestrzenią użytkową co najmniej 2 m/s,","b": "różnicę ciśnień pomiędzy klatką schodową a przestrzenią użytkową co najmniej 30 Pa oraz prędkość przepływu powietrza przez otwór drzwiowy między klatką schodową a przestrzenią użytkową co najmniej 2 m/s,","c": "różnicę ciśnień pomiędzy klatką schodową a przestrzenią użytkową co najmniej 30 Pa oraz prędkość przepływu powietrza przez otwór drzwiowy między klatką schodową a przestrzenią użytkową co najmniej 1 m/s."},"category": "Odporność ogniowa i klasy budynków"},{"id": 512,"q": "Zgodnie ze Specyfikacją Techniczną PKN-CEN/TS 54-14:2020 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, odległość punktowej czujki ciepła od otworu wentylacji nawiewnej, w którym prędkość nawiewanego powietrza do pomieszczenia wynosi więcej niż 1 m/s, nie może być mniejsza niż:","options": {"a": "0,5 m,","b": "1 m,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe – wymagania dotyczące minimalnej odległości czujki punktowej od otworu wentylacyjnego nie dotyczą czujek ciepła."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 513,"q": "W przypadku tunelu służącego do przeprowadzenia drogi publicznej, wymagana w nim wentylacja mechaniczna wykorzystywana do usuwania dymu i ciepła, powinna zapewniać prędkość przepływu powietrza w tunelu:","options": {"a": "nie większą niż 5 m/s,","b": "większą niż 10 m/s,","c": "nie większą niż 10 m/s."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 514,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, tryskacze wiszące nie powinny być przyłączane bezpośrednio do przewodów o średnicy większej niż:","options": {"a": "50 mm w przypadku przewodów z izolacją,","b": "65 mm,","c": "80 mm."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 515,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, źródło wody powinno być w stanie ponownie napełnić zbiornik z zapasem wody dla urządzeń tryskaczowych OH:","options": {"a": "w czasie nie dłuższym niż 24 godziny,","b": "w czasie nie dłuższym niż 36 godzin,","c": "do 50% w czasie nie dłuższym niż 48 godzin."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 516,"q": "Zgodnie z Polską Normą PN-EN 15004-1:2025-05 Stałe urządzenia gaśnicze – Urządzenia gaśnicze gazowe – Część 1: Projektowanie, montaż i konserwacja, urządzenie zatrzymujące (przycisk „Stop Gaszenia”) należy lokalizować:","options": {"a": "wewnątrz i na zewnątrz zabezpieczanego pomieszczenia, przy wejściu do pomieszczenia oraz przy wyjściu ewakuacyjnym z pomieszczenia,","b": "na zewnątrz zabezpieczanego pomieszczenia, przy wejściu do pomieszczenia,","c": "wewnątrz zabezpieczanego pomieszczenia, przy wyjściu ewakuacyjnym z pomieszczenia."},"category": "Ewakuacja"},{"id": 517,"q": "W budynku użyteczności publicznej o wysokości 64 m, zakwalifikowanym do kategorii zagrożenia ludzi ZL III, biegi i spoczniki schodów klatki schodowej służącej do celów ewakuacji, spełniającej obowiązujące przepisy techniczno-budowlane:","options": {"a": "powinny być wykonane z materiałów niepalnych oraz mieć klasę odporności ogniowej co najmniej R 60,","b": "mogą być wykonane z materiałów palnych i powinny mieć klasę odporności ogniowej co najmniej R 60,","c": "powinny być wykonane z materiałów niepalnych, a nie dotyczą ich wymagania klasy odporności ogniowej."},"category": "Ewakuacja"},{"id": 518,"q": "Zbiorniki gazu płynnego znajdujące się na stacji gazu płynnego powinny być usytuowane w odległości od granicy lasu nie mniejszej niż:","options": {"a": "10 m,","b": "20 m,","c": "30 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 519,"q": "Zgodnie z Polską Normą PN-EN 81-72:2020-12 Zasady bezpieczeństwa dotyczące budowy i instalowania dźwigów – Szczególne zastosowania dźwigów towarowo-osobowych – Część 72: Dźwigi dla straży pożarnej, klapa awaryjna, służąca do uwalniania strażaków uwięzionych w kabinie dźwigu dla straży pożarnej o udźwigu nominalnym 630 kg, powinna posiadać wymiary otworu w świetle co najmniej:","options": {"a": "0,4 m x 0,5 m,","b": "0,6 m x 0,6 m,","c": "0,5 m x 0,7 m."},"category": "Pozostałe / ogólne"},{"id": 520,"q": "Odległość zbiornika biogazu rolniczego od pomieszczeń przeznaczonych na pobyt ludzi znajdujących się w budynku produkcyjnym o gęstości obciążenia ogniowego 1000 MJ/m2, powinna wynosić co najmniej:","options": {"a": "8 m,","b": "15 m,","c": "20 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 521,"q": "W budynku hotelu o wysokości 12,5 m, który ma tylko cztery kondygnacje nadziemne, stanowiącym jako całość jedną strefę pożarową, przepusty instalacyjne o średnicy powyżej 4 cm występujące w ścianach pomieszczeń mieszkalnych (hotelowych), powinny mieć klasę odporności ogniowej co najmniej:","options": {"a": "EI 30,","b": "EI 60,","c": "nie stawia się wymagań w zakresie klasy odporności ogniowej."},"category": "Odporność ogniowa i klasy budynków"},{"id": 522,"q": "Zgodnie z Polską Normą PN-B 02877-4:2025-07 Ochrona przeciwpożarowa budynków – Systemy do grawitacyjnego odprowadzania dymu i ciepła – Część 4: Zasady projektowania, w budynku magazynowym przy maksymalnej powierzchni strefy dymowej ASD nieprzekraczającej 4000 m2, maksymalna odległość między elementami ograniczającymi strefę dymową nie powinna przekraczać:","options": {"a": "80 metrów,","b": "8 × H, gdzie H to wysokość strefy dymowej,","c": "sumy długości dwóch najdłuższych boków elementów ograniczających strefę dymową podzielonej przez 2, lecz nie więcej niż 60 metrów."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 523,"q": "Ukrycie kategorii U-3 powinno stanowić strefę pożarową wydzieloną przeciwpożarowo w sposób zabezpieczający przed rozprzestrzenianiem się pożaru do jej wnętrza przy oddziaływaniu pożaru, określonego w odniesieniu do krzywej pożaru standardowego, przez czas nie krótszy niż:","options": {"a": "60 minut,","b": "120 minut,","c": "240 minut."},"category": "Odporność ogniowa i klasy budynków"},{"id": 524,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, tryskacze w regałach, w poziomach pośrednich, nie powinny być zasilane z tego samego stanowiska kontrolno-alarmowego co tryskacze stropowe, w przypadku gdy:","options": {"a": "liczba tryskaczy w regałach, w poziomach pośrednich, przekracza 50,","b": "liczba poziomów pośrednich, w których zainstalowane są tryskacze jest większa niż 3,","c": "intensywność zraszania tryskaczy stropowych jest większa niż 7,5 mm/min."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 525,"q": "Biegi i spoczniki klatki schodowej służącej do ewakuacji z budynku hotelu o dwóch kondygnacjach nadziemnych i wysokości wynoszącej 9 m, która jest obudowana i zamknięta drzwiami o klasie odporności ogniowej co najmniej EI 30 S, powinny być wykonane z materiałów:","options": {"a": "palnych, przy czym co najmniej trudno zapalnych, i mieć klasę odporności ogniowej co najmniej R 30,","b": "niepalnych i mieć klasę odporności ogniowej co najmniej R 60,","c": "niepalnych, przy czym dopuszcza się występowanie elementów nośnych wykonanych z drewna litego czterostronnie struganego z fazowanymi narożnikami lub drewna klejonego warstwowo, o klasie reakcji na ogień nie niższej niż D z dodatkowymi klasyfikacjami s1, d0 lub s2, d0, pod warunkiem wykonania biegów i spoczników w klasie odporności ogniowej co najmniej R 90."},"category": "Ewakuacja"},{"id": 526,"q": "Średnica nominalna (DN) przewodu wodociągowego wykonanego z rur stalowych, na którym przewiduje się instalowanie hydrantów zewnętrznych przeciwpożarowych, przy modernizacji istniejącego wodociągu o wydajności 5 dm3/s w jednostce osadniczej o liczbie mieszkańców nieprzekraczającej 2000, powinna wynosić co najmniej:","options": {"a": "DN 80,","b": "DN 100 w odgałęzieniach sieci obwodowej,","c": "DN 125 w sieci rozgałęzieniowej."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 527,"q": "W strefie pożarowej PM o gęstości obciążenia ogniowego powyżej 4000 MJ/m² bez pomieszczenia zagrożonego wybuchem, która jest chroniona przez system sygnalizacji pożarowej i stałe samoczynne urządzenie gaśnicze wodne, dopuszczalna długość dojścia ewakuacyjnego na poziomej drodze ewakuacyjnej przy jednym dojściu wynosi:","options": {"a": "30 m,","b": "40 m,","c": "45 m."},"category": "Ewakuacja"},{"id": 528,"q": "Ściana zewnętrzna w projektowanym sześciokondygnacyjnym budynku o wysokości 18 m, zakwalifikowanym w całości do kategorii zagrożenia ludzi ZL III, która tworzy kąt 100° ze ścianą zewnętrzną jedynej ewakuacyjnej klatki schodowej w tym budynku, mającą na powierzchni 50% klasę odporności ogniowej EI 60 (o↔i) a na pozostałej powierzchni otwory przeszklone szkłem zwykłym, powinna w pasie terenu o szerokości co najmniej:","options": {"a": "4 m mieć klasę odporności ogniowej co najmniej REI 120 i być wykonana z materiałów niepalnych,","b": "6 m mieć klasę odporności ogniowej co najmniej REI 60 i być co najmniej nierozprzestrzeniająca ognia,","c": "6 m mieć klasę odporności ogniowej co najmniej REI 60 i być wykonana z materiałów niepalnych."},"category": "Ewakuacja"},{"id": 529,"q": "Wymagana ilość wody do celów przeciwpożarowych do zewnętrznego gaszenia pożaru dla budynku magazynowego, stanowiącego jedną strefę pożarową o gęstości obciążenia ogniowego 3900 MJ/m2 i powierzchni 2100 m2, zgromadzona w przeciwpożarowym zbiorniku wodnym, wynosi:","options": {"a": "216 m3,","b": "300 m3,","c": "432 m3."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 530,"q": "Zgodnie z Polską Normą PN-B 02877-4:2025-07 Ochrona przeciwpożarowa budynków – Systemy do grawitacyjnego odprowadzania dymu i ciepła – Część 4: Zasady projektowania, powierzchnia efektywna otworu służącego do napływu powietrza kompensacyjnego to:","options": {"a": "wynik przemnożenia powierzchni geometrycznej otworu przez współczynnik wypływu przez otwór (Co),","b": "wynik przemnożenia powierzchni czynnej otworu przez współczynnik korygujący (Cz),","c": "wynik przemnożenia powierzchni geometrycznej otworu przez współczynnik korygujący (Cz)."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 531,"q": "W budynku mieszkalnym wielorodzinnym, który ma 4 kondygnacje nadziemne i jedną kondygnację podziemną, pomieszczenie z rozdzielnią elektryczną zasilającą urządzenia mające funkcjonować w czasie pożaru, usytuowane na kondygnacji podziemnej, powinno:","options": {"a": "być wydzielone ścianami i stropem spełniającymi wymagania szczelności i izolacyjności ogniowej co najmniej przez czas wymagany do uruchomienia i działania zasilanych urządzeń,","b": "stanowić odrębną strefę pożarową wydzieloną ścianami i stropem oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 60,","c": "stanowić odrębną strefę pożarową wydzieloną ścianami i stropem oddzielenia przeciwpożarowego o klasie odporności ogniowej co najmniej REI 120."},"category": "Odporność ogniowa i klasy budynków"},{"id": 532,"q": "W projektowanym dwukondygnacyjnym budynku biurowym o wysokości 30 m korytarz o długości 80 m, stanowiący drogę ewakuacyjną, powinien:","options": {"a": "być podzielony na odcinki nie dłuższe niż 50 m przy zastosowaniu przegród z drzwiami dymoszczelnymi,","b": "mieć przestrzeń między sufitem podwieszonym i stropem podzieloną co 50 m przegrodami wykonanymi z materiałów niepalnych,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe."},"category": "Ewakuacja"},{"id": 533,"q": "Nachylenie podłużne drogi pożarowej przebiegającej wzdłuż dłuższego boku budynku użyteczności publicznej wysokiego (W), która przy tym boku ma przebieg prostoliniowy, może wynosić:","options": {"a": "5°,","b": "1 m w pionie na każde 20 m w poziomie,","c": "odpowiedzi w lit. a) i b) są nieprawidłowe."},"category": "Drogi pożarowe i dojazd"},{"id": 534,"q": "W wysokim (W) budynku szpitala dopuszcza się prowadzenie ewakuacji tylko do jednej klatki schodowej, jeżeli:","options": {"a": "powierzchnia wewnętrzna kondygnacji nie przekracza 750 m2,","b": "budynek jest wyposażony w stałe samoczynne urządzenia gaśnicze wodne,","c": "odpowiedzi a) i b) są nieprawidłowe."},"category": "Ewakuacja"},{"id": 535,"q": "Zgodnie ze Specyfikacją Techniczną PKN CEN/TS 54-14:2020-09 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji maksymalna wysokość pomieszczenia, na jakiej można instalować punktową czujkę płomienia, wynosi:","options": {"a": "9 m,","b": "25 m,","c": "45 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 536,"q": "Do zasilania w wodę instalacji wodociągowej przeciwpożarowej w budynku wysokościowym (WW) o wysokości 90 m, który na wysokości powyżej 12 m zawiera jedynie strefy pożarowe zakwalifikowane do kategorii zagrożenia ludzi ZL IV o powierzchni powyżej 750 m2, w którym na elewacji od strony drogi pożarowej, wyprowadzono dodatkową nasadę o średnicy 75 mm, umożliwiającą zasilanie instalacji wodociągowej przeciwpożarowej z samochodów gaśniczych, powinien być zastosowany zbiornik o zapasie wody do celów przeciwpożarowych co najmniej:","options": {"a": "50 m3,","b": "25 m3 w przypadku zapewnienia zasilania tego zbiornika w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 15 dm3/s,","c": "6 m3 w przypadku zapewnienia zasilania tego zbiornika w wodę z zewnętrznej sieci wodociągowej przeciwpożarowej o wydajności nie mniejszej niż 10 dm3/s."},"category": "Odporność ogniowa i klasy budynków"},{"id": 537,"q": "Ze strefy pożarowej garażu o powierzchni 1450 m2, która ma 50 stanowisk postojowych jednopoziomowych oraz jest wyposażona w instalację wentylacji oddymiającej, należy zapewnić ewakuację przez co najmniej:","options": {"a": "jedno wyjście ewakuacyjne,","b": "dwa wyjścia ewakuacyjne, przy czym jednym z tych wyjść może być wjazd lub wyjazd,","c": "dwa wyjścia ewakuacyjne, przy czym jedno z tych wyjść powinno prowadzić do sąsiedniej strefy pożarowej."},"category": "Ewakuacja"},{"id": 538,"q": "Zgodnie z Polską Normą PN-B 02877-4:2025-07 Ochrona przeciwpożarowa budynków – Systemy do grawitacyjnego odprowadzania dymu i ciepła – Część 4: Zasady projektowania, minimalna powierzchnia czynna pojedynczej klapy dymowej w budynkach produkcyjnych i magazynowych nie powinna być mniejsza niż 1,0 m2, a najmniejszy wymiar jej boku nie powinien być większy niż:","options": {"a": "2,0 d0,5, przy czym d stanowi wysokość warstwy dymu wyrażoną w metrach,","b": "1,4 d0,5, przy czym d stanowi wysokość warstwy dymu wyrażoną w metrach,","c": "1,5 d0,5, przy czym d stanowi wysokość warstwy dymu wyrażoną w metrach."},"category": "Oddymianie i wentylacja pożarowa"},{"id": 539,"q": "W średniowysokim (SW) budynku handlowym, zaliczonym do kategorii zagrożenia ludzi ZL I, w którym przewiduje się możliwość detalicznej sprzedaży wyrobów pirotechnicznych widowiskowych, składowanie tych wyrobów należy prowadzić w pomieszczeniu magazynowym, przeznaczonym wyłącznie do tego celu:","options": {"a": "wydzielonym ścianami wewnętrznymi i stropami o klasie odporności ogniowej odpowiednio co najmniej EI 120 i REI 120 i zamykanym drzwiami o klasie odporności ogniowej co najmniej EI 60,","b": "wydzielonym ścianami wewnętrznymi i stropami o klasie odporności ogniowej odpowiednio co najmniej EI 60 i REI 60 i zamykanym drzwiami o klasie odporności ogniowej co najmniej EI 30,","c": "spełniającym wymagania jak dla pomieszczenia zagrożonego wybuchem."},"category": "Odporność ogniowa i klasy budynków"},{"id": 540,"q": "Hydranty 33 nie mogą stanowić punktu poboru wody do celów przeciwpożarowych w:","options": {"a": "garażu zamkniętym obejmującym więcej niż dwie kondygnacje podziemne lub znajdującym się poniżej drugiej kondygnacji podziemnej,","b": "strefie pożarowej PM o gęstości obciążenia ogniowego nieprzekraczającej 500 MJ/m2, w której znajduje się pomieszczenie magazynowe o powierzchni 150 m2 i gęstości obciążenia ogniowego 2000 MJ/m2,","c": "strefie pożarowej ZL III w budynku średniowysokim (SW) przy wejściu do pomieszczenia magazynowego o powierzchni 300 m2 i gęstości obciążenia ogniowego 800 MJ/m2."},"category": "Odporność ogniowa i klasy budynków"},{"id": 541,"q": "Zgodnie z Polską Normą PN-EN 12845+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, tryskacze przyścienne mogą być instalowane:","options": {"a": "w obszarach magazynowania LH i OH,","b": "tylko pod płaskimi sufitami,","c": "powyżej sufitów podwieszonych."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 542,"q": "Zgodnie z Polską Normą PN-B-02857:2017-04 Ochrona przeciwpożarowa – Przeciwpożarowe zbiorniki wodne – Wymagania ogólne, stanowisko czerpnia wody może być usytuowane względem budynku PM zaprojektowanego w klasie odporności pożarowej D, w odległości co najmniej 8 m, jeżeli jego ściana zewnętrzna w pasie terenu o szerokości 16 m określonym od strony stanowiska czerpania wody ma klasę odporności ogniowej co najmniej:","options": {"a": "E 15,","b": "EI 15,","c": "REI-M 120."},"category": "Odporność ogniowa i klasy budynków"},{"id": 543,"q": "Odległość silosów na zboże i pasze o pojemności 150 ton od granicy działki sąsiedniej powinna wynosić co najmniej:","options": {"a": "4 m,","b": "8 m,","c": "15 m."},"category": "Pozostałe / ogólne"},{"id": 544,"q": "W pomieszczeniu sali kinowej z widownią dla 300 osób liczba siedzeń w jednym rzędzie przyściennym, przy zapewnionym odstępie między stałymi elementami siedzeń w rzędach wynoszącym 0,6 m, może wynosić nie więcej niż:","options": {"a": "16,","b": "20,","c": "23."},"category": "Ewakuacja"},{"id": 545,"q": "Zgodnie z Polską Normą PN-EN 12101-13:2022-09 Systemy kontroli rozprzestrzeniania dymu i ciepła – Część 13: Systemy różnicowania ciśnień (SRC) – Projektowanie i metody obliczeniowe, instalowanie, badania okresowe i konserwacja, w budynku wysokim (W) zaliczonym do kategorii zagrożenia ludzi ZL III chronionym instalacją tryskaczową z tryskaczami o RTI > 50 należy stosować system różnicowania ciśnienia:","options": {"a": "klasy 1,","b": "klasy 2,","c": "klasy 3."},"category": "Odporność ogniowa i klasy budynków"},{"id": 546,"q": "Magazyn podręczny, w którym prowadzi się sprzedaż materiałów wybuchowych, broni i amunicji, powinien być zlokalizowany w pomieszczeniu murowanym wydzielonym przeciwpożarowo:","options": {"a": "co najmniej ścianami wewnętrznymi o klasie odporności ogniowej EI 60 i stropami o klasie odporności ogniowej REI 60, zamykanym drzwiami o klasie odporności ogniowej EI 30,","b": "co najmniej ścianami wewnętrznymi i stropami o klasie odporności ogniowej REI 120, zamykanym drzwiami o klasie odporności ogniowej EI 60,","c": "zawsze jako odrębna strefa pożarowa według klasy odporności pożarowej budynku."},"category": "Odporność ogniowa i klasy budynków"},{"id": 547,"q": "Odległość pomieszczeń przeznaczonych na pobyt ludzi w budynku biurowym od silosu na pszenicę o pojemności 50 ton powinna wynosić co najmniej:","options": {"a": "8 m,","b": "10 m,","c": "15 m."},"category": "Pozostałe / ogólne"},{"id": 548,"q": "Podczas dokonywania oceny zagrożenia wybuchem w pomieszczeniu należy wyznaczyć strefę zagrożenia wybuchem, jeżeli może w nim występować mieszanina wybuchowa:","options": {"a": "o objętości co najmniej 10 dm3 w zwartej przestrzeni,","b": "o objętości co najmniej 1 dm3 w zwartej przestrzeni,","c": "z taką ilością palnych gazów, par, mgieł lub pyłów, której wybuch może spowodować przyrost ciśnienia w tym pomieszczeniu przekraczający 5 kPa."},"category": "Zagrożenie wybuchem"},{"id": 549,"q": "W strefie zagrożenia wybuchem 21 stosuje się urządzenia przeznaczone do użytku w przestrzeniach zagrożonych wybuchem:","options": {"a": "tylko kategorii 1,","b": "kategorii 1 lub 2,","c": "kategorii 1, 2 lub 3."},"category": "Zagrożenie wybuchem"},{"id": 550,"q": "Zgodnie ze Specyfikacją Techniczną PKN CEN/TS 54-14:2020-09 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji maksymalna odległość od narożnika pomieszczenia, w którym można zamontować punktową czujkę ciepła, wynosi:","options": {"a": "3,2 m,","b": "4,4 m,","c": "4,5 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 551,"q": "Maszynownie wentylacyjne i klimatyzacyjne, z wyjątkiem obudowy urządzeń instalowanych ponad dachem budynku, powinny być wydzielone ścianami o klasie odporności ogniowej co najmniej EI 60 i zamykane drzwiami o klasie odporności ogniowej co najmniej EI 30 w budynku:","options": {"a": "mieszkalnym o wysokości 13 m i czterech kondygnacjach nadziemnych,","b": "magazynowym o gęstości obciążenia ogniowego powyżej 4000 MJ/m2, wysokości 14 m i dwóch kondygnacjach nadziemnych,","c": "biurowym o wysokości 11 m i trzech kondygnacjach nadziemnych."},"category": "Odporność ogniowa i klasy budynków"},{"id": 552,"q": "Odległość ściany zewnętrznej wznoszonego budynku wolnostojącego o jednej kondygnacji nadziemnej, przeznaczonego do wykonywania działalności usługowej i handlowej, o powierzchni zabudowy 240 m2 i wysokości 4 m, z przekryciem dachu klasy FROOF (t1), od granicy sąsiedniej niezabudowanej działki budowlanej, nieobjętej miejscowym planem zagospodarowania przestrzennego, musi wynosić co najmniej:","options": {"a": "3 m,","b": "4 m,","c": "6 m."},"category": "Odporność ogniowa i klasy budynków"},{"id": 553,"q": "Zgodnie Polską Normą PN-EN 12845-1+A1:2020 Stałe urządzenia gaśnicze – Automatyczne urządzenia tryskaczowe – Projektowanie, instalowanie i konserwacja, przy projektowaniu stałych urządzeń gaśniczych wodnych tryskaczowych należy wybrać tryskacze o znamionowych temperaturach zadziałania bliskich spodziewanym najwyższym temperaturom otoczenia powiększonych od najwyższych temperatur otoczenia o minimum:","options": {"a": "25o C,","b": "30o C,","c": "35o C."},"category": "Stałe urządzenia gaśnicze (tryskacze, gazowe, mgłowe)"},{"id": 554,"q": "Pomiędzy zbiornikiem naziemnym z dachem stałym o pojemności 20 000 m3, przeznaczonym do magazynowania paliwa lotniczego (nafty lotniczej), znajdującym się na terenie bazy paliw płynnych, a granicą lasu należy zapewnić pas terenu ochronnego o szerokości nie mniejszej niż:","options": {"a": "80 m,","b": "100 m,","c": "(-) - nie stawia się wymagań w tym zakresie."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 555,"q": "W budynku mieszkalnym wielorodzinnym o 9 kondygnacjach nadziemnych i wysokości 32 m, klasa odporności ogniowej ścian wewnętrznych oddzielających mieszkania od innych mieszkań położonych na wysokości powyżej 25 m od poziomu terenu, powinna wynosić co najmniej:","options": {"a": "EI 15,","b": "EI 30,","c": "EI 60."},"category": "Odporność ogniowa i klasy budynków"},{"id": 556,"q": "Zgodnie ze Specyfikacją Techniczną PKN CEN/TS 54-14:2020-09 Systemy sygnalizacji pożarowej – Część 14: Wytyczne planowania, projektowania, instalowania, odbioru, eksploatacji i konserwacji, maksymalny promień działania czujki dymu zainstalowanej w pobliżu kalenicy dachu o nachyleniu połaci wynoszącym 30°, wynosi:","options": {"a": "6,2 m,","b": "7,75 m,","c": "8,06 m."},"category": "SSP, DSO i sygnalizacja pożarowa"},{"id": 557,"q": "Tunel o długości 1000 m wyposaża się w hydranty zewnętrzne nadziemne o średnicy nominalnej DN80, usytuowane w pobliżu wjazdów do tunelu i w tunelu, w odległościach nieprzekraczających:","options": {"a": "250 m,","b": "150 m,","c": "100 m."},"category": "Instalacje wodne, hydranty, zaopatrzenie w wodę"},{"id": 558,"q": "Drzwi stanowiące wyjście ewakuacyjne lub znajdujące się na drodze służącej do ewakuacji z miejsca doraźnego schronienia o pojemności 200 osób, powinny mieć szerokość w świetle ościeżnicy nie mniejszą niż:","options": {"a": "0,8 m,","b": "0,9 m,","c": "1,2 m."},"category": "Ewakuacja"},{"id": 559,"q": "Zgodnie z Polską Normą PN-EN 81-72:2020 Zasady bezpieczeństwa dotyczące budowy i instalowania dźwigów – Szczególne zastosowania dźwigów osobowych i dźwigów towarowo-osobowych – Część 72: Dźwigi dla straży pożarnej, w dźwigu dla straży pożarnej szerokość w świetle wejścia do kabiny dźwigu powinna wynosić co najmniej:","options": {"a": "0,8 m,","b": "0,9 m,","c": "1,0 m."},"category": "Pozostałe / ogólne"},{"id": 560,"q": "Przeciwpożarowe zaopatrzenie w wodę do zewnętrznego gaszenia pożaru dla budynku magazynowego, w którym są przechowywane materiały wybuchowe oraz amunicja, nie może być mniejsze niż:","options": {"a": "10 dm3/s,","b": "15 dm3/s,","c": "20 dm3/s."},"category": "Zagrożenie wybuchem"}];
